window.__D("text/maamarei-admur-hazaken/c006",{"p":[[2100990070,"בחי' מחכמה שבאה בסדר ההשתלשלו' דאבי\"ע כו' אך מה שנק' חכים ומבין כו' הכל להיו' מזה מקור לנבראי' בלבד דהיינו שיהי' מקור לחכמ' ומקור למחשב' שלנו כו' וכמ\"ש כי<sup data-n=\"3251\">16</sup> עמך מקור חיים באורך נראה אור פי' כי עמך כי מקור כל המציאות שלמטה הם בע\"ס דאצי' וגם המה נאצלו ע\"י אותיו' וצמצום כנ\"ל ובאורך נראה אור היינו כי מה שמושג ונראה בנבראי' בבחי' גבול הרי הוא בא מאורך שהמשיך למעלה באצי' להיו' נק' חכים ומבין כו' וזהו באורך נראה אור אור הנולד מתוך האור שנק' הארה דהארה כו' וד\"ל וע\"ד הזה בבחי' החסד כמ\"ש ועושה<sup data-n=\"3252\">17</sup> חסד לאלפים פי' לאלפים שיש אלפים מדרגו' עד שמתהוו' בחי' החסד וכמ\"ש חסד<sup data-n=\"3253\">18</sup> יבנה שצריך החסד לבא לידי בנין ע\"י &lt;רו&gt;\nריבוי צמצומי' באלפים מדרגו' והכל מטעם הנ\"ל משום דמצד עצמו' המאציל הרי לאו מכל אינון מדות כלל ויש להתהוו' החסד שם אחר מיוחד אליו ועד\"ז בשאר המדות הכל באין ע\"י שמות ודרך כלל הם ז' שמות שאינן נמחקי' שם אל בחסד שם אלקי' בגבורה כו' וד\"ל. אך הנה מ\"מ הגם שבאו מדותיו ע\"י צמצום בבחי' שמות שהוא רק לזולתו שיהא נקרא בקריאה על ידם כידוע אעפ\"כ מתאחד אור א\"ס בהם בתכלית היחוד וכמאמר הידוע דאיהו<sup data-n=\"3254\">19</sup> וחיוהי וגרמוהי חד כו' פי' איהו הוא אור א\"ס וחיוהי המה בחי' אורו' די\"ס הנאצלי' וגרמוהי המה בחי' כלים כו' הכל א' כמו עד\"מ האדם בחיו' נפשו שמלובשת באיבריו שמתאחד הוא עם האיברי' והכל נחשב כא' כך גם בחי' התפשטו' ההארה מאור א\"ס בנאצלי' באורו' וכלים ע\"י בחי' השמות הנ\"ל כולם מיוחדי' בו בתכלית וכמ\"ש לך ה' הגדולה והגבורה פי' לך ה' מפני שהמה מיוחדי' בו בתכלית כו' ולכך נקראי' בשם איברי' דמלכא עד\"מ האבר שמתאחד עם האדם כו' מפני שהחיו' מן הנפש מלובש בתוך האבר ומתאחד עמו והיו לאחדים ממש כך בחי' הארת השם שמלובש בחכמה או בחסד כנ\"ל מיוחדי' הם עם המאציל עי\"ז ההתלבשות בתכלית היחוד וד\"ל.\n<b>ובזה</b> יובן ענין רמ\"ח מ\"ע איך שהם נקראי' רמ\"ח אברי' דמלכא דהנה עבודת אברהם הי' תמיד להמשיך אורו' המאציל באורו' וכלים שהם המדו' הגדולה והגבור' כו' מפני שהי' בחי' מרכבה כמאמר האבות<sup data-n=\"3255\">20</sup> הן המרכבה וכמ\"ש בו הלוך<sup data-n=\"3256\">21</sup> ונסוע הנגבה שהלך ממדרג' למדרג' במדרגת האהבה והדביקו' עד שקשר את כל העולם והביא והעלה הכל מבחי' הפירוד לבחי' היחוד דאלקו' וכמ\"ש ואברם<sup data-n=\"3257\">22</sup> כבד מאד במקנה כו' ובעבוד\"ה<sup data-n=\"3258\">*22</sup> רב\"ה כו' ולהיותו בבחי' השפלות והענוה ביותר כמ\"ש ואנכי<sup data-n=\"3259\">23</sup> עפר ואפר באתעדל\"ת<sup data-n=\"3260\">24</sup> זו הי' אתעדל\"ע כמ\"כ להיו' למעלה באלקו' הענוה",[["3251","16","<b>כי עמך מקור חיים</b>: תהלים לו, יד."],["3252","17","<b>ועושה חסד לאלפים</b>: יתרו כ, ו. ואתחנן ה, יו\"ד."],["3253","18","<b>חסד יבנה</b>: תהלים פט, ג."],["3254","19","<b>דאיהו וחיוהי וגרמוהי חד</b>: ת\"ז בהקדמה (יז, ב)."],["3255","20","<b>האבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו."],["3256","21","<b>הלוך ונסוע הנגבה. . ממדרג' למדרג'</b>: לך יב, ט. ראה זהר לך פ, א. פד, א."],["3257","22","<b>ואברם כבד מאד במקנה</b>: לך לך יג, ב."],["3258","*22","<b>ובעבוד\"ה רב\"ה</b>: תולדות כו, יד."],["3259","23","<b>ואנכי עפר ואפר</b>: וירא יח, כז."],["3260","24","<b>באתעדל\"ת זו הי' אתעלדל\"ע</b>: ראה זהר לך לך פח, א."]]],[2100990071,"והשפלו' והוא להיו' במקום<sup data-n=\"3261\">25</sup> גדולתו גודל ענותונתו להיו' נקרא חכים ומבין כו' ע\"י צמצום השמות הנ\"ל אע\"פ שהיא ירידה ושפלות גדולה כנ\"ל וד\"ל.\n<b>וזהו</b> שאמרו שקיים אברהם כל התורה עד שלא ניתנה כו' שנא' וישמור משמרתי מצוותי חוקותי ותורתי ולכאורה יפלא איך קיים בפ\"מ מצות תרומו' ומעשרו' וכיוצא עד שלא הי' כהן וכן שאר מצות שא\"א שיתקיימו בלתי סיבה הידוע' להם כמו מצות סוכו' ופסח כו' אך הענין הוא שרצונם לומר שקיים<sup data-n=\"3262\">26</sup> כל התורה למעלה ברוחניו' והיינו ע\"י שהמשיך אורו' בכלים כנ\"ל והן הנק' מצות למעלה דהיינו מצות שהקדב\"ה עושה בעצמו וכמאמר הקדב\"ה<sup data-n=\"3263\">27</sup> מניח תפילין מתעטף<sup data-n=\"3264\">28</sup> בציצית כו' הקדב\"ה מבקר<sup data-n=\"3265\">29</sup> חולים כו' וכיוצא בזה וזהו שאמר וישמור משמרתי מצוותי כלומר מצות שלי כמו שהם בבחי' אצילו' והוא להיות על ידם המשכו' אורו' בכלים כמו בחכמה ובחסד כנ\"ל ולפי שמצוותי נק' איברי' דמלכא ע\"כ המה מיוחדי' בו בתכלית וכמאמר דאיהו וחיוהי וגרמוהי חד כו' וכנ\"ל אך יש להבין איך הוא ענין מצות תפילין למעלה לומר שהקדב\"ה מניח תפילין עד שעי\"ז יהי' המשכו' אורו' בכלים כו' וכמ\"כ ענין מצות ביקור חולים איך הוא מבקר חולים כו' הענין הוא בבחי' הרוחניו' למעלה דהנה ענין החולי למעלה בעולמו' עליוני' הוא ענין חולת<sup data-n=\"3266\">30</sup> אהבה מחמת העדר הקירוב כשמשיג באלקו' &lt;רז&gt;\nואינו מתדבק כראוי וכענין כנ\"י בגלותא שאומרת סמכוני<sup data-n=\"3267\">31</sup> באשישות רפדוני בתפוחים כי חולת אהבה אני כו' וכמ\"ש בזוהר<sup data-n=\"3268\">32</sup> משום דבגלות מתרחקת מאד ותגדל בה חולי האהבה כו' והרפואה לחולי זה הוא מה שאומרת סמכוני באשישו' רפדוני בתפוחים שהן עניני אורות רוחניים שמרפאי' כ\"כ עד שמשיבי' את הנפש לחולה זה כו' והוא ענין ביקור חולים שהקדב\"ה מבקר חולים והוא במה שירדפנה בתפוחי' כו' וכיוצא וה\"ז מצות ביקור חולים למעלה בבחי' הרוחניו' ועד\"ז כל המצות שיעשה הקדב\"ה וכמו שמניח תפילין הנה ידוע מאמרם ז\"ל תפילין<sup data-n=\"3269\">33</sup> דמארי עלמא מה כתיב בהו ומי כעמך ישראל כו' וזהו שנק' תפילין<sup data-n=\"3270\">34</sup> מלשון התחברות כידוע משום דלכך נתחבר אור<sup data-n=\"3271\">35</sup> א\"ס להיות שורה בחכמה בשביל<sup data-n=\"3272\">*35</sup>",[["3261","25","<b>במקום גדולתו. . ענותנותו</b>: ראה מגילה לא, א. סה\"מ תרנ\"א ע' עא. הש\"ת ע' 40 בהערה."],["3262","26","<b>שקיים כל התורה למעלה ברוחני'</b>: ראה גם סה\"מ תקס\"ה ח\"ב ע' תשסח וע' תשסט."],["3263","27","<b>הקדב\"ה מניח תפילין</b>: ברכות ו, א. פסיקתא דרב כהנא פ\"ה. פרשת החודש (נה, א). וש\"נ. תו\"א מקץ לה, ב."],["3264","28","<b>מתעטף בציצית</b>: ר\"ה יז, ב. רמב\"ם הל' יסוה\"ת פ\"א, ה\"ט."],["3265","29","<b>מבקר חולים</b>: סוטה יד, א."],["3266","30","<b>חולת אהבה</b>: שה\"ש ב, ה. וראה סה\"מ תקס\"ג ח\"א ע' עח ואילך."],["3267","31","<b>סמכוני באשישות</b>: שה\"ש שם."],["3268","32","<b>בזוהר. . דבגלות מתרחקת מאד</b>: ראה זהר ויגש רי, ג. ויקהל רטז, ב."],["3269","33","<b>תפילין. . ומי כעמך ישראל</b>: ברכות ו, א. דברי הימים-א יז, כא. וראה סידור שער התפילין טז, ג. אמרי בינה שער התפילין רפכ\"ט."],["3270","34","<b>תפילין מלשון התחברות</b>: ראה גם ערכי הכנויים לבעל סדר הדורות מערכת תפילין. תו\"א מקץ לה, ב. יתרו סח, ג. אוה\"ת תצוה ע' א'תשכט. ואתחנן ע' שלא."],["3271","35","<b>אור א\"ס שורה בחכמה</b>: ראה תניא פל\"ה (בהגה\"ה)."],["3272","*35","<b>בשביל ישראל שנק' ראשית</b>: ראה רש\"י בראשית א, א."]]],[2100990072,"ישראל שנק' ראשית לפי שישראל<sup data-n=\"3273\">36</sup> עלה במחשבה כו' לכך בתפילין שלו נא' ומי כעמך ישראל וד\"ל ועד\"ז שאר המצות ונקראי' מצוות\"י וכולם נעשו למעלה כדי שיהי' על ידם הוספת אורו' בכלים וכנ\"ל וכמ\"ש אלה<sup data-n=\"3274\">*36</sup> המצות אשר יעשה אותם האדם וחי בהם האד\"ם בה\"א הידיע' וחי בהם היינו שעל ידם ניתוסף אורו' המאציל בנאצלי' כנ\"ל שיהא נק' חכים ומבין וכיוצא כו' וד\"ל (ועד\"ז יש למעלה<sup data-n=\"3275\">37</sup> חוקותי בב' חקיקות המבוארי' במ\"א והן המצות שנק' חוקים ותורתי הם בחי' גשמי' שנא' ונתתי<sup data-n=\"3276\">38</sup> גשמיכם בעתם שהוא ע\"י קול דתורה למעלה כמ\"ש כאשר<sup data-n=\"3277\">39</sup> ירד הגשם כו' כן יהי' דברי אשר יצא מפי מפי דוקא לפי שהקדב\"ה<sup data-n=\"3278\">40</sup> יושב וקורא כו' כמ\"ש שם) וכל אלה המצות נעשו למעלה ע\"י אברהם כגון מצות ביקור חולים למעלה כנ\"ל נעשה ע\"י אברהם הסמיכה באשישו' לרפאו' חולת אהבה כי מל' דאצי' כשמסתתרת בבי\"ע נעשה בה בחי' חולת אהבה כי אינה רק מבחי' הארה דהארה והגם שנק' ממלא כ\"ע וסובב כ\"ע אינו אלא בחי' הארה וזיו כו' כמ\"ש הודו<sup data-n=\"3279\">41</sup> על ארץ ושמים וכידוע ואברהם שנא' בו ויקרא<sup data-n=\"3280\">42</sup> אברם בשם ה' אל עולם הרי המשיך תוספת גילוי אלקו' מלמעלה למטה בזה הי' אתעדל\"ע למעלה לרפדנה בתפוחי' ולסמכנה באשישו' וכה\"ג בשאר עובדו' במס\"נ שהי' לאברהם הכל גרם לעשו' המצות למעלה ועי\"ז נמשך האורו' בכלים וכמ\"ש וחי<sup data-n=\"3281\">43</sup> בהם וזהו שרמ\"ח מ\"ע רמ\"ח איברי' דמלכא הם למעלה כנ\"ל וד\"ל.\n<b>והנה</b> אע\"פ שאברהם כבר קיים כל התורה למעלה עד שלא ניתנה מ\"מ היה חידוש גדול בנתינתה למטה לבא במעשה גשמי' בעולם הנפרד כו' כי הנה להמשיך האורות בכלים למעלה אין זה דבר חידוש כ\"כ מאחר שאמר דאיהו וחיוהי וגרמוהי חד כו' שהם מיוחדי' בתכלית היחוד בא\"ס וא\"כ אין רבותא כ\"כ להמשיך תוספ' אור מן המאציל לנאצלי' ע\"י הז' השמו' הנ\"ל כי במצות עליונו' שיעשה האדם דלעילא הרי המה נק' אברי\"ו וכמאמר דרמ\"ח פקודי' רמ\"ח איברי' דמלכא והאבר הוא מתאחד עם העצמו' ואין זה חידוש כשיומשך באיברי' תוספת אור וחיות כו' עד\"מ אבל האי עלמא נק' עלמא<sup data-n=\"3282\">44</sup> דפרודא כמ\"ש ומשם<sup data-n=\"3283\">45</sup> יפרד כו' שהרי הנבראי' כולם נבראו בבחי' יש מאין ואין ערוך כלל לנברא עם הבורא כידוע ומכ\"ש בנשמו' ישראל שהיו &lt;רח&gt;\nמלובשי' עדיין בחומר גופני שלהם שהוא בבחי' חיצוניו' עולם העשי' שהוא הנק' עולם הפירוד ממש ואין להם דמיון למעלת נשמת אברהם שהי' בחי' מרכבה ממש כו' א\"כ הי' פלא וחידוש גדול מה שיוכל אור א\"ס להתצמצם כ\"כ ולהיות",[["3273","36","<b>שישראל עלה במחשבה</b>: ראה ב\"ר פ\"א, ד."],["3274","*36","<b>אלה המצות. . וחי בהם</b>: חיבור ב' כתובים בחוקותי כז, לד. אחרי יח, ה."],["3275","37","<b>למעלה חוקותי בב' חקיקות המבוארי' במ\"א</b>: ראה לקו\"ת בחוקתי מה, א ואילך. וראה לעיל ד\"ה אם בחוקותי."],["3276","38","<b>ונתתי גשמיכם בעתם</b>: בחוקותי כו, ג."],["3277","39","<b>כאשר ירד הגשם</b>: ישעי' נה, יו\"ד."],["3278","40","<b>שהקדב\"ה יושב וקורא</b>: ראה תדא\"ר רפי\"ח. יל\"ש איכה רמז תתרלד."],["3279","41","<b>הודו על ארץ ושמים</b>: תהלים מח, יג."],["3280","42","<b>ויקרא אברם בשם ה' אל עולם</b>: חיבור שני כתובים לך יג, ד. וירא כא, לג."],["3281","43","<b>וחי בהם</b>: אחרי יח, ה."],["3282","44","<b>נק' עלמא דפרודא</b>: ראה ע\"ח שער מג (שער ציור עולמות) בהקדמה להדרוש. ובכ\"מ."],["3283","45","<b>ומשם יפרד</b>: בראשית ב, י."]]],[2100990073,"מלובש במדות ע\"י מעשה המצות שעושין למטה בגשמיות כמו בחסד וצדקה שעושין בגשמיו' להחיו'<sup data-n=\"3284\">46</sup> רוח שפלי' יהי' נמשך אור חסד עליון דאצי' עד חיצוניו' הכלים שבחסד שבמל' דעשי' ולהיו' נק' חסד דרועא ימינא כו' וכמ\"ש יהי<sup data-n=\"3285\">47</sup> חסדך עלינו כאשר יחלנו לך כו' ועד\"ז בשאר המצות כמו בתפילין הכתובי' בקלף גשמי יאיר ויתלבש אור א\"ס בחכמה גם עד בחי' חכמה שבמל' דעשי' להיו' מקיף על המוחי' שבאותו ניצוץ מישראל המניח תפילין הללו כו' וכיוצא בזה בכל המצו' מעשיו' כמו שאנו או' אשר קדשנו במצוותיו מפני שירד אור התורה והמצות העליונות ונתלבשו גם בעלמין דפרודא כו' וזהו וירד<sup data-n=\"3286\">48</sup> ה' על הר סיני כו' שהיתה בחי' ירידה גדולה ועצומה ולכך אמר רב יוסף דהאי יומא הוא דקא גרים מפני שבו היתה הירידה הזאת שהוא דבר חידוש גדול ונפלא מאד כו' וד\"ל.\n<b>אך</b> יש להבין היא גופא איך אפשר שיהי' בחי' דילוג גדול כזה כו' אך הענין יובן בהקדים מ\"ש כי<sup data-n=\"3287\">49</sup> אל דיעות ה' ולא נתכנו עלילו' ויש<sup data-n=\"3288\">50</sup> קרי וכתיב ולא באלף ולו בוי\"ו כו' והענין הוא כידוע<sup data-n=\"3289\">51</sup> שיש ב' דיעות ה' דיעה שמלמעלה למטה בבחי' יחודא עילא' העולמו' כלא וכאין חשיבי לגבי אור אלקי ונמצא למעלה בחי' היש וכמ\"ש להנחיל<sup data-n=\"3290\">52</sup> אוהבי יש כו' וכל מה שלמטה נחשב כאין ואינו תופס מקום כלל ודיעה הב' הוא מלמטה למעלה בבחי' יחודא תתא' שהם נבראי' יש מאין כידוע הרי נהפוך הוא שכל מה שלמטה מטה נחשב ליש ודבר כו' ולמעלה הוא בחי' אין כו' וכתיב כי אל דיעו' הוי' היינו שסובל ב' הדיעות הללו משום דלגבי עצמו' המאצי' שוה מלמטה למעלה כמו מלמעלה למטה אחר שהוא עצמו למעלה מן ההשתלשלו' לגמרי כנ\"ל וא\"כ כשם שמלמעלה למטה אין העולמו' תופסי' מקום כך מלמטה למעלה אין תופסי' מקום לגבי עצמותו כו' והוא שם זה דא\"ל כמ\"ש כי א\"ל דיעו' הוא הכולל דוקא ב' דיעות יחד כו' והיינו שנא' ולא<sup data-n=\"3291\">*52</sup> ולו ולא באלף הן שס\"ה ל\"ת ולו בוי\"ו הן רמ\"ח מ\"ע שכללותם הוא ענין יחודא עילא' ויחודא תתא' ב' דיעות הנ\"ל ולגבי עצמותו שניהם שוים כנ\"ל ע\"כ אמר ולא נתכנו עלילו' ששם נתכנו שניהם יחד כו' וד\"ל.",[["3284","46","<b>להחיו' רוח שפלים</b>: ישעי' נז, טו."],["3285","47","<b>יהי חסדך עלינו</b>: תהלים לג, כב."],["3286","48","<b>וירד ה' על הר סיני</b>: יתרו יט, כ."],["3287","49","<b>כי אל דיעות ה'</b>: שמואל-א ב, ג."],["3288","50","<b>ויש קרי וכתיב</b>: ראה זהר (אד\"ז) האזינו רצב, סע\"ב. ראה גם תו\"ח לך פח, ד."],["3289","51","<b>כידוע שיש ב' דיעות</b>: ראה תו\"א יתרו סח, א. לקו\"ת ראה כג, ד. שם דרושים לשמ\"ע פג, א. שם שה\"ש מז, ב. סה\"מ תקס\"ב ע' רו. סה\"מ תקס\"ג ח\"ב ע' תשעח. סה\"מ תקס\"ד ע' קנו. סידור שחרית מד, סע\"א. שם דרושים לחתונה קכט, א. אמרי בינה פתח השער פי\"ב. דרך חיים שער התשובה פכ\"ז. שער האמונה בהקדמה [ד\"ה וזהו ותאמר]. עטרת ראש שער ר\"ה פ\"ה. פ\"ח. תו\"ח בראשית יח, ג. שם לה, א. שם וירא צז, ב. ד\"ה ויתן לך תקפ\"ה שם תולדות יד, ד. ד\"ה וישלח יעקב תקפ\"ג שם וישלח מד, א. ד\"ה משה ידבר תקפ\"ג שם יתרו שפב, ב. פירוש המלות פקל\"ח ואילך. אוה\"ת דרושים לסוכות ע' א'תשל."],["3290","52","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["3291","*52","<b>ולא ולו ולא. . שס\"ה ל\"ת ולו. . רמ\"ח מ\"ע</b>: ראה תו\"ח יתרו רנב, א [הוצאת קה\"ת — תשס\"ג] ובהנסמן שם בהמ\"מ."]]],[2100990074,"<b>והנה</b> במעשה המצות נא' אדם<sup data-n=\"3292\">53</sup> אתם אתם קרויים אדם כו' משום דכתיב נעשה<sup data-n=\"3293\">54</sup> אדם בצלמינו כדמותינו ואין נק' אדם כצלם האלקי' ודמותו אלא ע\"י התורה והמצו' ולכך א' אתם קרויים אדם כו' והטעם הוא לפי שהקדב\"ה מקיים כל המצות למעלה כנ\"ל ע\"כ בקיום האדם המצות למטה נק' ג\"כ אדם אשר בצלמו ודמותו כו' אך הנה מה שאמר בצלמינו ודמותינו דוקא דהיינו שיהא ממש בצלם ודמות אדם העליון הענין הוא שיהא גם אצלו ב' הדיעו' הנ\"ל בהשווא' א' כמו שהוא בהשווא' א' למעלה כנ\"ל כי מחמת המשכו' אורו' בכלים שנמשך ע\"י האדם ע\"י המצות ממשיך למטה גילוי אלקו' כמו שהוא למעלה דהיינו להיו' אין<sup data-n=\"3294\">55</sup> עוד מלבדו למטה כמו למעלה ובזה הוא שנעשה אדם בצלמינו ממש כו' ואיך הוא ענין זה מבואר הוא במ\"א<sup data-n=\"3295\">56</sup> ע\"פ ולא &lt;רט&gt;\nתחללו כו' כי ע\"י לימוד התורה הרי דבר ה' הוא מדבר וכמ\"ש ואשים<sup data-n=\"3296\">57</sup> דברי בפיך כו' ולומד בבחי' ביטול כו' אזי אין העולם תופס מקום למטה כמו למעלה להיותו בלימוד זה בדוגמא לדבר ה' למעלה שאין תופס מקום לנגדו מלמטה למעלה כמו מלמעלה למטה כנ\"ל והיינו לא תחללו לא תעשו בחי' חלל בשם קדשו להיות העולם תופס מקום כו' ולא להיות דוחק רגלי השכינה כו' כי אין עוד מלבדו למטה כמו למעלה מטעם שאל דיעו' סובל וכולל ב' הדיעו' כנ\"ל וד\"ל.\n<b>והנה</b> ע\"י התורה הוא ממשיך המשכת אור פנימי מאור א\"ס ע\"ד הנ\"ל וע\"י המצות ממשיך בבחי' אור מקיף כידוע שהתורה<sup data-n=\"3297\">58</sup> נק' מזון והמצות נק' לבושי' שהם מקיפי' לנפש כו' כמ\"ש בספרי הקבלה וע\"י אמצעו' שניהם יחד נעשה ונמשך גילוי אור א\"ס למטה עד שאין העולם תופס מקום כלל וע\"ז נא' כי<sup data-n=\"3298\">59</sup> ה' אלקיך אש אוכלה הוא פי' עד\"מ האש הנתון בכלי מבפנים וגם מקיפי' אותו באש מבחוץ שנשרף ונכלה מעבר לעבר כל מיני חומריו' וגסות שיש בה כך עד\"מ הנפש הבהמיו' שהיא חומריו' מתבררת לגמרי ונשרפת באש מבפנים שהוא התורה ואש מבחוץ שהן המצות ואינה מסתרת כלל על הנפש האלקי' וז\"ש כי ה' אלקיך הוי' זהו בחי' התורה בבחי' אור מבפנים ואלקיך זהו בחי' המצו' בבחי' כלי כמ\"ש כי<sup data-n=\"3299\">60</sup> נר מצוה כו' והיינו שאמרו ז\"ל דת\"ח<sup data-n=\"3300\">61</sup> אין אור של גיהנם שולטת בהם מפני שהתורה והמצות כבר ביררו לנפשם הבהמיו' וא\"צ עוד מירוק בגיהנם כו' וד\"ל.\n<b>ואחר</b> הקדמה זו יובן הטעם איך הי' ירידה גדולה בנתינת התורה כו' משום דקמי' ב' הדיעו' שוין כנ\"ל ויכול אור א\"ס להתגלו' למטה כמו למעלה וע\"כ ניתנה",[["3292","53","<b>אדם אתם אתם קרויים אדם</b>: יחזקאל לד, לא. יבמות סא, א."],["3293","54","<b>נעשה אדם בצלמנו כדמותינו</b>: בראשית א, כו."],["3294","55","<b>אין עוד מלבדו</b>: לשון הפסוק ואתחנן ד, לה."],["3295","56","<b>במ\"א ע\"פ ולא תחללו</b>: ויקרא כב, לב. ראה גם תו\"א (שם) סח, ב. לקו\"ת נשא כז, א."],["3296","57","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["3297","58","<b>שהתורה נק' מזון והמצות נק' לבושי'</b>: ראה תניא פ\"ה."],["3298","59","<b>כי ה' אלקיך אש אוכלה הוא</b>: ואתחנן ד, כד."],["3299","60","<b>כי נר מצוה</b>: משלי ו, כג."],["3300","61","<b>דת\"ח אין אור של גיהנם שולטת בהם</b>: ראה חגיגה כז, א."]]],[2100990075,"התורה והמצו' גם בעולם הפירוד הזה להיו' גם כאן כמו למעלה והוא ניתן במתנה דוקא לישראל שיהא להם כח זה ע\"י עסק תורתם ועבודתם משא\"כ אוה\"ע אינם ממשיכי' כלום כמארז\"ל ג'<sup data-n=\"3301\">62</sup> מתנות טובות כו' וזמן מתנה זו היא בחג השבועו' זמן מתן תורתינו ולכך א' רב יוסף דהאי יומא דקא גרים ואי לאו האי יומא כמה יוסף איכא בשוקא, פי' דהאי יומא שירד ה' על הר סיני ניתן מתנה זו לכאו\"א מישראל שיוכל להמשיך גילוי אלקו' בתורתו ועבודתו למטה כמו למעלה ממש כנ\"ל ובזה מובדל ת\"ח משאר אנשים ואי לאו האי יומא כמה יוסף איכא בשוקא שאין הבדל בינו לבין שאר יוסף אלא בעסק תורתו וזה אינו אלא מצד האי יומא דקא גרים (וגם י\"ל כמה יוסף כי שמו הי' רמוז כשם יוס\"ף<sup data-n=\"3302\">63</sup> העליון שנק' צדיק חי עלמין ובו יורד האור והשפע למטה ואי לאו האי יומא כמה יוסף אחריני שבאת זלע\"ז כו' איכא והוא מ\"ש יוסף<sup data-n=\"3303\">64</sup> דעת יוסף מכאוב כענין חכמי'<sup data-n=\"3304\">65</sup> המה להרע כו' שיש השפעה לחיצוני' ג\"כ וכענין למשמאילי' בה כו').\n<b>וזהו</b> משה ידבר והאלקים יעננו בקול. פי' בחי' משה הוא למעלה מבחי' אברהם כי באברהם לא אמרו אלא שקיים כל התורה למעלה ולא ירד אותה למטה וכמ\"ש בו וישמור<sup data-n=\"3305\">66</sup> משמרתי מצוות\"י מצוות\"י דוקא כמו שהמה למעלה אבל לא הי' ביכולתו להוריד המצות עד למטה גם בעולם הנפרד אמנם ע\"י משה להיותו מבחי' ומדרגה יותר גבוה ע\"כ הוריד התורה והמצות &lt;רי&gt;\nגם למטה בעולם הנפרד וכמ\"ש וירד<sup data-n=\"3306\">67</sup> ה' על הר סיני כו' משום דכל<sup data-n=\"3307\">68</sup> הגבוה גבוה יותר יותר יוכל להשפיל א\"ע במקום נמוך ביותר ומטעם הנ\"ל בפי' אל דיעות ה' דדוקא לגבי עצמותו ב' הדיעו' שוין וגם מלמטה למעלה אין העולם תופס מקום כמו מלמעלה למטה וזהו מדרגת משה להיותו מבחי' מ\"ה וכמ\"ש ונחנו מ\"ה<sup data-n=\"3308\">69</sup> כי שרש נשמת משה מן בחי' עלמין סתימין שלפני ההשתלשלו' דאבי\"ע וכמ\"ש בו כי<sup data-n=\"3309\">70</sup> מן המים משיתהו וז\"ש בו מ\"ה<sup data-n=\"3310\">71</sup> שמ\"ו ומה שם בנ\"ו כו' וע\"כ הי' ביכולתו דוקא להוריד אור א\"ס בחכמה שבתורה גם למטה בעולם הנפרד להיו' מלובש גם בחכמ' שבענין גשמי ובמעשה גשמי' כו' כי החכמה<sup data-n=\"3311\">72</sup> מאין תמצא וע\"י משה מפני שהי' מבחי' מ\"ה נמשך מאין בחכמה גם בעולם הנפרד וזאת המעלה מיוחדת למשה דוקא על היותו עניו בתכלית והוא בחי' הביטול בתכלית וכמ\"ש בו והאיש<sup data-n=\"3312\">73</sup> משה עניו מאד מכל האדם אשר ע\"פ האדמה כו' ועד\"ז יש בחי' משה בכל דור ובכל זמן כמ\"ש בזוהר דאתפשטותי'<sup data-n=\"3313\">74</sup> דמשה בכל דרא",[["3301","62","<b>ג' מתנות טובות</b>: ברכות ה, סע\"א."],["3302","63","<b>יוסף העליון שנק' צדיק</b>: ראה זח\"א קנג, ב."],["3303","64","<b>יוסף דעת יוסף מכאוב</b>: קהלת א, יח."],["3304","65","<b>חכמי' המה להרע</b>: ירמי' ד, כב."],["3305","66","<b>וישמור משמרתי</b>: תולדות כו, ה."],["3306","67","<b>וירד ה' על הר סיני</b>: יתרו יט, ב."],["3307","68","<b>דכל הגבוה גבוה יותר</b>: ראה שערי אורה שער הפורים נח, א. סה, א. מאמרי אדה\"א שמות ח\"ב ע' שמח. וש\"נ. לעיל (ח\"א) ע' תח."],["3308","69","<b>ונחנו מ\"ה</b>: בשלח טז, ז."],["3309","70","<b>כי מן המים משיתהו</b>: שמות ב, יו\"ד."],["3310","71","<b>מה שמ\"ו ומה שם בנ\"ו</b>: משלי ל, ד. וראה תו\"ח שמות מג, ד. וש\"נ."],["3311","72","<b>החכמה מאין תמצא</b>: איוב כח, יב."],["3312","73","<b>והאיש משה עניו</b>: בהעלתוך יב, ג."],["3313","74","<b>דאתפשטותי' דמשה בכל דרא</b>: ראה ת\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א — ס\"א)"]]],[2100990076,"כו' והוא בחי' הענוה והשפלות בבחי' הביטול בתכלית שיש בכאו\"א מישראל בבחי' ביטול רצון בקיום התורה והמצות כענין בטל<sup data-n=\"3314\">75</sup> רצונך כו' בבחי' זו ממשיך ומנהיג אור א\"ס בחכמה להיו' נמצא ענותונתו כו' גם בעוה\"ז הנפרד וד\"ל וזהו מש\"ה ידב\"ר פי' ידבר לשון הווה שתמיד ידבר והיינו לפי שתמיד בחי' משה ידבר וימשיך התפשטו' אור א\"ס בתורה ומצות גם למטה מטה כו' וד\"ל.\n<b>והאלקים</b> יעננו בקול. פי' כי הנה ארז\"ל כל<sup data-n=\"3315\">76</sup> הקורא ושונה הקדב\"ה קורא ושונה כנגדו כו' ופי' כנגדו היינו פשוט כנגדו ממש כנגד הקורא לפי מה שהוא אם הוא מבחי' ומדרגה עליונה בשרש נשמתו משם ימשיך הקריאה אליו שיהי' הקדב\"ה קורא משם כנגדו כו' ולכאורה יפלא דלפ\"ז גם אם שרש נשמתו ומדרגתו ממדרגו' התחתונו' מאד גם משם ימשיך הקריאה כנגדו והאיך יהי' ירידת גילוי אלקו' כ\"כ למטה מטה שגם בהיות הקורא פחות הערך כמו קטן וע\"ה יהי' הקדב\"ה קורא כנגדו כו'.\n<b>אך</b> הענין הוא דהכל מטעם אחד והוא מפני שכבר ניתן כח זה במתנה לישראל בשעת מ\"ת ע\"י משה כנ\"ל בפי' דהאי יומא קא גרים כו' ודוקא ע\"י משה להיות כי משה<sup data-n=\"3316\">77</sup> נק' איש האלקי' והוא בעלה<sup data-n=\"3317\">78</sup> דמטרוניתא כי הנה פי' אלקי\"ם הוא בחי' השתררו' ואדנו' כמו נתתיך<sup data-n=\"3318\">79</sup> אלקים לפרעה כו' ולמעלה הוא בחי' כח הפועל בנפעל שהוא בחי' יחודא תתאה שבא ע\"י הצמצום דשם אלקים כו' ויש ק\"ך<sup data-n=\"3319\">80</sup> צרופי אלקי' בכללו' בי\"ע עד שגם במדרגו' התחתונו' דעשיה יש שם אלקי' ג\"כ המהוו' בחי' המרכבה דעולם העשי' פני<sup data-n=\"3320\">81</sup> ארי' פני שור כו' שמשם נמשך מקור חיות הנפש דנוגה הבהמיו' כידוע וע\"כ גם מי שקורא ושונה בהבל פיו מכח הנפש הבהמיו' קול זה יעורר שם אלקי' שרש ומקור אותה המרכבה דפני ארי' כו' שנמשך משם הנפש הבהמיו' ומשם הקדב\"ה קורא כנגדו וזהו והאלקים יעננו האלקים דוקא והוא מבחי' יחודא תתא' שמתלבשי' ק\"ך צרופי אלקי' וזהו שהאלקי' יעננו לקורא ושונה דהיינו שיהיה הקדב\"ה קורא ושונה כנגדו גם לפחות הערך כמו קטני' וע\"ה כי לכולם יש שרש לנפשם בשם &lt;ריא&gt;\nאלקי' כנ\"ל ולפי בחינתו ומדרגתו יעננו אלקי' כשיושב ושונה כו' וד\"ל.\n<b>וזהו</b> שארז\"ל והאלקי' יעננו בקול בקולו של משה דוקא. כי הנה ענייה זאת שהאלקי' יעננו באתעדל\"ע ע\"י אתעדל\"ת הקורא ושונה כנ\"ל כל זה הוא בא ע\"י קולו של משה דוקא וכמ\"ש משה ידבר ואז והאלקי' יעננו אבל כשאין משה",[["3314","75","<b>בטל רצונך</b>: אבות פ\"ב, מ\"ד."],["3315","76","<b>כל הקורא ושונה</b>: ראה תדא\"ר רפי\"ח."],["3316","77","<b>משה. . איש האלקים</b>: ברכה לג, א. תהלים צ, א."],["3317","78","<b>בעלה דמטרוניתא</b>: ראה זהר ויחי רלו, ב. תרומה קלז, ב. פירוש המלות פס\"ג. סה\"מ תקס\"ח ח\"א ע' תקע."],["3318","79","<b>נתתיך אלקים לפרעה</b>: וארא ז, א."],["3319","80","<b>ק\"ך צירופי אלקי'</b>: ראה ע\"ח (שער הזיווגים) שט\"ו, פ\"ו. (שער השמות) שמ\"ד, פ\"ה."],["3320","81","<b>פני ארי' פני שור</b>: יחזקאל פ\"א."]]],[2100990077,"המדבר לא יעננו אלקי' כו' לפי שבחי' משה המשיך מצד שרשו למעלה מעלה מכל ההשתלשלו' כנ\"ל שיהי' ירידת אור א\"ס גם למטה מטה כנ\"ל ולהיו' במקום גדולתו ענוותונתו כו' כי משה<sup data-n=\"3321\">82</sup> נק' שושבינא דמלכא שמוריד את המלך אל הכלה ושיהי' למטה כמו למעלה בהשווא' א' כנ\"ל והיינו מפני שהי' מבחי' שם מ\"ה כו' וע\"כ גם כל מי שיש בו קצת ההארה מבחי' משה ממדרגת שם מ\"ה והוא הענוה והשפלו' בבחי' הביטול כנ\"ל בפי' לא תחללו כו' גם בכל דור ובכל זמן כשקורא ושונה נק' זה בשם קולו של משה כי אתפשטותא דמשה בכל דרא כנ\"ל ואז נא' בו מש\"ה ידב\"ר שמדבר ומוריד אור א\"ס עד למטה והוא שיהי' הקדב\"ה קורא ושונה כנגדו ממש לפי מה שהוא כו' היינו שיהי' האלקי' יעננו בקול באותו קול דבר הלכה שהוא לומד וזהו בקו\"ל בקולו של מש\"ה דוקא לפי שהוא הגורם זאת הירידה של אור א\"ס בתחלה וע\"כ כשהאלקי' יעננו אינו עונה אלא אחר קולו של משה דוקא להיותו למעלה משם אלקי' זה וכידוע שנק' איש האלקי' כו' וד\"ל.\n<b>ובכל</b> זה יתורצו הקושיות הנ\"ל האיך הוא אומר ידבר ויעננו לשון הווה כו' דהרי ע\"י משה שהוא בחי' הביטול תמיד ידבר ותמיד יעננו האלקי' כו' בכל דור ובכל זמן כנ\"ל וגם הקושיא הראשונה מה הן הדברי' שעליהם אמר משה ידבר והאלקי' יעננו כו' הרי מובן דלא קאי על י' הדברו' אלא על ענין כח המשכה זו לעתיד בכל דורו' הבאים שיהי' הקדב\"ה קורא ושונה בכל מי שיקרא וישנה למטה יהי' מי שיהי' כנ\"ל שנעשה ונמשך כח זה בכנ\"י ע\"י שהי' משה מדבר והאלקים יעננו בשעת מ\"ת וזהו משה ידבר להמשיך ולהוריד אור א\"ס וכנ\"ל והאלקים יעננו למטה אז בקולו של משה שהמשיך מלמעלה כמו עד\"מ שמדברים ב' בנ\"א זע\"ז לגמור איזה דבר שיתקיים לעולם כו' וזהו שאמר רב יוסף דהאי יומא דקא גרים להיו' כי בהאי יומא דוקא משה ידבר על העתיד כו' וכן בכל חג השבועות בכל דור האי יומא קא גרים כח זה והטעם להאי יומא דוקא לפי שלא<sup data-n=\"3322\">83</sup> נשלמו הספי' עדיין ועדיין לא הוכשרו כנ\"י למתנה זו להיו' להם התורה במתנה שלא נשלמו כנ\"ל אלא ממחרת<sup data-n=\"3323\">84</sup> השבת תספרו כו' וביום החמשים הוא זמן מתן תורתינו דוקא וד\"ל.\n&lt;ריב&gt;",[["3321","82","<b>משה נק' שושבינא דמלכא</b>: ראה זהר (רע\"מ) ויקרא כ, א. מצורע נג, ב (רע\"מ)."],["3322","83","<b>שלא נשלמו הספי'. . וביום החמישים</b>: ראה ר\"ה כא, ב. וראה לקו\"ת במדבר י, ד. יב, א. ובכ\"מ."],["3323","84","<b>ממחרת השבת תספרו</b>: אמור כג, טז."]]],[2100990078,"<h3>מראיהם ומעשיהם</h3>\n<b>בעזר\"ה חג השבועות</b>\n<b>מראיהם</b><sup data-n=\"3324\">1</sup> ומעשיהם<sup data-n=\"3325\">2</sup> כאשר יהי' האופן בתוך האופן. פי' כמו<sup data-n=\"3326\">3</sup> האופן הקטן שהוא בתוך האופן הגדול שהאופן הגדול סובבו לאופן הקטן ומקיפו מכל צדדיו הרי בגובה עליונו של עיגולי' הללו האופן הגדול למעלה מאופן הקטן שבתוכו אחר שהוא מוקף בתוכו אבל למטה בתחתית העיגולי' הללו נהפוך הוא שם שהאופן הגדול הוא למטה מהאופן הקטן אחר ששם האופן הגדול מסבבו למטה ממנו והאופן הקטן למעלה מהאופן הגדול כו' וכך הוא רוח<sup data-n=\"3327\">4</sup> החיה באופנים. דהנה לכאורה יש להבין מה שאמר רוח החיה לשון יחידו' ולא אמר רוח החיות דהא ד'<sup data-n=\"3328\">5</sup> חיות הן במרכבה וכידוע.\n<b>אך</b> הענין הוא משום דמדרגת האופנים הוא ממדרגות התחתונו' דעשי' וכמ\"ש אופן<sup data-n=\"3329\">6</sup> אחד בארץ כו' וכדי להיות רוח החיה באופנים שהן היותר תחתוני' מוכרח שיתלבש שם הרוח ממקום ומדרגה היותר עליון והוא מבחי' הכללית של כל ד' החיות שבמרכבה הכוללת כולם וראשית כולם שהוא בחי' פני אדם שבמרכבה וכמ\"ש ופניהם<sup data-n=\"3330\">7</sup> פני אדם כו' כי פני אריה אל הימין ופני שור מהשמאל כו' אבל בבחי' אדם אין בו ימין ושמאל כי הוא בחי' פנימי' שלהם הכוללם יחד ולכך נק' אדם<sup data-n=\"3331\">8</sup> אדמה לעליון כלומר לבחי' אדם העליון שעל הכסא הנק' אדם דאצי' והם נק' אנפי<sup data-n=\"3332\">9</sup> רברבי ואדם זה דמרכבה נק' אדם תתא' ונק' אנפי זוטרי כו' וכמ\"ש בזוהר וכמ\"ש כמים<sup data-n=\"3333\">10</sup> הפנים לפנים כן לב האדם לאדם כו' וזהו כי<sup data-n=\"3334\">11</sup> רוח החי\"ה החי\"ה כתר הוא בחי' פני אדם שבמרכבה שכוללת כולם ולכך נא' החיה בהא הידוע' כלומר",[["3324","1","<b>מראיהם ומעשיהם כאשר יהי' האופן בתוך האופן</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (נד, א). הנחה אחרת בתו\"א יתרו סט, ב.\nמאמר זה באריכות במאמרי אדה\"א במדבר כרך ב ע' תכז. וראה בהנסמן שם בהמ\"מ. מאמר זה הוא קשור עם ד\"ה משה ידבר שלפנ\"ז.\nבהתמים חוברת ב דף מז, א ומועתק גם בהיום יום י\"ח שבט: ”כ\"ק אדמו\"ר הצ\"צ ספר לבנו אאזמו\"ר מהר\"ש, אשר הדרוש ומראיהם ומעשיהם — תורה אור פ' יתרו — הוא דרוש הראשון שאמר הרב המגיד ממעזריטש בשעת קבלו את הנשיאות — חג השבועות תקכ\"א — כפי אשר שמעו רבינו הזקן מפי הרמ\"מ מהאראדאק — בעל פרי הארץ — שהי' באותו מעמד, רק שרבינו ביאר הדרוש ע\"פ סגנונו\". עכ\"ל."],["3325","2","<b>מראיהם ומעשיהם. . בתוך האופן</b>: יחזקאל א, טז."],["3326","3","<b>כמו האופן הקטן. . שהאופן הגדול סובבו</b>: ראה אוה\"ת שמות כרך ח ע' ב'תתקעח."],["3327","4","<b>רוח החיה באופנים</b>: יחזקאל א, כ. כא."],["3328","5","<b>ד' חיות הן במרכבה וכידוע</b>: ראה אגה\"ק סי' כ\"ח (קמז, ב). לקו\"ת נשא כח, סע\"ג. אוה\"ת משפטים כרך ח' ע' ג'יח ואילך."],["3329","6","<b>אופן אחד בארץ</b>: יחזקאל א טו. וראה ס' הערכים — חב\"ד כרך ב' ע' שפח ואילך."],["3330","7","<b>ופניהם פני אדם. . פני אריה אל הימין</b>: ע\"פ יחזקאל א, יו\"ד. וראה מאמרי אדה\"א חגה\"ש ע' שצח ובהנסמן שם."],["3331","8","<b>אדם אדמה לעליון</b>: ישעי' יד, יד. ראה עבודת הקודש ח\"א פי\"ז ואילך. הנסמן במאמרי אדה\"א בראשית ע' תקסב."],["3332","9","<b>אנפי רברבי. . אנפי זוטרי</b>: ראה זהר פינחס ריז, ב. הנסמן בתו\"ח משפטים רפז, ג."],["3333","10","<b>כמים הפנים לפנים</b>: משלי כז, יט."],["3334","11","<b>כי רוח החי\"ה</b>: יחזקאל א, כ. כא. ושם י, יז."]]],[2100990079,"החיה הידועה שכוללת הכל כו' וכמ\"ש ופני<sup data-n=\"3335\">12</sup> אדם לארבעתן ואמרו<sup data-n=\"3336\">13</sup> בזוהר דכליל כולהו כו' וד\"ל והטעם לזה שמתלבש באופנים דוקא בחי' היותר עליון שהוא בחי' פני אדם הענין הוא לפי שבכל מקום זהו כלל גדול שכל שהוא אור יותר עליון מתפשט הארתו עד למטה מטה ביותר וכדוגמת האופן הקטן אשר יהי' בתוך האופן הגדול הנ\"ל שלהיותו גבוה יותר יותר משפיל א\"ע לסבב עד למטה מכולם וכמ\"כ באופני' להיותם מדרגה היותר תחתונה בהכרח שיסבב שם האור היותר עליון למעלה והוא אשר בחי' מעלה ומטה שוין לפניו וע\"כ למעלה הוא עליון ולמטה הוא תחתון מכולם כו' מפני שהוא למעלה מבחי' מעלה ומטה והוא בחי' פני אדם שבמרכבה כנ\"ל וזהו כי רוח החי\"ה באופני' דוקא להיותם נמוכי' מכולם ולא במדרגו' העליונו' מהם מטעם הנ\"ל וד\"ל.\n<b>והנה</b> כדוגמא זאת אשר באופנים יובן למשכיל ג\"כ עד למעלה מעלה ברום המעלות בכל ההשתלשלו' שהענין כן הוא מריש כל דרגין שבהשתלשלו' עד סוף כל דרגין שהוא בבחי' כאשר יהי' האופן בתוך האופן הנ\"ל דהיינו שבחי' מקיף היותר עליון בכל ההשתלשלו' הנק' כתר הכללי דהיינו בבחי' כתר דא\"א כו' הוא המקיף עד למטה מכל דרגין כו' וכמ\"ש ומתחת<sup data-n=\"3337\">14</sup> זרועו' עולם ואין לפניו בחי' מעלה ומטה כלל כמו העיגול היותר עליון שמקיף הוא גם לכלל היותר תחתון מכולם כו' וד\"ל.\n<b>וזהו</b> ענין חג &lt;ריג&gt;\nהשבועות בדרך כלל, דהנה מ\"ט<sup data-n=\"3338\">15</sup> ימי הספי' ידוע שהם באי' בבחי' סדר ההשתלשלו' דהיינו בבחי' מ\"ט שערי בינה באצי' ובבי\"ע וכנ\"ל שהם ענין ז'<sup data-n=\"3339\">16</sup> שמות שאינן נמחקי' להמשיך אורו' בכלים כו' דהכל הוא בבחי' ממלא כ\"ע בין באצי' בין בבי\"ע כו' שהוא כסדר ההשתלשלו' דוקא דהיינו בבחי' מעלה ומטה ראש ורגל כו', אבל בחג<sup data-n=\"3340\">17</sup> השבועות ביום החמשים הוא בחי' שער החמשים שהוא אור העליון מכל מ\"ט השערי' דבינה שהוא בחי' מקיף היותר כללי להקיף את כולם יחד מלמעלה ומלמטה כו' עד שהוא למעלה מבחי' מעלה ומטה ראש ורגל כו' ולכך בו ניתנה התורה לישראל דוקא כי הרי במ\"ת היה ענין ירידת אור א\"ס כ\"כ למטה כנ\"ל עד שהוא מתלבש בענין במ\"ע בעשי' גשמית כקלף התפילין וכיוצא בזה במל\"ת שזהו לפי שאין לפניו מעלה ומטה כלל וכמבואר<sup data-n=\"3341\">18</sup> בפי' כי אל דיעות הוי' כנ\"ל וזהו בבחי' שער החמשים דוקא להיותו בחי' מקיף היותר עליון עד שיכול לדור למטה כמו למעלה ממש וכענין כאשר יהי' האופן בתוך האופן הנ\"ל וד\"ל.",[["3335","12","<b>ופני אדם לארבעתן</b>: ע\"פ יחזקאל א, י."],["3336","13","<b>ואמרו בזוהר דכליל כולהו</b>: זח\"ב פ, ב. זח\"ג רמא, א."],["3337","14","<b>ומתחת זרועו' עולם</b>: ברכה לג, כז."],["3338","15","<b>מ\"ט ימי הספירה. . מ\"ט שערי בינה</b>: ראה לקו\"ת במדבר י, ד. תו\"ח נח נח, א. מאמרי אדה\"א ויקרא ח\"א ע' שו. במדבר ח\"ב ע' תל."],["3339","16","<b>ז' שמות שאינן נמחקין</b>: ראה רמב\"ם הל' יסוה\"ת פ\"י, ה\"ב."],["3340","17","<b>בחג השבועות. . שער החמישים</b>: ראה תו\"א יתרו סט, ב. לקו\"ת במדבר י, ד. יב, א. תו\"ח בא קיז, ד [הוצאת קה\"ת — תשס\"ג]."],["3341","18","<b>וכמבואר בפי' כי אל דעות הוי' כנ\"ל</b>: שמו\"א ב, ג. ראה לעיל ד\"ה משה ידבר (ע' תנט) ובהנסמן שם."]]],[2100990080,"<b>וזהו</b> ג\"כ הטעם שבחג<sup data-n=\"3342\">19</sup> השבועו' בו ניתן לישראל בחי' כתר תורה וכמ\"ש ויתנצלו<sup data-n=\"3343\">20</sup> בנ\"י את עדיים מהר חורב וכן כתיב ותבואי<sup data-n=\"3344\">21</sup> בעדי עדיים כו' וכמ\"ש במ\"א כי פי' כתר תורה היינו עד\"מ הכתר והעטרה הגשמית שהיא נתונה ע\"ג הראש מלמעלה בבחי' מקיף להורות שאין בבחי' מקיף בחי' מעלה ומטה שהוא בחי' ענין ראש ורגל כי על הראש מקפת ג\"כ וכוללת בהקפתה הכל ראש ורגל כו' והוא מטעם הנ\"ל להיות כי שער החמשים הוא בחי' מקיף היותר עליון וע\"כ נק' כתר תורה דוקא משום דאוריי'<sup data-n=\"3345\">22</sup> מחכמ' נפק' ומתלבשת בבחי' ו' מדות דז\"א והן שיתא סדרי משנ' ובפרט הן ל\"ו מסכתו' שכל מדה כלולה מו' כו' אך בזמן מ\"ת ניתן בחי' הכתר שבה שלמעלה מן המדו' המסתעפי' ממ\"ט שערי בינה והוא מבחי' שער החמשי' הכולל כולם וד\"ל.\n<b>וזהו</b> ביאור ענין משה ידבר הנ\"ל, דהנה אמרו ז\"ל דמ\"ט<sup data-n=\"3346\">23</sup> שערי בינה נמסרו לו למשה חוץ מאחד והוא שער החמשים וכמ\"ש ותחסרהו<sup data-n=\"3347\">24</sup> מעט מאלקי' כי שם אלקים דבינה כולל מ\"ט שערים ושער החמשים כוללם יחד וכמ\"ש לך<sup data-n=\"3348\">25</sup> ה' הגדולה כי כל כו' אותיו' לך וכל הן חמשים שערי בינה כו' וכמ\"ש במ\"א ועכ\"פ קרוב היה משה לשער החמשים הזה אלא שלא ניתן לו במתנה דהיינו שיוכל להביאו בבחי' גילוי למטה כו' שהרי בהכרח לומר שהי' למשה השגה גם בשער החמשים כידוע בפי' ויעבור<sup data-n=\"3349\">26</sup> ה' על פניו ויקרא הוי' הוי' כו' דויעבור קאי על ה' ואחר שעבר קרא משה י\"ג מדה\"ר הללו ופי' ויקרא קאי על משה כדאית' בזוהר וזאת הקריא' משם הוי' שבכתר העליון המקיף הכללי הוא כידוע שהוא למעלה מסדר ההשתלשלו' כמשי\"ת<sup data-n=\"3350\">27</sup> בסמוך בפי' ונוצר חסד כו' וא\"כ הי' למשה השגה גם בשער החמשי' אלא שלא ניתן לו במתנה להביאו למטה בבחי' גילוי גם בכנ\"י עד בחג השבועו' שאז נאמר מש\"ה<sup data-n=\"3351\">28</sup> ידבר פי' בחי' משה דוקא ימשיך ויוריד אור א\"ס להיו' למטה כמו למעלה כנ\"ל שהוא מפני שזכה לבחי' שער החמשים שנתגלה לו בשעת מ\"ת דוקא ולהיותו יותר עליון הוא דוקא יכול לירד למטה מטה כ\"כ כענין הנ\"ל באופן אשר בתוך האופן כו' וד\"ל.\n<b>וגם</b> בכל דור ובכל זמן מתלבשת הארת משה בכל ראשי ישיבו' &lt;ריד&gt;\nשבכנ\"י וכמובן מתוך דברי רז\"ל שהיו קוראים לראש הישיבה בשם משה כענין שאמר רב",[["3342","19","<b>שבחג השבועו'. . כתר תורה</b>: ראה פע\"ח שער (כג) חג השבועות פ\"א. וראה תו\"א יתרו סז, ב. קט, א. לקו\"ת שה\"ש מד, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתה. מאמרי אדה\"א במדבר כרך ב ע' תלב ואילך."],["3343","20","<b>ויתנצלו בנ\"י את עדיים</b>: תשא לג, ו."],["3344","21","<b>ותבואי בעדי עדיים</b>: יחזקאל טז, ז."],["3345","22","<b>דאוריי' מחכמ' נפק'</b>: זח\"ב סב, א. פה, א. ועוד."],["3346","23","<b>דמ\"ט שערי בינה נמסרו לו למשה</b>: ראה ר\"ה כא, ב. ת\"ז סתכ\"ב. תז\"ח קיג, ג. (ובהנסמן בנצוצי זהר לשם). לקו\"ש חי\"ד ס\"ע 451."],["3347","24","<b>ותחסרהו מעט מאלקי'</b>: תהלים ח, ו."],["3348","25","<b>לך ה' הגדולה</b>: דה\"א כט, יא."],["3349","26","<b>ויעבור ה' על פניו. . קאי על משה</b>: תשא לד, ו. ואילך. וראה זח\"ג קלח, א. אוה\"ת תשא ע' ב'סז."],["3350","27","<b>כמשי\"ת בסמוך בפי' ונוצר חסד</b>: בקטע המתחיל ”ולהבין כל זה\"."],["3351","28","<b>משה ידבר</b>: יתרו יט, יט."]]],[2100990081,"ספרא לרבא מש\"ה<sup data-n=\"3352\">29</sup> שפיר קאמרת כו' (ויש שהיו קוראי' לו במדרג' אברהם וכמו שאמר רב יוסף מארי<sup data-n=\"3353\">30</sup> דאברהם כו') לפי שראש הוא המוריד וממשיך אור א\"ס בחכמה שבתורה שלומד להם להיו' בבחי' גילוי למטה כמו למעלה שזה אינו אלא מבחי' שער החמשים שזכה משה ע\"י מ\"ת דוקא והוא הנק' כתר תורה שניתן למשה שעליו אנו אומרי' ישמח<sup data-n=\"3354\">31</sup> משה במתנת חלקו כו' כי כליל תפארת בראשו נתת לו כו' וד\"ל.\n<b>ולהבין</b> כל זה בתוספת ביאור יש להקדים תחלה שרש ענין ונוצר<sup data-n=\"3355\">32</sup> חסד לאלפים ושרש ענין ועושה<sup data-n=\"3356\">33</sup> חסד לאלפים מהו ההפרש אשר בין ונוצר לעושה ומהו פי' לאלפי\"ם דוקא כו'. הנה תיבת ונוצר<sup data-n=\"3357\">34</sup> אותיו' צנור ואותיו' רצון כי מזל ונוצר חסד הוא שרש ומקור לאור החכמה שוהחסד הזה הוא מקור לחכמ' כי חסד<sup data-n=\"3358\">35</sup> בגי' ע\"ב כו' כידוע וכמ\"ש והחכמה<sup data-n=\"3359\">36</sup> מאין תמצא מאין הוא הכתר שהוא הרצון ומתחלף האותיו' דרצון באותיו' צנור כי אין ההארה הזאת רק בחי' המשכה מצומצמת כמו הקילוח דרך הצינור וגם פי' ונוצר לשון שמירה הוא כאדם ששומר במחשבתו איזה דבר כענין ואביו<sup data-n=\"3360\">37</sup> שמר את הדבר שהוא ענין הסכם הדבר ברצון במחשבתו בהעלם ועדיין אינו בא לידי גילוי כך שרש ומקור לחכמה כשהוא עדיין בבחי' ההעלם דרצון הנק' כתר הוא ענין ונוצר כלומר ששומרו לחסד עדיין בהעלם המחשבה כו' משא\"כ ועושה חסד הוא בחי' גילוי אור החסד מן ההעלם כי ענין עשי' הוא בחי' התיקון וכמו ועשת'<sup data-n=\"3361\">38</sup> את צפרני' שהוא ענין בחי' המשכת אור בכלי כך כשכבר נמשך האור דחסד זה בכלי שהוא בחי' עשי' נק' ועושה חסד אבל כששומרו עדיין ברצון נקרא ונוצר חסד כו' וד\"ל. ובזה יובן הטעם מה שנוצר חסד כתיב קודם פוקד<sup data-n=\"3362\">39</sup> עון אבות ועושה חסד כתיב אחר פוקד עון אבות, כי הנה פוקד עון אבות עד ונקה הוא אחר סיום י\"ג מדה\"ר והנה בחי' ונוצר חסד שהוא שרש לחכמה דאצי' כנ\"ל הרי הוא למעלה מן ההשתלשלו' דאצי' וע\"כ נאמר קודם פוקד עון אבו' כו' אבל בחי' ועושה חסד שהוא בבחי' גילוי אור בכלי כנ\"ל הרי הוא בבחי' חסד דז\"א שלמטה מן אור אבא כידוע בזוהר דאית<sup data-n=\"3363\">40</sup> חסד ואית חסד כו' והוא מדרגת אברהם כנ\"ל ע\"כ נאמר אחר פוקד עון אבות דהיינו לאחר סיום י\"ג מדה\"ר במזל ונקה שהוא מזל הי\"ג כידוע כי י\"ג מזלו' דא\"א כולם גבוהי' גם מאור החכמה ראשית האצי' כו' וד\"ל והנה בב' מדרגו' חסד הנ\"ל נאמר לאלפי\"ם.",[["3352","29","<b>מש\"ה שפיר קאמרת</b>: שבת קא, ב."],["3353","30","<b>מארי דאברהם</b>: ראה ב\"ב קלד, ב — א\"ר יוסף מריה דאברהם."],["3354","31","<b>ישמח משה במתנת חלקו</b>: נוסח תפלת עמידה שחרית לשבת."],["3355","32","<b>ונוצר חסד לאלפים</b>: תשא לד, ז."],["3356","33","<b>ועושה חסד לאלפים</b>: יתרו כ, ו. ואתחנן ה, י."],["3357","34","<b>ונוצר אותיו' צנור ואותיו' רצון</b>: ראה זהר הרקיע לזהר בראשית נא, א (כה, ב). וראה קונטרס תשובות וביאורים (מכ\"ק אדמו\"ר זי\"ע) סט\"ו. וש\"נ. ראה גם ס' מאמרי אדה\"א ויקרא ע' רעג. וש\"נ."],["3358","35","<b>חסד בגי' ע\"ב</b>: ראה לקו\"ת ואתחנן יג, ב. ובהנסמן שם בהמ\"מ."],["3359","36","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["3360","37","<b>ואביו שמר את הדבר</b>: וישב לז, יא."],["3361","38","<b>ועשת' את צפרני'</b>: תצא כא, יב."],["3362","39","<b>פוקד עון אבות</b>: תשא לד, ז."],["3363","40","<b>דאית חסד ואית חסד</b>: ראה זח\"א ריט, א. זח\"ג קלג, ב. וראה אוה\"ת וירא צ, א ואילך."]]],[2100990082,"<b>ויש</b> להבין מהו לאלפים דוקא דהנה ידוע בסדרי העליות של הנשמו' מג\"ע לג\"ע שהוא ממדרגה למדרגה גבוה הימנה שצריך בתחלה לשכוח על מדרגתו הראשונה לגמרי ואם לאו לא יוכל לעלות וכמו שאנו מוצאי' בעליו' הנשמו' מג\"ע התחתון שבמל' דעשי' כשעולין דרך העמו\"ד הידוע לג\"ע העליון שהוא בעולם הבריא' צריכי' לטבול<sup data-n=\"3364\">41</sup> בנהר דינור דנגיד<sup data-n=\"3365\">42</sup> ונפיק מן קדמוהי כו' כדי לשכוח גם בחי' התענוג שהתענג על ה' בג\"ע התחתון ליהנות מזיו השכינה כו' כמו שצריכי' לטבול בנהר דינור שלמטה בצאת הנשמו' מחומר הגופני שבעוה\"ז כדי לעלו' &lt;רטו&gt;\nלג\"ע התחתון מפני שצריכי' לשכוח<sup data-n=\"3366\">43</sup> על כל עניני עוה\"ז החומריים גם שיאבד מהם כח הזכרון מעניני' החומריים כי כל זמן שגם כח הזוכר מעניני' הגשמיי' לא נשתכח מהם א\"א להם לקבל העונג האלקי בג\"ע התחתון כו' וכך הוא ענין הטבילה בנהר דינור מדי עלותם מג\"ע התחתון לג\"ע העליון כי לפי ערך יחשב התענוג שבג\"ע התחתון בחי' הגשמת העוגג לגבי בחי' עונג שבג\"ע העליון, ודוגמא לדבר זה יובן ממה שמצינו בגמ' בר' זירא שהתענה<sup data-n=\"3367\">44</sup> מאה תעניו' עד ששכח תלמודו שלמד בבבל בעלותו ללימוד תלמוד ירושלמי שהוא יותר גבוה להיותו בלתי פלפול כו' והגם שתלמודו בבבלי הי' בתכלית הפשטת הגשמיו' כי הרי לא שלט בו האש כידוע בו מענין המעשה שנכנס באש ולכך נק' קטינא<sup data-n=\"3368\">45</sup> חריך שקי כו' מ\"מ התענה ק' תעניו' שישכח תלמודו לגמרי כי לא יוכל לקבל מדרגה היותר גבוה בלתי אם ישכח לגמרי על מדרגתו הראשונ' כו' וכיוצא בזה המה ענין העליו' ממדרג' למדרגה בדרך פרטי עליו' העולמו' כמ\"ש ילכו<sup data-n=\"3369\">46</sup> מחיל אל חיל כו' וכמ\"ש הליכו'<sup data-n=\"3370\">47</sup> אלי כו' וזהו פי' לאלפי\"ם דהיינו שיש אלפים מדרגות בעליו' מזה לזה ובין כאו\"א צריך ביטול ושכחה כנ\"ל והחסד הנ\"ל נמשך לאלפים מדרגו' מלמעלה למטה עד שיוכלו לקבלו גם העומדי' במדרגה היותר תחתונ' שבאלפים המדרגו' הללו וד\"ל.\n<b>אך</b> הנה יש להבין עדיין מה שהוא אומר הענין במספר הקצוב לאלפים דוקא, הענין הוא להיות כי בחי' החסד הוא בחי' אור ההשפעה בכל מקום לפי מה שהוא אם מלפני האצי' לאצי' הוא הנק' ונוצר חסד כנ\"ל ואם מאצי' לבי\"ע הוא הנק' ועושה חסד כנ\"ל ובכולם ירידת אורו הרי בא בצמצום להאיר למטה בצמצום אחר צמצום עד למטה מטה יגיע אור החסד ג\"כ ובדרך פרט המה אלפי\"ם מדרגו' עד שמחמת זה בעליו' הנשמו' ג\"כ יש אלפים מדרגו' להגיע לאור החסד הראשון כו' ואמנם הנה מה שהן אלפי\"ם אין הענין מצד המספר אלא מפני שאור חסד זה בא בצורת אור האל\"ף<sup data-n=\"3371\">48</sup> דוקא כי שרש חסד זה בא בשם מ\"ה שהוא במילוי אלפי\"ן דוקא",[["3364","41","<b>לטבול בנהר דינור. . לג\"ע העליון</b>: ראה חגיגה יג, ב. וראה זהר מקץ רא, א. ויקהל ריא, ב. דרך מצותיך קפט, ב. תו\"ח בראשית לג, ב ובהערה 10."],["3365","42","<b>דנגיד ונפיק מן קדמוהי</b>: דניאל ז, יו\"ד."],["3366","43","<b>לשכוח על כל עניני עוה\"ז</b>: ראה זהר ויקהל שנסמן לעיל."],["3367","44","<b>שהתענה מאה תעניו'</b>: ב\"מ פה, א. ראה תו\"א יתרו סט, ג. אוה\"ת במדבר כרך ג ע' תתנז. ואתחנן ע' עה. וראה גם לקו\"ש ח\"כ ר\"ע 319. חכ\"ד ס\"ע 26. וש\"נ."],["3368","45","<b>קטינא חריך שקי</b>: ברכות מו, א."],["3369","46","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["3370","47","<b>הליכות אלי</b>: תהלים סח, כה."],["3371","48","<b>האל\"ף. . בשם מ\"ה. . במילוי אלפין</b>: ראה זהר בראשית כו, א-ב."]]],[2100990083,"וביאור ענין מילוי שם הוי' באלפי\"ן הוא ענין אות האלף דשם אהי' ופי' אהי' ידוע בזוהר<sup data-n=\"3372\">49</sup> אנא זמין לאתגלאה כו' כי כל אל\"ף מורה על העתידות כמו אעשה ארצה אפקוד כו' וכך שם אהי' ענינו על העתיד דאנא זמין לאתגלאה ועדיין לא נתגלה כו' והטעם הוא כי גם צורת האות של האל\"ף מורה כך דהנה אנו רואים ציור תמונת<sup data-n=\"3373\">50</sup> אלף הוא יו\"ד בראשו וי\"ו באמצעו ויו\"ד הפוכה תחתיו כזה א וידוע שהיו\"ד<sup data-n=\"3374\">51</sup> הוא בחי' הצמצום והוי\"ו הוא בחי' ההמשכה וא\"כ בצורת אל\"ף הרי בחי' הצמצום בא תחלה ואח\"כ נמשך אור ההשפעה וההמשכה שהוא הוי\"ו אשר באמצעו להורות כי המשכה זאת הנה היא באה דוקא אחר בחי' הצמצום בראשונה מפני שמבלעדי הצמצום לא הי' באפשר להיו' בחי' המשכה זאת כו' כי הכל הי' נכלל בעצמות המשפיע כו' ואח\"כ חוזרת ומתצמצמת המשכה זו ונעשית כמו יו\"ד הפוכה תחת הוי\"ו והוא ענין הצמצום אשר אחר ההמשכה בשביל המשכה אחרת הבאה אחריה שצ\"ל הפסק וביטול בין זה לזה כמו שמבואר בענין עליו' המדרגו' הנ\"ל ונמצא מובן שממדרגה למדרגה נעשה ציור אות אלף דהיינו צמצום והמשכה &lt;רטז&gt;\nוצמצום שהוא יו\"ד וי\"ו יו\"ד שבאות האל\"ף וע\"כ נק' המשכת גילוי אור החסד הזה ממדרגה למדרגה בשם הוי' שהוא במילוי דאלפי\"ן כלומר אנא זמין כו' פי' לעתיד דוקא וכמ\"כ הוא בכל פרטי סדר ההשתלשלו' שבא מעילה לעילה שתחתיה כו' וד\"ל (אך הנה לפ\"ז היה מהראוי שיהיה הוי\"ו שבאמצע אות האלף מתמשך ביושר ולא באלכסון, ואם מפני היו\"ד שצ\"ל תחתיו, הי' צריך שאלכסונו יהי' נמשך מימין לשמאל ולא משמאל לימין כזה א אלא א<sup data-n=\"3375\">52</sup>, אך יש בזה ענין עמוק לי\"ח משום דההמשכה צריכה להיו' באלכסון שמשמאל לימין דוקא וכמ\"ש שמאלו<sup data-n=\"3376\">53</sup> תחת לראשי כו' וד\"ל) וזהו ונוצר חסד לאלפים ועושה חסד לאלפים הכל בבחי' ציור דאות אלפי\"ן בין מכתר לאצילו' ובין מאצי' לבי\"ע ומטעם הנ\"ל וד\"ל. ובכל זה מובן בתוספת ביאור בענין שער החמשי' דמשה ידבר שהוא בבחי' ונוצר חסד שבא מן בחי' הכתר ונק' תר\"ך<sup data-n=\"3377\">54</sup> עמודי אור וכמו שהעמוד מחבר מעלה ומטה יחד כך הוא בחי' כתר תורה והוא שם מ\"ה במילוי אלפי\"ן שבתורה מפני שאור החכמה מקבל ממזל ונוצר אבל בחי' אברהם הי' מבחי' ועושה חסד שהוא בבחי' חסד דז\"א והגם שהוא ג\"כ במילוי אלפי\"ן כנ\"ל אבל אינו יורד לבי\"ע בגילוי רק הכל באצי' מטעם דאיהו וגרמוהי חד כנ\"ל משא\"כ ע\"י משה נמשך ע\"י שער החמשי' גם בעולם הפירו\"ד כו' כמשל העמוד שמחבר מעלה ומטה יחד ולכך נא' ונוצר קודם פוקד עון אבו' כו' כנ\"ל וד\"ל.",[["3372","49","<b>בזוהר אנא זמין לאתגלאה</b>: ראה זח\"ג יא, א. (ובמק\"מ וזהר הרקיע שם). סה, ב. (ובמק\"מ שם). פרדס שער השמות פ\"ב."],["3373","50","<b>תמונת אלף. . יו\"ד בראשו. . ויו\"ד הפוכה תחתיו</b>: ראה שו\"ע אדה\"ז הל' תפילין סל\"ו."],["3374","51","<b>שהיו\"ד הוא בחי' הצמצום</b>: ראה אגה\"ת פ\"ד."],["3375","52","<b>א</b>: ציור אות א' זה נעתק מגוכתי\"ק אדה\"א בגוכתי\"ק מס' 1025."],["3376","53","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."],["3377","54","<b>תר\"ך עמודי אור</b>: ראה פרדס ש\"ח, פ\"ג. וראה אגה\"ק סכ\"ט."]]],[2100990084,"<h3>להבין שרשי הדברים הנ\"ל</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b><sup data-n=\"3378\">1</sup> שרשי הדברים הנ\"ל. הנה להבין שרש ענין ההפרש בין אברהם למשה דאע\"פ שאברהם<sup data-n=\"3379\">2</sup> קיים כל התורה עד שלא ניתנה מ\"מ יש מעלה יתירה במשה שניתנה על ידו ולכך נא' משה<sup data-n=\"3380\">3</sup> ידבר משה דוקא כנ\"ל.\n<b>הנה</b> צריך להקדים תחלה שרש ענין אברהם למעלה. דהנה שרש בחי' אברהם למעלה הוא מתחיל מבחי' יסוד אבא ולכך נק' אבר\"ם וידוע דא\"ב<sup data-n=\"3381\">4</sup> הוא בחי' חכמה שנק' אור אבא וענין אבר\"ם הוא בחי' רוממו' אור החכמה והוא קודם שיתלבש השכל במדו' שהחכמה מובדלת בכח נבדל מן המדו' ומשם נמשך המוחי' למדו' בצמצום כידוע. והנה כל עבודת אברהם למטה הי' להיות בחי' הגדלות המדות דז\"א ע\"י המשכות מוחי' מאור אבא בז\"א ותחלה יש להבין מהו ענין הגדלו' המדו' בז\"א, בהיות ידוע בפי' אד\"ם למעלה שהוא כשנעשה בחי' פרצוף ברמ\"ח איברים וכדי שיהי' גידול האיברים הוצרך להיו' בג' זמנים הנק' עיבור יניק' מוחי' וסדר הגידול כך הוא כי הנה תחלה לא היו המדו' דז\"א רק בבחי' קטנו' דעיבור והוא בבחי' תלת<sup data-n=\"3382\">5</sup> גו תלת ואח\"כ נתגדלו בזמן העיבור להיו' כלול כל מדה מששה מדו' והוא מספר ל\"ו בכלל &lt;ריז&gt;\nמו' המדו' ונק' אל\"ה<sup data-n=\"3383\">6</sup> והוא אותיו' לאה כידוע בפי' מי<sup data-n=\"3384\">7</sup> ברא אלה שהוא עיבור ז\"א במעי אימא שנק' מי כו' ואח\"כ בזמן היניקה נגדלו עוד להיו' כל מדה כלולה מן בחי' חב\"ד ג\"כ והיינו שיהי' ט' ספי' בכל מדה כמו בחי' חסד דז\"א יש בו גם בחי' חב\"ד שבחסד כו' וזהו בפרט וממילא בכלל שנעשה בעל ט' ספי' וט' פעמי' ט' גי' פ\"א וג\"פ פ\"א שיש בבחי' רת\"ס שבג' כלים פנימי' אמצעים וחיצונים שבאיברי' כידוע הרי רמ\"ג ועם ה\"ח דאימא המגדילי' עולה רמ\"ח כו' והגדלה זאת הוא הנק' בחי' מוחי' דיניקה עד\"מ התינוק שמתגדלים איבריו בזמן היניקה שיונק מחלב אמו והחלב הוא הנכנס בתוכו בבחי' א\"פ ומתעלם בו והרחבת גידול האבר ממילא בא והגידול אינו לפי ערך שמתגדל בזמן הגדלו' במזונות כו' כמ\"ש במ\"א.\n<b>כך</b> למעלה יובן למשכיל איך שהמדו' עליונו' דז\"א מתגדלי' להיו' כלולים מט' ספי' כמו חב\"ד שבחסד וחג\"ת שבחסד כו' שכל זה הגידול מתגדל מבחי' היניק' ממוחי' דאימא שנעשה ונמשך כמו חלב לתינוק עד\"מ עד שיש דעת בכל מדה",[["3378","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (נה, א). הנחה אחרת בתו\"א סח, ג."],["3379","2","<b>שאברהם קיים כל התורה</b>: ראה יומא כח, ב."],["3380","3","<b>משה ידבר</b>: יתרו יט, יט."],["3381","4","<b>דא\"ב הוא בחי' חכמה</b>: ראה זהר (אדרא זוטא) האזינו רצ, א. תניא פ\"ג. ביאוה\"ז ויצא טז, ג. בלק קג, ב. לקו\"ת שה\"ש יג, סע\"ד."],["3382","5","<b>תלת גו תלת</b>: ראה זהר (תוספתא) בשלח נ, סע\"א. ע\"ח שער הכללים פ\"ג. שעה\"י קל, ב הערה 18."],["3383","6","<b>אל\"ה. . אותיו' לאה</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ס\"ע תתפג. ביאורי הזהר תרומה מט, ג. לקו\"ת פקודי ד, ג. ע\"ח שער (לז) יעקב ולאה פ\"ד. מאו\"א מערכת אלה ספ\"א."],["3384","7","<b>מי ברא אלה</b>: ישעי' מ, כו."]]],[2100990085,"והוא מובן בדרך דוגמא ממה שאנו רואי' בתינוק בזמן היניקה שמדותיו הטבעיים אינם כמדו' דבהמה ממש בלא דעת אלא יש בהן קצת הארת הדעת והוא ענין טעם ושכל למה יחפוץ בזה הדבר וכיוצא ובעבודת ה' יובן זה ממה שימצא התפעלו' האהבה ע\"י הארת הדעת והטעם והדעת הזה נכנס באותה ההתפעלות ומזה נעשה סיבת התרחבותה וגידולה בבחי' התפשטו' לאורך ורוחב כו' וכמ\"ש במ\"א וכך יובן למעלה ואמנם תחלה לא הי' בז\"א בעיבור במעי אימא רק בבחי' קטנו' דהיינו תלת גו תלת ואח\"כ לו' דהיינו שחב\"ד שבהם בהעלם הי' בהם עד שבא זמן היניק' כנ\"ל וד\"ל ובזמן הגדלו' הוא נעשה בעל י' ספי' והוא כלול מבחי' כחב\"ד מפני שבכל מדה מאיר מבחי' צלם אור אבא להגדיל תוספת המוחי' מבחי' הכתר שבו והוא בחי' גדלו' המוחי' דז\"א דהיינו שמוסיפי' לו מוחי' בג\"ר שבו והוא רק ע\"י המשכו' אור מאור אבא דוקא כמ\"ש במ\"א באריכו' ואז נק' בחי' ז\"א אילנא דכליל מע' ענפין והוא כשכל מדה כלולה מי' כי אז גם בחי' מלכיו' שבו כלולי' מי' כו' וכמ\"ש במ\"א וד\"ל.\n<b>והנה</b> כשנעשה בחי' הגדלו' המדו' דז\"א בבחי' מוחי' דגדלו' מאור אבא היינו עד\"מ כמו שיאיר שכל האדם מכח השכל הנבדל שבו במדותיו להוסיף בהם גילוי מוחי' כו' וזהו בחי' אברם שהוא בחי' רוממו' אור החכמה שנק' אברם כנ\"ל וכשבא ונמשך למטה להאיר תוספ' מוחי' בג\"ר שבמדו' נק' אברהם וזה הי' כל עיקר עבודת אברהם אבינו ע\"ה למטה והיינו שאמרו קיים אברהם כל התורה ואפי' ערובי תבשילין כו'.\n<b>דהנה</b> ענין המצות בשרשן המה ג\"כ בחי' כלים לאורו' דז\"א שהרי נק' רמ\"ח איברים דמלכא וע\"ד דוגמא הנה מצות התפילין למעלה כמאמר שהקדב\"ה<sup data-n=\"3385\">8</sup> מניח תפילין ותפילין<sup data-n=\"3386\">9</sup> דמארי עלמא כתיב בהו כי מי גוי גדול<sup data-n=\"3387\">10</sup> כו' ועוד פסוקי' כאלה מפני שנא' אלה<sup data-n=\"3388\">11</sup> המצו' אשר יעשה אותם האדם וחי בהם פי' האדם הוא האדם דאצי' שהוא בחי' הגדל' המדות דז\"א כנ\"ל ומה שהוא חי ע\"י המצות כלומר שנוסף &lt;ריח&gt;\nבו אורו' ומוחי' הוא דוקא ע\"י המצו' כמו ע\"י תפילין שנמשך וניתוסף בו מוחי' דאבא ע\"י שמניח תפילין והוא לפי שנא' בפ' שגנוז בהם מי גוי גדול כו' והם שרש נשמו' ישראל שעלו במחשבה הקדומ' דא\"ק כמאמר ישראל<sup data-n=\"3389\">12</sup> עלה במחשב\"ה וכידוע ומפני זה שורה אור אבא במוחי' דוקא וכמארז\"ל בראשית<sup data-n=\"3390\">13</sup> ברא בשביל<sup data-n=\"3391\">14</sup> ישראל שנק' ראשית כו' וכן בשביל ישראל שעלה במחשב' סתימא' דא\"ק האציל אור אבא להיו' בבחי' אור וכלי כו' וע\"כ בסיבת פ' מי גוי גדול שבתפילין דמארי עלמא נמשך מבחי' אור אבא תוספ' מוחי' בז\"א בבחי' אור מקיף כו' כמו שנמשך לאדם התחתון בחי' מוחי' מחכמ' דמל' דאצי' בנפשו בבחי' מקיף מפני התפילין שמניח שפ' קדש",[["3385","8","<b>שהקדב\"ה מניח תפילין</b>: ברכות ו, א."],["3386","9","<b>ותפילין דמארי עלמא</b>: שם."],["3387","10","<b>כי מי גוי גדול</b>: ואתחנן ד, ז."],["3388","11","<b>אלה המצות אשר יעשה אותם האדם</b>: חיבור ב' כתובים — בחוקותי כז, לד. אחרי יח, ה."],["3389","12","<b>ישראל עלה במחשב\"ה</b>: ראה ב\"ר פ\"א, ד."],["3390","13","<b>בראשית ברא</b>: בראשית א, א."],["3391","14","<b>בשביל ישראל שנק' ראשית</b>: ראה רש\"י בראשית א, א."]]],[2100990086,"גנוז בו אור חכמ' כו' וכמ\"ש במ\"א, ועד\"ז בשאר המצות כמו מצות החסד והצדקה למעלה הוא הנק' ח\"ס דלי\"ת להחיו'<sup data-n=\"3392\">15</sup> רוח שפלי' שהוא בחי' מל' דאצי' הנק' ד\"ל כמ\"ש אשרי<sup data-n=\"3393\">16</sup> משכי\"ל אל ד\"ל והוא שרש ענין ביקור חולים הנ\"ל שהוא גילוי אור האצי' במל' שהיא נק' חולת אהבה בגלותא כו' עי\"ז נמשך וניתוסף אור בכלי החסד דז\"א כו' ועד\"ז בפרטי שאר המצות עד שאמרו קיים אברהם אפי' ערובי תבשילי' כו' שהוא בחי' נצח שבחסד ע\"ד דוגמא כי לדמות מצוה זו במנין רמ\"ח הכלליי' הוא בערך פרק א' מפרקי האברי' כמו נצח שבחסד וכיוצא אחר שכל המצו' המה באו בציור איברי' א\"כ יש גם למצוה זו דע\"ת ג\"כ שרש ומקום אחיזה באיזה פרט מן האיברי' כו' כי כללות כולם נק' מצות הוי' וז\"ש מצוותי<sup data-n=\"3394\">17</sup> חוקותי דוקא וגם אנו או' אשר קדשנו במצוותיו במצוותיו דוקא ואחר שנשלם ברמ\"ח איברי' ע\"י המצו' אז נק' בחי' אדם בבחי' פרצוף שלם דהיינו בבחי' מוחין דגדלו' ומקור כל ההמשכו' הללו בז\"א ע\"י המצות הוא ע\"י אור אבא דוקא כי בחי' החכמה דאבא הוא הנק' ראשית והוא שרש כל אורו' האצי' כידוע וזהו פי' אברם בלא ה\"א כנ\"ל וכשמגדל אורו' דז\"א כנ\"ל נק' אברהם בתוס' ה\"א שהן בחי' ה\"ח המגדילי' כנ\"ל וד\"ל.\n<b>וזהו</b> ג\"כ שרש ענין ז' שמות שאינן נמחקין שהמה כולם בחי' אורו' בכלים כמו שם שהוא הכלי לאדם להתפס על ידו וז\"ש ויעש<sup data-n=\"3395\">18</sup> דוד ש\"ם פי' שהמשיך אור בכלי ונק' הכלי בשם עשי' כמ\"ש ויע\"ש דוד שם וכמו גם החכמה אחר שנאצלה בבחי' כלי יש לה בחי' שם מיוחד והוא שם<sup data-n=\"3396\">19</sup> הוי' בניקו\"ד פתח כו' וכן ת\"ת בשם הוי' ואלקי' בגבורה וכיוצא בזה בשאר השמו' ואמנם הגם שכבר נאצלו אורו' וכלים קודם שבא אברהם מ\"מ זאת היתה עבודתו להמשיך ולהוסיף אורות באצי' ממקור האצי' והוא מעצמו' המאציל ע\"י אהבה רבה במס\"נ כשהי' הלוך ונסוע הנגבה כנ\"ל לפי שבמס\"נ מאיר דוקא מעצמו' המאציל כי רוח<sup data-n=\"3397\">20</sup> אייתי רוח כו' וכתיב מי<sup data-n=\"3398\">21</sup> כה' אלקינו בכל קראינו אליו אלי\"ו<sup data-n=\"3399\">*21</sup> ולא למדותיו כו' וזהו שאמר אברהם לעצמו' אור א\"ס בשם א\"ד דוקא אל<sup data-n=\"3400\">22</sup> נא תעבור מעל עבדך ולכך לא<sup data-n=\"3401\">23</sup> הי' אדם שקרא להקדב\"ה אדון עד אברהם כידוע לפי שהמשיך אור א\"ס בשם א\"ד זה שהוא מז' שמו' הנ\"ל שיהי' מאיר בו באור חדש ובתוספ' מרובה ע\"כ לא קרא אדם לא\"ס בשם א\"ד כ\"כ בבחי' תוס' גילוי אור א\"ס עד אברהם כשאמר בשם א\"ד אל נא תעבור כלומר אל תעבור מלהאיר בשם זה דא\"ד דוקא וד\"ל ועד\"ז בשאר השמו' כו' וכל זה בחי'\n&lt;ריט&gt;",[["3392","15","<b>לחיו' רוח שפלי'</b>: ישעי' נז, טו."],["3393","16","<b>אשרי משכיל אל דל</b>: תהלים מא, ב."],["3394","17","<b>מצוותי חוקותי</b>: תולדות כו, ה."],["3395","18","<b>ויעש דוד ש\"ם</b>: שמואל-ב ח, יג."],["3396","19","<b>שם הוי' בניקוד פתח</b>: ראה פרדס (שער הנקודות) שכ\"ח, פ\"ה. פע\"ח (שער העמידה) ש\"ט, פי\"ט. סידור האריז\"ל ומ\"ח שם. ובאוה\"ת ואתחנן ע' שעט מציין לזוהר תולדות קמה, סע\"א."],["3397","20","<b>רוח אייתי רוח</b>: ראה זהר תרומה קסב, רע\"ב."],["3398","21","<b>מי כה' אלקינו בכל קראינו</b>: ואתחנן ד, ז."],["3399","*21","<b>אליו ולא למדותיו</b>: ראה פרדס שער (לב) הכוונה פ\"ב בשם הספרי. אלימה רבתי מעין א תמר א. ס' חרדים המצוה העיקרית רפ\"ה. וראה סה\"מ תקס\"ג ע' קכו — שארז\"ל בספרי. אמרי בינה פט\"ז."],["3400","22","<b>אל נא תעבור מעל עבדך</b>: וירא יח, ג."],["3401","23","<b>לא הי' אדם. . עד אברהם</b>: ברכות ז, ב."]]],[2100990087,"אברהם שהוא קיים כל התורה ברוחניו' בלבד דהיינו להוסיף אורו' בכלים למעלה והוא משום דאיהו וחיוהי וגרמוהי חד כו' כנ\"ל אבל לא קיים כל התורה למטה בעולם הנפרד כו' כי כדי שיבא אור א\"ס ע\"י המצו' גם למטה בבי\"ע עולמו' הנפרדי' צריך שיהי' הממשיך ממדרג' יותר גבוה מבחי' אור אבא שהוא אברם הנ\"ל המגדיל המדו' דז\"א שהרי אין שייכו' לאצי' עם הבריאה אחר סיום הקו ע\"י בחי' הפרסא המפסיק כו' אלא צריך שיבא האור ממעלה ומדרגה גבוה שהאצי' והעשי' שוין שם והוא בחי' א\"ק שנק' מחשבה הקדומ' שמשם נמשך שרש ומקור לנשמת משה שנא' בו כי<sup data-n=\"3402\">24</sup> מן המים משיתה\"ו מלפני כל ההשתלשלו' דאבי\"ע וגילוי שרשו מתחיל מבחי' חכמ' סתימא' דא\"א שהוא מקור לאור אבא כידוע דאבא<sup data-n=\"3403\">25</sup> יונק ממזל ונוצר כו' וזהו שנא' בהמשכת י\"ג מדה\"ר ויעבור<sup data-n=\"3404\">26</sup> ה' על פניו ויקרא ה' כו' דידוע בפי' ויקרא<sup data-n=\"3405\">27</sup> זה דקאי על משה והוא לפי שמשה<sup data-n=\"3406\">28</sup> משה לא פסיק טעמא כו' כמ\"ש<sup data-n=\"3407\">29</sup> במ\"א ביאור ענינו וע\"כ לא יש הפסק לגבי משה בין ב' הויו' הללו ולכך ויקרא משה הוי' הוי' פי' שקרא מן הוי' שהוא בחי' ההעלם דמחשבה הקדומה לגילוי אור בבחי' שם הוי' שבע\"י וא\"א שנקראו בשם כתר בכלל והוא שרש בחי' י\"ג תקוני' שנמשכי' מח\"ס דא\"א הנק' חכמה שבכתר וכידוע ולהיו' דבאברהם<sup data-n=\"3408\">30</sup> אברהם פסיק טעמא ע\"כ לא הי' ביכולתו להוריד אור א\"ס בתורה ומצו' גם למטה בבי\"ע עולמו' הנפרדי' אבל משה משה דלא פסיק טעמא כו' הי' ביכולתו להמשיך ולהוריד האור גם בבי\"ע.\n<b>ולהבין</b> ביאור הדברים הללו יש להקדים מאמר א' הנז' בזוהר<sup data-n=\"3409\">31</sup> בענין תלת עלמין עלמא קדמא' נהיר לאלף אלפי' כו' ועלמא תניינא לחמשין ושבעה אלפי' כו' ועלמא תליתא' לתשעי' ושית כו' ומבואר<sup data-n=\"3410\">32</sup> בספרי הקבלה דתלת עלמין הללו המה ג' עולמו' בי\"ע הנק' עולמו' הנפרדי' כידוע ומבחי' שם אל שהוא התיקון הראשון מי\"ג התיקוני' דא\"א מאיר ונמשך בג' עולמו' הללו וכשמאיר ונמשך בעולם הבריא' מתלבש בשם שד\"י ונק' אל שד\"י וכשמאיר ונמשך בעולם היצי' מתלבש בשם הוי' ונק' אל הוי' וכשנמשך ומאיר בעולם העשי' מתלבש בשם א\"ד ונק' אל א\"ד וגי' דאל שד\"י הוא שמ\"ה אותיו' מש\"ה ושם מאיר לאלף אלפים וריבוא רבבו' כו' ובעולם היצי' שגי' דהוי' עם אל עולה נ\"ז מאיר לנ\"ז אלפי' כו' ובעולם העשי' דגי' דא\"ד עם א\"ל עולה צ\"ו מאיר לתשעי' וששה אלפים כו' ואמנם",[["3402","24","<b>כי מן המים משיתהו</b>: שמות ב, י."],["3403","25","<b>דאבא יונק ממזל</b>: ראה ע\"ח שער הכללים פ\"ה. שער א\"א (שי\"ג) ספ\"ט. שער או\"א (שי\"ד) פ\"ג. שער הזווגים (שט\"ו) ספ\"ב. שער הולדת או\"א וזו\"נ (שט\"ז) פ\"ו. שער העיבורים (שכ\"ח) פ\"ב. שער הנסירה (שכ\"ט)."],["3404","26","<b>ויעבור ה' על פניו ויקרא</b>: תשא לד, ו."],["3405","27","<b>ויקרא זה דקאי על משה</b>: תשא לד, ו. וראה זח\"ג קלח, א."],["3406","28","<b>שמשה משה לא פסיק טעמא</b>: זהר וירא קכ, ב. נשא קל, א (באד\"ר). בלק קפז, ב. קרבן אהרן לתו\"כ ויקרא א, א ספ\"א."],["3407","29","<b>כמ\"ש במ\"א ביאור ענינו</b>: ראה ג\"כ תו\"א משפטים עה, ג. עו, ג. תו\"ח משפטים [הוצאת קה\"ת — תשס\"ג] רפג, ג. וראה לקו\"ש חכ\"ו ס\"ע 359 ואילך."],["3408","30","<b>דבאברהם אברהם פסיק טעמא</b>: נסמן לעיל ”שמשה משה\"."],["3409","31","<b>בזוהר בענין תלת עלמין</b>: זח\"ג קנט, א."],["3410","32","<b>ומבואר בספרי הקבלה. . ג' עולמו' בי\"ע</b>: רמ\"ז לזח\"ג שם."]]],[2100990088,"הנה אנו רואים שכולם מקבלים מבחי' אל דתיקון הראשון מי\"ג תיקוני' אלא שבריא' בשם אל שד\"י ושם הוי' ביצי' ג\"כ מבחי' אל כו', וזה פלאי לכאורה איך יהי' דילוג המדרגה כ\"כ מבחי' אל דתקוני' דא\"א שהוא מקור האצי' שיתלבש בבי\"ע כו', אך הענין הוא משום דאדרבה דלהיות עולמו' הללו המה בירידו' המדרגה ביותר צריך שיבא להם אור השפע ממקום עליון ביותר כי כדי שיבא האור עד למטה כ\"כ צריך שיבא ממקום הנעלה ביותר, וכידוע ענין הטעם בכלל הזה דלדבר נמוך ביותר צריך שיאיר ממקום גבוה ביותר כי לעוצם הרוממו' יוכל להשפיל א\"ע ביותר משום דערך עומק<sup data-n=\"3411\">33</sup> תחת לפי ערך עומק רום כמ\"ש בס\"י וכמבואר במ\"א וא\"כ היא הנותנת לומר ג\"כ דבעומק תחת מאיר דוקא מעומק רום כי &lt;רכ&gt;\nנעוץ<sup data-n=\"3412\">34</sup> תחלתן בסופן דוקא וכמ\"ש במ\"א באריכו', וזהו ענין האופן<sup data-n=\"3413\">35</sup> אשר בתוך האופן שלהיותו יותר מקיף כללי מכולם ע\"כ יסובב למעלה ולמטה בהשווא' א' משא\"כ אופן אשר מלובש בתוכו שאיננו מסבב כ\"כ למטה כמו האופן הסובב כולם לפי שאינו מקיף כללי לכללות הכל עליון ותחתון כמו האופן העליוני מכולם כו' והרי מובן מזה שכל היותר עליון יותר תחתון וזהו עצמו הטעם שבתחתון יהי' בא האור מהיותר עליון והיינו מה שאמרו ז\"ל ע\"פ ועברתי<sup data-n=\"3414\">36</sup> בארץ מצרים אני ולא מלאך כו' וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> ענין המאמר הזה בתלת עלמין הללו דהיינו ג' עולמו' הנפרדי' יש מאין ממש כו' שמקבלי' ההארה דוקא מאור ח\"ס דא\"א בתיקון הראשון דאל שמתלבש בג' שמו' הנ\"ל משום דכדי שיאיר האור כ\"כ למטה בעולם הפירוד צריך שיבא דוקא ממקום היותר גבוה והוא מבחי' אל דא\"א שהוא הכתר<sup data-n=\"3415\">37</sup> הממוצע בין עצמו' המאציל לנאצלי' כו' וד\"ל, ובזאת ההקדמה יובן ג\"כ הטעם בירידת התורה והמצו' בעולם הנפרד שהוא ע\"י משה דוקא להיותו מבחי' ח\"ס דא\"א כנ\"ל, וע\"כ הי' ביכולתו לקרו' הוי' הוי' והוא משום דלא פסיק טעמא כו' כמ\"ש בו מן המים משיתהו כו' וכנ\"ל וע\"כ דוקא ע\"י משה ניתנה התורה בעולם הנפרד בפעולה גשמי' ולא ע\"י אברהם כי שרש אברהם הוא רק בבחי' ג\"ר דאבא כנ\"ל אבל שרש בחי' משה הוא בח\"ס מקור דאור אבא כנ\"ל ושרש שרשו הוא מבחי' חכמה דא\"ק כנ\"ל וד\"ל.\n<b>וזהו</b> משה<sup data-n=\"3416\">38</sup> ידבר והאלקי' יעננו בקול. פי' משה הוא מבחי' שם מ\"ה דא\"ק כנ\"ל ואע\"פ שמתלבש בח\"ס ומשם עד חכמ' דאבי\"ע הרי אין כולם מסתירים לפני עצמו' המאציל וכענין האדם שיודע את מחשבו' ושכליו' עצמותו וסוקרם בעצמותו בסקירה א' כך כתיב בעצמו' אור א\"ס היוצר יחד לב\"ם כו' וכולא<sup data-n=\"3417\">39</sup> קמי' כלא חשיבי",[["3411","33","<b>עומק תחת. . עומק רום כמ\"ש בס\"י</b>: ראה ס\"י פ\"א מ\"ה. שה\"א י, א. שעה\"י קט, א."],["3412","34","<b>נעוץ תחלתן בסופן</b>: ס\"י פ\"א, מ\"ז."],["3413","35","<b>האופן אשר בתוך האופן</b>: יחזקאל א, טז."],["3414","36","<b>ועברתי בארץ מצרים אני ולא מלאך</b>: בא יב, יב. ספרי תבוא כו, ח. זהר (מהנ\"ע) וירא קיז, א. הגש\"פ."],["3415","37","<b>הכתר הממוצע</b>: ראה ע\"ח שער (מב) דרושי אבי\"ע פ\"א. סידור שו, ב."],["3416","38","<b>משה ידבר</b>: יתרו יט, יט."],["3417","39","<b>וכולא קמי כלא חשיבי</b>: ראה זהר בהקדמה יא, ב."]]],[2100990089,"ואינם מסתירי' כלל וא\"כ מובן מזה כשדבר<sup data-n=\"3418\">40</sup> ה' זו הלכה מאחר שנק' דברי<sup data-n=\"3419\">41</sup> אשר שמתי כו' הרי אין דבריו וגם חכמתו שמלובש בזה תופס' מקום בעצמותו ואינם מסתירי' כלל וע\"כ משה ידבר פי' ממשיך תמיד מן ההעלם לגילוי עד סוף כל המדרגו' מאור ח\"ס באין מסתיר לפניו כלל והוא רק ע\"י בחי' ביטול עצמותו וכענין הידוע בפי' ולא תחללו כנ\"ל וד\"ל, וזהו ענין יום מ\"ת דיומא<sup data-n=\"3420\">42</sup> דוקא גרים לפי שבשבועו' מאיר באור אבא מבחי' מקורא דכולא והוא בחי' חכמ' דא\"ק ע\"י שמתלבש בח\"ס הנ\"ל והוא הנק' גדלו' דאבא והטעם דיומא גרים לפי שנא' מש\"ה ידבר מש\"ה דוקא ומטעם הנ\"ל וד\"ל.\n<b>וז\"ש</b> וירד<sup data-n=\"3421\">43</sup> ה' על הר סיני כו' ענין ירידה זו ומה שהיא באש דוקא יובן בהקדים תחלה ההפרש בין תורה למצות. דהנה ידוע דבחי' א\"פ ובחי' א\"מ מצחצחי' את הכלי בחי' א\"פ מצחצח חצי עובי הכלי מבפנים ובחי' א\"מ מצחצח חצי הכלי מבחוץ וא\"כ ע\"י תורה ומצות ג\"כ מתצחצח הכלי והוא נפש האלקי' מזוהמת פסולת הנפש הבהמיו' ע\"י התורה מתצחצח מבפנים כי התורה<sup data-n=\"3422\">44</sup> נק' מזון לנפש והמצות נק' לבושי' וכמ\"ש בתורה ותורתך<sup data-n=\"3423\">45</sup> בתוך מעי ובמצו' נא' כי<sup data-n=\"3424\">46</sup> נר מצוה שנק' נר &lt;רכא&gt;\nכמו הנר שהוא כלי ולבוש והתורה נק' אור וע\"י אמצעו' שניהם מזדכך הנפש מבפנים ובחוץ והן ענין ב'<sup data-n=\"3425\">47</sup> חקיקו' שמבואר ע\"פ אם בחוקותי כנ\"ל ואז דבר ה' זו הלכה שהאדם לומד ה\"ז כאילו רוח ה' דובר בו ולנגד עצמו' אור א\"ס אין מסתיר כלל כמ\"ש היוצר<sup data-n=\"3426\">48</sup> יחד לבם כו' וזהו וירד ה' על הר סיני שזהו ענין ירידת אור א\"ס בכל דיבור ודיבור בד\"ת שהאדם לומד וירידה זאת באש כי זהו עד\"מ האש אשר נתון בתוך הכלי שמזדכך עי\"ז כל עובי הכלי מבפנים ובחוץ כנ\"ל אך מה שיוכל להיו' ירידה גדולה כזאת מעצמו' אור א\"ס עד היכלו' התחתוני' דבי\"ע הוא ע\"י משה<sup data-n=\"3427\">49</sup> שנק' שושבינא דמלכא שמוליך ומוריד אור א\"ס עד למטה מטה מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> משה ידבר מא\"א עד בי\"ע ימשיך ויוריד אור א\"ס בתורה ומצות שיעשה האדם כמו שעל ידו היתה ירידת ה' על הר סיני ובחי' משה יש בכל דור כידוע, אבל זהו מלמעלה למטה כנ\"ל ואח\"כ יעננו אלקי' מלמטה למעלה והוא שאמרו ז\"ל האלקי' יעננו בקול בקולו של משה דוקא כו'.\n<b>וביאור</b> הדברי' הנה ידוע דהתלמוד<sup data-n=\"3428\">50</sup> בבריא' והמשנה ביצי' ונמצא שיתא סדרי משנה באי' המה גם בבחי' ו\"ק דנוק' דעשי' בהתלבשו' והלומד מס' פיאה",[["3418","40","<b>כשדבר ה' זו הלכה</b>: שבת קלח, ב. עמוס ח, יב."],["3419","41","<b>דברי אשר שמתי</b>: ישעי' נט, כא."],["3420","42","<b>דיומא דוקא גרים</b>: ראה פסחים סח, ב."],["3421","43","<b>וירד ה' על הר סיני</b>: יתרו יט, כ."],["3422","44","<b>התורה נק' מזון</b>: ראה תניא פ\"ה."],["3423","45","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["3424","46","<b>כי נר מצוה</b>: משלי ו, כג."],["3425","47","<b>ב' חקיקות שמבואר ע\"פ אם בחוקותי כנ\"ל</b>: ראה לעיל ד\"ה אם בחוקותי תלכו ובביאורים."],["3426","48","<b>היוצר יחד לבם</b>: תהלים לג, טו."],["3427","49","<b>משה שנק' שושבינא דמלכא</b>: ראה זהר (רע\"מ) ויקרא כ, א. מצורע נג, ב."],["3428","50","<b>דהתלמוד בבריא'</b>: ראה אמרי בינה שער הק\"ש פנ\"ג (נב, ב) בשם הע\"ח. וראה תניא פ\"מ בהג\"ה אחרונה בפרע\"ח. [ראה שם שער (יז) הנהגת הלימוד, שם שער (ו) הקדישים פ\"ב]."]]],[2100990090,"מסדר זרעי' הוא מעורר בבחי' חסד דנוק' דעשי' וכיוצא ועד\"ז בשאר הסדרים, והנה בכל אדם מישראל יש בחי' קולו של משה בהיותו קורא ולומד בתורה ע\"י שדברי' חיים וקיימי' מאז אשר ירד ה' על הר סיני ע\"י משה וזהו פי' ומשה ידבר בתמידו' כמבואר למעלה וע\"י הקול שקורא ולומד ממשיך ומדבר מן המאציל אור א\"ס עד למטה כנ\"ל, והיינו עד שמתלבשת הארה זו בי\"ס דבי\"ע ובהגיע שמה אותה ההארה מבחי' קולו של משה אזי בחי' האלקי' אשר מחי' שם מאין ליש יעננו באותו הקול שהוא כענין שהקדב\"ה<sup data-n=\"3429\">51</sup> יושב וקורא ושונה כנגדו פי' כנגד אותו קולו של משה יעננו באותו קול לומר אחריו מה שהוא אומר כו' ע\"ד דוגמא כשלומד הלכה בסדר זרעים שהוא ממשיך אור א\"ס בקולו של משה בכלי חסד דנוק' דעשי' אזי שם אלקי' שמאיר באותה כלי הספי' דחסד דנוק' דעשי' יעננו באותו הקול לקרות ולשנות אותה דבר ההלכה שנאמרה למטה בקולו של משה כו' ונמצא עליונים למטה ותחתונים למעלה כי בחי' קולו של משה שהי' עליון וירד למטה נעשה למטה בחי' מקבל מקול האלקי' אשר יעננו בהגיעו להיכלו' דבי\"ע ותחתונים למעלה דשם האלקי' הזה הוא מבחי' השמו' שבמדרגו' התחתוני' דבי\"ע כי ידוע דק\"ך צרופי אלקי' מתלבשי' עד סוף העשי' כו' וד\"ל.\n<b>אך</b> הנה מ\"מ מצד ששרש קולו של משה הוא למעלה מן האצילו' כנ\"ל ע\"כ אין העניי' דשם האלקי' אלא לפי ערך קולו של משה דהיינו אם קול זה של תורה למטה הוא באיש שמעלתו ומדרגתו באוי\"ר גבוה מאד נעלה כמו נשמו' התנאי' ואמוראי' ומכ\"ש כמו ר\"ע ורשב\"י וכיוצא ודאי שערך מעלתם זה ימשיך אור א\"ס ב\"ה בקול שקוראי' ושונין בתורה יותר ממקום ומעלה נכבדת מקול קורא שיקרא איש אחר זולתם שנמוך מהם הרבה במדרגה כו' וא\"כ ודאי שערך העניי' שיעננו בקול אינו אלא לפי ערך ההמשכה בקולו &lt;רכב&gt;\nשל משה שהמשיך שם אם המשיך שם מקולו של משה שמלובש בנשמת צדיק למטה אזי האלקי' יעננו באותו אור ובאותה מדרג' ממש כענין מאמר אביתר<sup data-n=\"3430\">52</sup> בני אומר כו' ואם קולו של משה המשיך שם מקול של איש בינוני למטה לא יגיע שמה האור במדרג' גבוה אזי לא יעננו שם האלקי' דשם כ\"א באות' מדרגה בלבד ועד\"ז יובן גם בקטני הערך דמ\"מ הרי הקדב\"ה יושב ושונה כנגדו אמרו והיינו כנגד אותו שלומד יהי' מי שיהי' גם מבחי' האחרונ' דהיכלו' דעשי' כנגדו יקרא משם ויעננו בקולו של משה שיש באותו האדם כי משה ידב\"ר כתיב שימשיך וידבר עד סוף כל המדרגו' שבזה הוא מובדל במעלה מאברהם על היותו ממשיך התורה גם למטה מטה כנ\"ל, והיינו שאמר משה ידבר והאלקי' דוקא יעננו בקול גם שם אלקי' האחרון שבכל ההשתלשלו' מטעם הנ\"ל וד\"ל.",[["3429","51","<b>שהקב\"ה יושב וקורא</b>: ראה תדא\"ר רפי\"ח."],["3430","52","<b>אביתר בני אומר</b>: ראה גיטין ו, ב."]]],[2100990091,"<h3>ולהבין כל הנ\"ל בתוספת ביאור</h3>\n<b>ולהבין</b><sup data-n=\"3431\">*52</sup> כל הנ\"ל בתוספת ביאור יש להקדים תחלה שרש ענין אברהם. הנה אברהם<sup data-n=\"3432\">53</sup> נק' איש החסד כי שרשו הי' מבחי' חסד עליון ונק' איש החסד לפי שהמשיך אורו' בכלים וכמ\"ש ויקרא<sup data-n=\"3433\">54</sup> אברם בשם הוי' אל עולם פי' שקרא והמשיך בשם הוי' היינו שהוסיף אור בשם הוי' מן ההעלם לגילוי כו' וזהו כמשל המים<sup data-n=\"3434\">55</sup> המגדלי' כל מיני צמח או כמו ענין החלב שמגדל האיברי' בולד שנק' מוחי' דיניקה כנ\"ל ועיקר הענין הוא שע\"י הכנסת האורות ממילא נתרחבו הכלים ונגדלו בהגדלה מרובה כי ענין ההגדלה של הכלים הוא מה שנמצא בהם בחי' ההתכללות ממדה זו למדה אחרת זולתה כמו חסד שבגבורה שמתכללת בה בחי' גבור' שבחסד כו' וכיוצא בזה עד שימצא מדה א' כלולה מהרבה אופנים ומדרגות ואז נק' הכלי של החסד בבחי' הגדלה וריבוי מצד ריבוי ההתכללות, ועד\"ז בשאר המדות כו' וכל זאת ההגדלה והריבוי אינו אלא מצד המשכת וכניסת האורו' בריבוי ואזי ממילא נגדלי' בבחי' ההתכללו' הנ\"ל כמשל היניקה מן החלב שהולד יונק שעי\"ז ממילא נגדלו האיברים ומתרחבים וכן המים המגדלי' כל מיני צמח הגדלת הצמח ממילא בא ע\"י כניסת לחלוחי' המים בו כו' וכמבואר זה במ\"א בטעם יותר מבואר וד\"ל, וזהו ויקרא אברם שקרא והמשיך תוספ' אור למעלה מן האצי' ונכנס האור בריבוי וממילא נתרחב הכלי והוא בחי' השם דהוי' ע\"ד הנ\"ל וד\"ל.\n<b>ויובן</b> זה בתוספת ביאור הנה ידוע מארז\"ל בטעם שם<sup data-n=\"3435\">56</sup> שד\"י שאמר לעולמ\"ו ד\"י פי' אחר בחי' הגילוי של המאציל להאציל האורו' חזר ואמר לעולמו די שיהי' העלם וצמצום האור וא\"כ בכל פרצוף יש בחי' גילוי למעלה ובחי' העלם למטה ואברהם שהי' איש החסד היינו בחי' המגדל להיו' תוספ' גילוי גם בבחי' ההעלם אשר למטה כו' וזהו שקרא בשם הוי' אל עולם פי' אל הוא בחי' חסד והוא בחי' גילוי אור אלקי ועולם הוא בחי' העלם של הכלי ולפי שהמשיך בשרש האצילו' המשכת תוספת אור ע\"כ המשיך גם בשם הוי' למטה דהיינו בכלים דז\"א שיהי' גם שם נק' אל עולם דהיינו בבחי' גילוי תוספת האור בכלי ואז ממילא נתרחב הכלי כנ\"ל וד\"ל. ואמנם יש בזה עוד ענין א' שלא הי' בחי' גילוי אור תוספ' זה אלא למעלה באצי' בלבד &lt;רכג&gt;\nומשום דאור האצי' מיוחד ומקושר במאציל עצמו דהא איהו וחיוהי וגרמוהי חד כנ\"ל אבל למטה בבי\"ע לא הגיע כ\"כ בחי' תוספת גילוי אור זה שהרי לפי המבואר בפי' ויקרא אברם כו' הי' מהראוי שיהי' בחי' גילוי אור האלקי גם למטה מטה בבי\"ע וא\"כ הי' מהראוי שיתוספו גרים מאוה\"ע ע\"י אברהם לאלפים ורבבו' גם בעוה\"ז השפל החומרי ולא מצינו בנפש<sup data-n=\"3436\">57</sup> אשר עשה כו' כ\"א רק שי\"ח",[["3431","*52","<b>ולהבין כל הנ\"ל בתוספת ביאור</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025.\nנוסח אחר (הנחת המהרי\"ל) נמצא בכת\"י 80 עב, ב. 392 של, א. 1824 ה, ג. ומתחיל: משה ידבר. — נדפס בתו\"א סח, ד."],["3432","53","<b>אברהם נק' איש החסד</b>: ראה זהר בראשית מז, ב. וראה ארחות צדיקים שער יז, הובא באוה\"ת וירא צ, ב. וראה גם בארוכה סה\"מ תרח\"ץ ע' קכט ואילך."],["3433","54","<b>ויקרא אברם בשם הוי' אל עולם</b>: חיבור ב' כתובים לך יג, ד. וירא כא, לג."],["3434","55","<b>המים המגדלי' כל מיני צמח</b>: ראה תניא פ\"א (ה, סע\"ב.)."],["3435","56","<b>שם שדי שאמר לעולמו די</b>: ראה ג\"כ סה\"מ תרל\"ב ח\"ב ע' שנג."],["3436","57","<b>בנפש אשר עשה</b>: ראה לך לך יב, ה ובפרש\"י."]]],[2100990092,"אנשים כמספר אליעזר כידוע בדברי רז\"ל<sup data-n=\"3437\">58</sup> בפי' וירק<sup data-n=\"3438\">59</sup> את חניכיו כו' ואף באותם שי\"ח אנשים לא נמשך בחי' גילוי אלקו' ע\"ד שהוא במדרג' העליונה אלא רק בבחי' אמונה בלבד כו' אלא ודאי שלא הגיע אור תוספ' הנ\"ל למטה בבי\"ע כ\"א מעט מזעיר בהארה דהארה בצמצום גדול ולכך לא נתגיירו רק שי\"ח אנשים כו' ועיקר הגילוי הי' למעלה באצי' בלבד ומטעם דאיהו וכו' וכנ\"ל וד\"ל.\n<b>ועד\"ז</b> יובן מ\"ש ויטע<sup data-n=\"3439\">60</sup> אשל בבאר שבע כידוע שעשה גמ\"ח גדולים עם הבריו' דודאי צדקה וחסד זה בהעלא' מ\"ן שלו גרם למעלה תוספת גילוי אור בכלי החסד דאצי' אבל לא הגיע בחי' תוספ' גילוי אור זה למטה רק מעט מזעיר כנ\"ל ועיקר הגילוי הי' למעלה באור החסד דאצי' ומטעם הנ\"ל ועד\"ז כל העובדו' שעשה אברהם הכל הי' רק בחי' גילוי תוספ' אור למעלה בלבד כנ\"ל וד\"ל.\n<b>והנה</b> כל מה שהמשיך אברהם תוספ' אורו' בכלים למעלה לא היה רק לפי ערך בחי' העלא' מ\"ן שלו מלמטה במס\"נ בעובדא ובדיבור כו' כידוע המאמר דרוח אייתי ואמשיך רוח כו' ולפי ערך ההעלא' הוא ערך ההמשכה וזהו ענין ז' שמות שאינן נמחקין שעשה אברהם למעלה ע\"י בחי' העלא' מ\"ן שלו, אך יש להבין מהיכן יבא הסיבה להיות בחי' תוספת אור ע\"י ההעלאו' מ\"ן כו' עד שמפני זה אמר שנחשב כאילו עשה לשם מחדש וכענין ויעש דוד שם שר\"ל שעשאו מחדש כו'.\n<b>הענין</b> יובן בהקדים לזה ענין אחר המבואר בס'<sup data-n=\"3440\">61</sup> לק\"א להה\"מ ז\"ל ע\"פ בעמדם תרפינה כנפיהם פי' בעמדם של בנ\"י למטה בתפלה בלחש אז תרפינה כנפיהם של המלאכי' למעלה כי בחי' כנפיהם הם בחי' אוי\"ר של המלאכי' כידוע שהאוי\"ר<sup data-n=\"3441\">62</sup> נק' גדפין כי המה בבחי' רצוא ושוב כמו הפריחה בכנפים כו' ולפי שרואי' המלאכי' מעלת אוי\"ר של כנ\"י בעמדם בתפלה ע\"כ נופלים ממדרגת אוי\"ר שלהם וממילא תרפינה כנפיהם ומורידי' אותם למטה מפני בחי' ביטול במציאו' שלהם כו', ולכאורה אינו מובן איך יהי' מדרג' אוי\"ר דכנ\"י למטה גבוה מאוי\"ר של המלאכי' הלא אוי\"ר דכנ\"י אחר שנשמות שלהם מלובשי' בחומר גופני בהכרח שהאוי\"ר ג\"כ מגושם כו' ואוי\"ר של המלאכי' שהמה בחומר רוחני ודאי שהמה במעלה ומדרג' יותר כו', אך הענין הוא כך כי אוי\"ר של כנ\"י הגם שהם ודאי מצד עצמם למטה ממדרג' אוי\"ר של המלאכי' אבל מצד שרשם שמעוררי' למעלה כי רוח אייתי רוח כו' ונמשך אוי\"ר מלמעלה למטה ונמשך ובא בהשתלשלות מעילה לעילה עד שבא לעולם המלאכי' ולהיותו להם בחי' אור חדש כי הנה הוא בא ממקום גבוה הרבה ממדרג' המלאכי' ע\"כ תרפינה כנפיהם בעברו דרך עליהם והגם שבירידת",[["3437","58","<b>בדברי רז\"ל</b>: ראה זהר (סתרי תורה) פ, ב. וראה תו\"א יתרו סח, ד."],["3438","59","<b>וירק את חניכיו</b>: לך לך יד, יד."],["3439","60","<b>ויטע אשל בבאר שבע</b>: בראשית כא, לג."],["3440","61","<b>בסי' לק\"א להה\"מ ז\"ל ע\"פ בעמדם תרפינה</b>: יחזקאל א, כד-כה. או\"ת (הוצאת קה\"ת) סח, א. וראה תו\"א סט, א."],["3441","62","<b>שהאוי\"ר נק' גדפין</b>: ראה גם תו\"ח בראשית ו, ד. שמות תכו, א."]]],[2100990093,"אור זה למטה בכנ\"י נעשה בבחי' ומדרג' נמוכה &lt;רכד&gt;\nממדרג' המלאכי' כנ\"ל אבל בירידתו מלמעלה למטה דרך עולם המלאכי' להיותו שם בחי' אור חדש למעלה הרבה מהם ע\"כ תרפינה כנפיהם וזהו בעמדם תרפינה כנפיהם בעמד\"ם דוקא כי רוח אייתי רוח כנ\"ל וד\"ל, וע\"ד דוגמא זו המשיך אברהם תוספ' אור חדש בשמות וכלים של האורו' שהי' מלובשי' מכבר עי\"ז נתבטל בחי' מציא' הכלי והשם הראשון וכאילו נעשה מחדש ע\"י גילוי אור תוספ' זה להיותו גבוה הרבה וכאילו לא ראו אור עדיין לנגד גילוי אור חדש זה כו' והיינו כמו ויעש דוד שם כו' כך עשה אברהם ז' שמו' הנ\"ל מחדש וע\"י אתעדל\"ת דוקא מטעם הנ\"ל כי רוח אייתי רוח והגם שאינה באה אלא לפי ערך מ\"מ אור חדש יאיר עי\"ז כנ\"ל בפי' בעמד\"ם כו' וד\"ל.\n<b>והנה</b> עיקר ענין הגדלו' האורו' בכלים למעלה הוא ע\"י המצות שהקדב\"ה עושה כמו מה שהקדב\"ה<sup data-n=\"3442\">63</sup> מניח תפילין והקדב\"ה מבקר חולים<sup data-n=\"3443\">64</sup> כו' וז\"ש עקב<sup data-n=\"3444\">65</sup> אשר שמע אברהם בקולי וישמור משמרתי מצוותי כו' והיינו שקיים כל התורה כו' וכנ\"ל וביאור הדברי' מבואר קצת למעלה ולהבין בתוספת ביאור בפרטי המצות הנה מה שאמרו ז\"ל שהקדב\"ה מבקר חולים כו' הענין הוא להיות כי אמרו ז\"ל בת<sup data-n=\"3445\">66</sup> היתה לאברהם ובכל שמה כו' והוא בחי' מל' דאצי' שנק' בכ\"ל וכמ\"ש ומלכותו<sup data-n=\"3446\">67</sup> בכ\"ל משלה ובגלותא שהמלכות מסתתרת בבי\"ע בתכלית ההסתר וההעלם כנודע אזי היא בבחי' חולת אהבה כלפי ז\"א דאצי' בעלה כו' כי כל בחי' ריחוק גורם ענין חולת אהבה וכידוע ומבואר במ\"א וקצת מזה יובן עד\"מ מכל השפעת עילה ועלול שטבע העלול להיות תשוקת דביקותו בתמידו' אל העילה באהבה רבה וכאשר יתרחק העלול מן העילה מאד מאד אזי יתעורר תגבורת התשוקה מפני העדר הקירוב ואז יהי' אור האהבה חלש וגרוע מצד העדר מילואה בקירוב הנאהב עד שיגרום בחי' חולי לעלול בעבור ההעדר ונק' זה בשם חולת אהבה כידוע וביקור חולי זה הוא כשיבא בחי' קירוב מן העילה לעלול שלו ויתגלה לו בדברי אהבה וקירוב זאת תהי' רפואת החולי להשיב נפשו ממש וזהו המשל להבין למעלה בבחי' ז\"א דאצי' שהוא הקדב\"ה שמרפא בחי' חולת אהבה דמל' דאצי' בגלותא דכתיב בה בגלותא כי<sup data-n=\"3447\">68</sup> חולת אהבה אני כו' והוא מצד מדת החסד ח\"ס דלי\"ת כנ\"ל והוא ענין החסד שעשה אברהם למעלה ע\"י בחי' העלא' מ\"ן שלו כנ\"ל עם בתו שנק' בכ\"ל וגם נק' בת<sup data-n=\"3448\">69</sup> נדיב בתו של אברהם כו' וד\"ל ועד\"ז ענין מצות תפילין שהקדב\"ה מניח למעלה כו' ולמטה הי' זה שאברהם המשיך בעולם אחדו' ה' וע\"כ כתיב בתפילין<sup data-n=\"3449\">70</sup> דמארי עלמא מי גוי גדול כו' ומי כעמך ישראל גוי אחד וכיוצא כו' וכנ\"ל וד\"ל.",[["3442","63","<b>שהקדב\"ה מניח תפילין</b>: ברכות ו, א."],["3443","64","<b>והקדב\"ה מבקר חולים</b>: סוטה יד, א."],["3444","65","<b>עקב אשר שמע</b>: תולדות כו, ה."],["3445","66","<b>בת היתה לאברהם</b>: ב\"ב טז, ב."],["3446","67","<b>ומלכותו בכ\"ל משלה</b>: תהלים קג, יט."],["3447","68","<b>כי חולת אהבה אני</b>: שה\"ש ב, ה."],["3448","69","<b>בת נדיב בתו של אברהם</b>: שה\"ש ז, ב. סוכה מט, ב."],["3449","70","<b>בתפילין דמארי עלמא מי גוי גדול כו' ומי כעמך ישראל גוי אחד</b>: ברכות ו, א. דברים ד, ז. דברי הימים-א יז, כא."]]],[2100990094,"<b>ועתה</b> להבין בתוספת ביאור ענין ההפרש בין אברהם למשה כנ\"ל. דהנה אמרו בזוהר<sup data-n=\"3450\">71</sup> באד\"ר דאית חסד ואית חסד כו' א' בחי' חסד דז\"א והוא חסד שלמטה מן החכמה והב' חסד דא\"א והוא הנק' ורב חסד שלמעלה מן החכמה כו' והנה שרש נשמת משה הי' משמטה הראשונה שלפני זאת השמטה ויש בזה ב'<sup data-n=\"3451\">72</sup> דיעות בספרי הקבלה אם שמטה שלפני זו היתה שמטה &lt;רכה&gt;\nמז' אלפי' שני' והנכון כדעת האריז\"ל שהוא ענין עולם התוהו שלפני עולם התיקון כו' וכמ\"ש ביאור זה במ\"א, ועכ\"פ יהי' איך שיהי' בחי' משה הוא מלפני השתלשלו' דאצי' וע\"כ נא' בו מן<sup data-n=\"3452\">73</sup> המי\"ם משיתהו פי' מן בחי' מים העליוני' שלפני בחי' האצי' שבבחי' התיקון כו' ולכך נא' במשה ויקרא הוי' הוי' וכנ\"ל שמשה הוא הקורא שפע והמשכה מלפני האצי' והיינו שקורא וממשיך מבחי' רב חסד דא\"א או ממזל ונוצר חסד להיו' מקור ושרש לאור אבא שבאצי' וכידוע דאור<sup data-n=\"3453\">74</sup> אבא אינו מקבל רק ממזל ונוצר כו', וזהו ההפרש בין אברהם למשה דשרש אברהם הי' מרכבה רק לבחי' חסד דז\"א ושרש משה לבחי' חסד דא\"א כו' וד\"ל.\n<b>והנה</b> ידוע ההפרש בין השתלשלו' למעלה מן ההשתלשלו' שהוא עד\"מ באדם שיש ערך ושייכו' לשכל עם המדו' והמדו' עם הדיבור כו' עד שיש עי\"ז חיבור וקישור לשכל גם עם המעשה אע\"פ שזה רוחני וזה גשמי אבל מבחי' עצמו' הנפש המובדלת בערך גם מבחי' השכל להיותה כח היולי כו' הרי אין הפרש לגבה בין שכל למעשה ושניהם שוין בערך כו' וכך יובן למעלה דלגבי עצמו' המאציל שוה ומשוה ראשית כל השתלשלו' עם אחרית כל כו' וכמ\"ש מגיד<sup data-n=\"3454\">75</sup> מראשית אחרית כו' עד שרוחניו' וגשמיו' שוין שם וכמ\"ש כחשיכה<sup data-n=\"3455\">76</sup> כאורה כו' וכולא<sup data-n=\"3456\">77</sup> קמי' כלא חשיבא בהשווא' א' ממש כמ\"ש קטן<sup data-n=\"3457\">78</sup> וגדול שם הוא כו' והיינו בחי' הדיעה שלפני המאציל שההשתלשלו' נק' אין כי כלא חשיב כו' והוא הדיעה העליונ' שהיא מלמעלה למטה היפך הדיעה הב' שמלמטה למעלה כו' ואמנם הנה לפי הדיעה שמלמעלה למטה הרי יכול אור א\"ס לשכון גם בעניני' גשמיים כמו בעניני' רוחניים אחר ששניהם שוין כו', וזהו כענין האופן אשר בתוך האופן שהעליון מקיף לכולם כו' וכנ\"ל, ויובן זה עד\"מ מחשבה כללית באדם שיחשוב כללות ענין א' בסקירה א' שהגם שיש בו פרטיים הרבה יסקור אותם במחשבה אחת והנה מחשבה זו נעשית במוחו כמו בחי' עיגול גשמי למטה בציור אחר שמחשבה זו סוקר להרבה פרטיים",[["3450","71","<b>בזוהר באד\"ר דאית חסד ואית חסד</b>: ראה זח\"א ריט, א. זח\"ג קלג, ב. וראה אוה\"ת וירא צ, א. ואילך."],["3451","72","<b>ב' דיעות בספרי הקבלה</b>: בתו\"א שמות נא, ד מציין: בהקדמה לתמונה ג דכ\"ז כ\"ט ל\"א. ראה פרדס שער (כא) פרטי השמות ספ\"ג. סידור תפלה למשה — להרמ\"ק — בפי' ה' מלך (לח, ב). שיעור קומה — להרמ\"ק — ספ\"ג. הרח\"ו באור החמה שמות י, א. שער מאמרי רשב\"י לאדרא רבא רלב, א. לקו\"ת וספר הליקוטים להאריז\"ל ר\"פ קדושים. מגלה עמוקות אופן סד. סה. תו\"ח שמות נט, (א) ב ואילך. סה\"מ תרס\"ח ע' מז. לקו\"ש בראשית חיו\"ד ע' 176."],["3452","73","<b>מן המים משיתיהו</b>: שמות ב, י."],["3453","74","<b>דאור אבא. . ונוצר</b>: ראה זהר (אד\"ז) האזינו רפט, ב."],["3454","75","<b>מגיד מראשית אחרית</b>: ישעי' מו, י."],["3455","76","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["3456","77","<b>וכולא קמי' כלא חשיבא</b>: זח\"א יא, ב."],["3457","78","<b>קטן וגדול שם הוא</b>: איוב ג, יח."]]],[2100990095,"יחד מכל צד בהשווא' ה\"ז כמו בחי' עיגול רוחני במחשבה שיחשוב בדבר לציירו ולהקיפו במחשבתו מכל צדדיו כו' וזהו המשל להבין למעלה בחי' מקיף היותר עליון המקיף לכללו' כל ההשתלשלו' דאבי\"ע בהשווא' א' למעלה ולמטה וכמ\"ש ומתחת<sup data-n=\"3458\">79</sup> זרועו' עולם והוא הנק' בחי' כתר בכלל כמו הכתר על הראש שיקיף בעטרה סביב הכל בהשווא' כו' וכמ\"ש במ\"א והוא נק' בחי' א\"א דאצי' שהוא המקיף הכללי לגבי השתלשלו' דאבי\"ע וד\"ל ולהיות כי שרש נשמת משה הי' מבחי' שמטה הראשונ' שלפני ההשתלשלו' כנ\"ל ע\"כ היה ביכולתו דוקא להוריד התורה והמצות שהן בחי' תוספ' גילוי אורו' למעלה באצילו' כנ\"ל באברהם שיוכלו להתלבש גם בענינים גשמיים שבעוה\"ז השפל כמצות תרומו' ומעשרו' בתבואה גשמי' ומצות הצדקה בכסף ומצות התפילין בקלף גשמי וכיוצא לפי שאין הפרש בין גשמיו' לרוחניו' לפני עצמו' אור א\"ס שלפני ההשתלשלו' מטעם הנ\"ל להיותו בחי' הכתר הנק' מקיף הכללי וכענין האופן אשר בתוך האופן וכנ\"ל ואין הארה זו מאיר אלא ע\"י בחי' משה דוקא מטעם הנ\"ל והוא כמו הדיעה הא' שלפני עצמו' המאציל וכנ\"ל וכמ\"ש בו אני<sup data-n=\"3459\">80</sup> &lt;רכו&gt;\nה' לא שניתי בין קודם ההשתלשלו' לאחר ההשתלשלו' כו' אך א\"א להמשיך אור זה כ\"א בבחי' ביטול עצמותו מכל וכל והוא הנק' ביטול במציאו' וכמו שהי' לימודו<sup data-n=\"3460\">81</sup> של רב יהודה ולכך הי' פטור מן התפלה שלא התפלל אלא מל' יום לל' יום לפי שהי' תמיד בבחי' הביטול וכמו שאמרו עליו אין זה ילוד אשה שהי' אימתא דמארי' עלי' תמיד כו' ועד\"ז יובן בשאר צדיקי' שלומדי' עד\"ז שהוא אפס קצה המדרג' מבחי' משה ולכך נק' כל ראש ישיבה בשם משה וכמאמר רב ספרא לרבא משה<sup data-n=\"3461\">82</sup> שפיר קאמרת לפי שהי' ממשיך בחי' ביטול לכל בני הישיב' כו' וד\"ל.\n<b>וזהו</b> משה ידבר כו' פי' דוקא משה כי הוא מן המים העליונים שלפני שמטה זו כנ\"ל ע\"כ הוא ידב\"ר וימשיך אור התורה תמיד בכל דור ובכל זמן וכנ\"ל, ובזה ג\"כ יש ב' מדרגו' תורה ומצות והוא בחי' שם מ\"ה ושם ב\"ן שם מ\"ה בתורה שבא ע\"י בחי' ביטול כנ\"ל ושם ב\"ן במצות לעשו' בחי' כלי לאור כו' וכנ\"ל והוא ענין ירידת התורה על הר סיני באש כמ\"ש כי<sup data-n=\"3462\">83</sup> ה' אלקיך שהוא בחי' מ\"ה וב\"ן כידוע אש אוכלה הוא לברר וללבן בחי' חיצוניו' ואחוריי' שנאחזי' בכלים עד\"מ האש הניתן בכלי ללבנו מכל צד וכנ\"ל וד\"ל.\n<b>והנה</b> עיקר טעם הירידה הזאת באש על הר סיני ובכל דור וזמן בבחי' משה כנ\"ל הוא כדי לברר וללבן חיצוניו' העולמו' דבי\"ע ולהעלותם עד שיהיו שוין במדרגה לבחי' אורו' דעולם האצי' דעכשיו וכמ\"ש כי<sup data-n=\"3463\">84</sup> שמים כעשן נמלחו כו' הנני עושה שמים חדשים וארץ חדשה כו' דמשמעות זה הוא שיתחדשו העולמו' כאילו",[["3458","79","<b>ומתחת זרועו' עולם</b>: האזינו לג, כז."],["3459","80","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["3460","81","<b>לימודו של רב יהודה. . פטור מן התפלה</b>: שבת יא, א. וראה תו\"א מקץ לח, ד. סט, א. אוה\"ת ויקרא ע' רנה-ו."],["3461","82","<b>משה שפיר קאמרת</b>: שבת קא, ב."],["3462","83","<b>כי הוי' אלקיך. . אש אוכלה הוא</b>: ואתחנן ד, כד."],["3463","84","<b>כי שמים כעשן נמלחו</b>: ישעי' נא, ו."]]],[2100990096,"נבראו מחדש ע\"י הברורי' והוא ע\"י התורה ומצו' שמים חדשי' נעשי' ע\"י רזין דאוריי' וסודו' התורה וארץ חדשה ע\"י הנגלה שבתורה כו' ועיקר הענין הוא שיתהפך בי\"ע להיו' במעלת ומדרג' אור האצי' כו' והמופת לזה מובן ממה שאמרו ז\"ל עתידים<sup data-n=\"3464\">85</sup> צדיקים שיאמרו לפניהם קדוש כו' וזה פלאי לכאורה, אך הענין הוא אחר שיתעלה בי\"ע להיות בבחי' האצי' דעכשיו וכמ\"ש שמים<sup data-n=\"3465\">86</sup> חדשים כו' א\"כ כמו שאומרי' המלאכי' קדוש לפני בחי' אורו' דז\"א דאצי' שנק' קדו\"ש וכידוע כך יאמרו לעתיד לפני הצדיקים שביררו בבי\"ע בחי' רפ\"ח ניצוצי' ע\"י תורה ומצו' ג\"כ קדוש כי עי\"ז יתהפך בחי' בי\"ע להיו' בבחי' האצי' וכמ\"ש ביום<sup data-n=\"3466\">87</sup> ההוא יהי' ה' אחד ושמו אחד למהוי<sup data-n=\"3467\">88</sup> אחד באחד כו' וד\"ל.\n<b>וזהו</b> משה ידבר והאלקים יעננו כו' האלקים דוקא פי' שם אלקי' זה הוא ענין ק\"ך<sup data-n=\"3468\">89</sup> צרופי אלקי' שיורדי' ומתלבשי' עד סוף עולם העשי' כידוע וע\"י שמתברר מבי\"ע לבחי' אצי' כנ\"ל ע\"י לימוד התורה ע\"כ אמר והאלקי' יעננו מפני ששם ב\"ן דאלקי' מתהפך להיו' ג\"כ בבחי' שם מ\"ה דאצי' למהוי אחד באחד כנ\"ל, וזהו שאמר יעננו לשון עניי' כי ענין העניי' הוא רק לומר הדבר כמו שאומר הקורא בלתי שינוי כלל וכענין העונה אחר המקרא את ההלל וכידוע מארז\"ל עונה<sup data-n=\"3469\">90</sup> אחריו מה שהם אומרים כו' והענין הוא לפי שע\"י המשכת בחי' ביטול דמשה מעצמו' המאציל להוריד למטה כנ\"ל בקריאתו בתורה ע\"ד לימוד דרב יהודה וכיוצא כנ\"ל כך אלקים יעננו לומר אותו דבר הלכה להתהפך משם אלקי' &lt;רכז&gt;\nולהיו' בבחי' שם מ\"ה וזהו שאמרו שהקדב\"ה יושב וקורא ושונה כנגדו והוא מ\"ש והאלקי' יעננו בקו\"ל כו' וד\"ל.\n<b>אך</b> הנה מה שאמרו ז\"ל בקולו של משה דוקא כנ\"ל יובן בהקדים ענין א' בביאור מאמר רז\"ל דהעוסק<sup data-n=\"3470\">91</sup> במקרא מדה ואינו מדה כו' משום דלכאורה עפ\"י הקבלה ג\"כ הענין כן שהרי מבואר בכתבי<sup data-n=\"3471\">92</sup> האריז\"ל דמקרא בעשי' ומשנה ביצי' ותלמוד בבריא' כו', אמנם באמת ביאור דבר זה דהמקרא בעשי' כו' נהפוך הוא מכפי הנראה לכאורה שזהו מעלה ומדרגה האחרונה אלא אדרבה זהו מעלה יותר גבוה כי פי' מה שאמר שהתלמוד בבריאה הכונה כך הוא שבחי' המשכת גילוי אור א\"ס אינו נמשך אלא ממאציל לאצי' ומאצי' עד עולם הבריאה ויותר אינו נמשך עוד והמשנה ביצירה רצונו לומר דאור א\"ס נמשך בלימוד המשנה מן המאציל לאצי' ומאצי' עד עולם הבריא' ומבריא' עד עולם היצי' ולא יותר כו' והמקרא בעשי' ר\"ל",[["3464","85","<b>עתידים צדיקים שיאמרו לפניהם קדוש</b>: ב\"ב עה, ב."],["3465","86","<b>שמים חדשים</b>: ישעי' סה, יז."],["3466","87","<b>ביום ההוא יהי' הוי' אחד</b>: זכרי' יד, ט."],["3467","88","<b>למהוי אחד באחד</b>: זהר תרומה קלה, סע\"א."],["3468","89","<b>ק\"ך צרופי אלקי'</b>: ראה ע\"ח (שער הזיווגים) שט\"ו, פ\"ו. (שער השמות) שמ\"ד, פ\"ה."],["3469","90","<b>עונה אחריו מה שהם אומרים</b>: ראה סוכה לח, ב. וראה תו\"א סח, ג."],["3470","91","<b>דהעוסק במקרא מדה ואינו מדה</b>: ראה ב\"מ לג, א. ראה מאמרי אדה\"א שמות ח\"א ס\"ע עו ואילך. נביאים וכתובים ס\"ע תד ואילך."],["3471","92","<b>בכתבי האריז\"ל דמקרא בעשי'</b>: ראה פרע\"ח שער (יז) הנהגת הלימוד. באמרי בינה שער הק\"ש פנ\"ג (נב, ב) — בשם הע\"ח. ראה תניא פ\"מ בהג\"ה אחרונה — בפרע\"ח. וראה תו\"א יז, א."]]],[2100990097,"שנמשך בלימודו גם עד העשי' ועד בכלל, וזה ידוע דכל שהאור יוכל לימשך עד מדרג' היותר תחתון מוכרח שיהי' האור ממקום ומדרגה היותר עליון מטעם שכל היותר עליון יותר יוכל להשפיל א\"ע כנ\"ל בפי' האופן אשר בתוך האופן כו' וא\"כ מובן שהמקרא גבוה מכולם אחר שאור א\"ס יוכל לשכון ע\"י המקרא גם בעולם העשי' היותר אחרון והמשנה למטה ממנה במדרג' אחר שאין אור א\"ס יורד עוד למטה מבחי' היצי' כו' והתלמוד למטה מן המשנה אחר שעל ידי לימודו לא ירד אור א\"ס גם למטה מבחי' עולם הבריא' כו' וכמ\"ש במ\"א<sup data-n=\"3472\">93</sup>, וגם ע\"ד הפשוט הרי המקרא עיקר ועליו נשנה המשנה ועל המשנה מפרש התלמוד כו' ולכך אינו מובן מה שאמרו דעוסק במקרא גרוע מעוסק בתלמוד כו' אלא הענין הוא שבאמת מעלת המקרא גבוה מכולם אלא לפי שאין זה ביכולת האדם להמשיך למטה כ\"כ עד העשי' כו' לכך טוב יותר עסק התלמוד לפי שבנקל להמשיך אור א\"ס בעולם הבריא' כו' וד\"ל ואמנם הנה ע\"י משה הרי נמשך ההארה שיהי' גם התלבשו' אור א\"ס בתחתית כל המדרגו' כנ\"ל וז\"ש והאלקי' יעננו בקול בקולו של משה דוקא לפי שיש בבחי' קולו של משה דוקא כח זה להוריד כ\"כ למטה עד שהאלקים יעננו גם לקורא במקרא שהוא בעשי' עד אשר כל א' מישראל כשיקרא פסוק א' בכתובי' ימשיך אור א\"ס באותו המדרגה באשר הוא שם לפי שאותו הפסוק נאמר בקולו של משה לכך בהכרח שהאלקי' יעננו ויקרא אותו הפסוק כנגדו דהיינו כנגדו ממש וכנ\"ל וזהו פי' שהקדב\"ה קורא פי' הקדב\"ה הוא בחי' מל' ובבחי' עולם הבריא' מתלבש העניי' במל' דבריא' והוא בלימוד התלמוד בדרך כלל ובלימוד המשנה אלקים יעננו במל' דיצי' כו' ובלימוד המקרא אלקי' דעשי' יעננו בקול והכל בקולו של משה דוקא כו' וד\"ל.\n<b>ועדיין</b> יש להבין למה לא נמשך להיו' אלקי' יעננו כו' גם בלתי קריא' למטה במקרא ומשנה כו' אחר שהתורה כבר ירדה ע\"י משה כו'. אך הענין הוא משום דצריך לעורר למעלה בחי' ענוה ושפלו' דמשה בחי' מ\"ה כמ\"ש ונחנו<sup data-n=\"3473\">94</sup> מ\"ה ועי\"ז במקום<sup data-n=\"3474\">95</sup> גדולתו כו' גם למעלה ירד אור א\"ס להיו' מאיר בבחי' דילוג שלא לפי סדר ההשתלשלו' כנ\"ל ע\"כ אמר שהקדב\"ה שונה כנגדו דהיינו דוקא כשהאדם קורא ושונה אבל בלא קריא' &lt;רכח&gt;\nהאדם א\"צ לקרו' ולשנו' למעלה אחר שהתורה ירדה שמה כבר אלא מפני שצריך לעורר בחי' מ\"ה וזה א\"א כ\"א ע\"י בחי' ביטול של הלומד למטה כנ\"ל ע\"כ בקריא' של אדם תליא מלתא ואז יש ג\"כ התחדשו' עוד שהקדב\"ה יושב ושונה כו' והיינו מה שמתהפך מבי\"ע לאצי' עי\"ז כנ\"ל שהוא ביאור מ\"ש והאלקים יעננו בקול שהוא שם ב\"ן הנק' אלקי' והוא בחי' מל' של כל עולם מכל פרטי הג' עולמו' דבי\"ע כו' וד\"ל.",[["3472","93","<b>וכמ\"ש במ\"א</b>: ראה תו\"א מקץ לח, ד. ועוד."],["3473","94","<b>ונחנו מה</b>: בשלח טז, ז."],["3474","95","<b>במקום גדולתו</b>: ראה מגילה לא, א. סה\"מ ה'ש\"ת ע' 40 בהערה. לקוטי הגהות לתניא פ\"ד."]]],[2100990098,"<h3>נוסח שני: משה ידבר</h3>\n<b>משה</b><sup data-n=\"3475\">1</sup> ידבר והאלקים יעננו בקול בקולו של משה<sup data-n=\"3476\">2</sup> ולהבין ההפרש בין אברהם<sup data-n=\"3477\">3</sup> שגם הוא קיים כל התורה כולה עד שלא נתנה כו' כמארז\"ל ע\"פ עקב<sup data-n=\"3478\">4</sup> אשר שמע אברהם בקולי וישמור משמרתי כו' לבין משה שנתן התורה הנה אב<sup data-n=\"3479\">5</sup> רם היא<sup data-n=\"3480\">6</sup> החכמה<sup data-n=\"3481\">7</sup> שנק' אב שהיא בחי' הראשית וביאור הדברי' הנה עבודת אברהם הי' להמשיך אורות בכלים דאצי' וכמארז\"ל בת<sup data-n=\"3482\">8</sup> הי' לאברהם ובכל שמה שהיא בחי' מל' שהמשיך לה אורות עליונים והיינו ג\"ח שלו אמנם לא המשיך רק באצי' אבל לא בבי\"ע אבל משה ממשיך אורות עליונים גם בבי\"ע ע\"י התורה שנק' תורת<sup data-n=\"3483\">9</sup> משה.\n<b>והטעם</b> יובן ע\"ד אמרם בס'<sup data-n=\"3484\">10</sup> הזהר אברהם אברהם פסיק טעמא בגווייהו משה משה לא פסיק טעמא כו' כי הנה ידוע דבין אצי'<sup data-n=\"3485\">11</sup> לבי\"ע יש פרסא ומסך המסתיר אור האצי' מבלתי יאיר כמו שהוא בבי\"ע שנק' דרך כללות עולם הנפרדים משא\"כ אצי' נק' אחדות ופי' אצי' יש בו ב' פירושי' ושניהם עולים בקנה א' מענין ויאצל<sup data-n=\"3486\">12</sup> מן הרוח כו' שהוא ענין הפרשה שנפרש הארה ממרע\"ה להע'<sup data-n=\"3487\">13</sup> זקנים והב' מענין אצלו שהוא פי' סמוך לו<sup data-n=\"3488\">14</sup> והענין שיש הפרש בין ענין פרישה לענין הבדל וחילוק מהחילוק<sup data-n=\"3489\">15</sup> שמחלקים וחותכים הדבר הזה נבדל ממהותו לגמרי מן הדבר שנחתך משם ואין לו שום צד חבור אלי' וה\"ז דוגמת הזורק אבן בידו שכח היד המוליך את האבן גם שנלקח מהכח שביד עכ\"ז נתפרד ממנו ונתלבש על האבן להוליכו ואין לו חבור וקשור לעצם כח היד אבל ענין הפרשה הוא הכח שמתגלה ממקורו בלתי מובדל ממנו לגמרי אלא שמתגלה בבחי' גילוי מבלתי יתעלם וה\"ז כמו הכותב בידו על הניר או מצייר איזה צורה שהכח היורד מהיד לכתוב ולצייר מקושר הוא עם עצמיות כח היד שהרי היד יכול להוליך ולעשות הצורה והכתב כמו שירצה ואלו הי' הכח שמוציא<sup data-n=\"3490\">16</sup> מופרד ממנה לא הי' מתנהג ע\"י וכמו שאין להיד",[["3475","1","<b>משה ידבר</b>: נעתק מכת\"י 80 עג, ב. נמצא ג\"כ בכת\"י 392 מ, א. 1213 סה, ב.\nנדפס ג\"כ במאמרי אדה\"ז על פרשיות התורה ח\"א ע' שיא. וראה ג\"כ לעיל ע' תע."],["3476","2","<b>משה ידבר. . . בקולו של משה</b>: יתרו יט, יט. ברכות מה, א."],["3477","3","<b>אברהם. . . קיים כל התורה כולה</b>: ראה יומא כח, ב. וראה ב\"ר פצ\"ה, ג. פמ\"ט ב. ובכ\"מ."],["3478","4","<b>עקב אשר שמע אברהם בקולי</b>: תולדות כו, ה."],["3479","5","<b>אב רם</b>: ראה זח\"א עט, ב."],["3480","6","<b>אב רם היא</b>: בכת\"י ב': אברהם הוא אב רם והיא."],["3481","7","<b>החכמה שנק' אב</b>: ראה זח\"ב צ, א. זח\"ג רצ, א. ביאוה\"ז לכ\"ק אדמו\"ר הצ\"צ ע' תשיג. וראה סידור עם דא\"ח קמו, ג."],["3482","8","<b>בת הי'. . ובכל שמה</b>: ב\"ב טז, ב. תו\"א יתרו סח, ד."],["3483","9","<b>תורת משה</b>: מלאכי ג, כב. מכילתא בשלח טו, א."],["3484","10","<b>בס' הזהר אברהם אברהם פסיק טעמא</b>: אד\"ר נשא קלח, א. בלק קפז, ב."],["3485","11","<b>אצי' לבי\"ע יש פרסא</b>: ראה ע\"ח שער (מז) סדר אבי\"ע פ\"א. עמק המלך שער עולם הבריאה רפ\"א. פ\"ג. פ\"ו."],["3486","12","<b>ויאצל מן הרוח</b>: בהעלותך יא, כה. ראה תו\"א בראשית ג, א. וירא יד, א. סה\"מ תקס\"ז ע' כג. לב. תקס\"ט ע' ריט."],["3487","13","<b>להע'</b>: בכת\"י ב: להעיר לע'."],["3488","14","<b>אצלו. . . סמוך לו</b>: ראה סה\"מ תקס\"ה ע' שיג. תקס\"ז ע' טו."],["3489","15","<b>מהחילוק</b>: בכת\"י ב: שהחילוק הוא."],["3490","16","<b>שמוציא</b>: בכת\"י ב: המצייר."]]],[2100990099,"שום בחירה אחר שזרקה האבן שיוגבה למעלה או ירד למטה שלא יוכל לשאת<sup data-n=\"3491\">17</sup> אח\"כ מכמו שנזרק ממנו פ\"א והיינו לפי שהכח של האבן נפרד ממנו ואינו כמו במשל הכתיבה הנ\"ל לכך<sup data-n=\"3492\">18</sup> אצי' נק' גילוי ההעלם דעצמיות א\"ס ואינו<sup data-n=\"3493\">19</sup> הגילוי זה מקושר ומחובר לעצמיותו אלא שהוא מה שהעצמות מתגלה מפני כך נק' אצי' א\"ס<sup data-n=\"3494\">20</sup> היותו סמוך לו משא\"כ בי\"ע הם מופרדים ממש ואין להם קישור וחיבור כלל וזהו בחי' מל' שבמל' כי מל' הוא בחי' התגלות כי האותיות מגלים את השכל ומל' שבמל' הוא התגלות דהתגלות דהיינו כח שיצא בדרך פרוד כנ\"ל וע\"כ עיקר הסיבה שבי\"ע הם נפרדים ממש הוא לפי שהשפע מגיע עליהם<sup data-n=\"3495\">21</sup> מבחי' מל' שבמל' דוקא כידוע.\n<b>והנה</b> בזהר<sup data-n=\"3496\">22</sup> המשיל ע\"ס דאצי' לעשר ספירות<sup data-n=\"3497\">23</sup> הנמשכין מן הנהר וכמ\"ש מעין דא יו\"ד עביד חפירא רברבא וקרא גרמי' בה מבין כו' שהוא הפרש בין ע\"ס דאצי' לע\"ס דבי\"ע שע\"ס דאצי' נמשלו לחפירות הנמשכין מן הנהר שמי הנהר נמשכין ויורדים בתמידות לתוכן שיש להם חבור וקשר עמה כו' וכמ\"ש דעביד חפירא רברבא מן אותו המעיין כו' אבל ע\"ס דבריאה י\"ל<sup data-n=\"3498\">24</sup> נמשלו לחפירה מבריכה<sup data-n=\"3499\">25</sup> שאין לה חבור עם הנהר עתה רק פעם א' הוא שנמשך מן הנהר ועשו בריכה ואח\"כ נסתמו בלי יגיעו וירדו תוך אותה הבריכה והיינו מטעם הנ\"ל לפי שיש פרסה ומסך בין אצי' לבי\"ע שנתעלם אור האצי' ואינו יורד בבי\"ע רק בדרך הגשמה גדולה שלא הי' כן תחילה והוא מאור התולדה בלבד ולא אור העצמות וע\"כ נק' יש מאין כידוע וכו' שמקבלין מן בחי' מל' שבמל' בלבד אבל האצי' גם שאינו רק הארה מעצמיותו יהי' איך שיהי' עכ\"פ הארה זו מקושרת במקורה בתמידית כנ\"ל.\n<b>וזהו</b> הטעם שאמרו בע\"ח בכוונת בא\"י כו' שהוא להוסיף אורות שבאצי' והיינו כי עיקר הוספות האור בתוספות ברכה שלא הי' כן בתחילה כידוע דיש שינוי בין שבת למו\"ש<sup data-n=\"3500\">26</sup> כו' אינן אלא באצי' שהוא מקושר ומחובר עם העצמיות שייך לומר שם שמקבל שפע בתמידי' שהרי נמשל לחפירה שאינה מופסקת מן הנהר כנ\"ל ע\"כ יתכן שם ענין הוספה ומיעוט כו' אבל בבי\"ע מאחר שנפרדו לגמרי וכדוגמת החפירה שנפסקת מן הנהר שלא יתכן שיגיע אלי' שפע מן הנהר אחר שיש הפסק ביניהם א\"כ היתכן<sup data-n=\"3501\">27</sup> לומר בהם ענין הוספה ומיעוט כי כבר נפרדו ואין בהם רק כמו שנחצבו תחילה בלתי גרעון והוספה כו' וד\"ל<sup data-n=\"3502\">28</sup>.",[["3491","17","<b>לשאת</b>: בכת\"י ב: לשנות"],["3492","18","<b>לכך</b>: בכת\"י ב': וכך"],["3493","19","<b>ואינו</b>: בכת\"י ב: ואמנם."],["3494","20","<b>א\"ס</b>: בכת\"י ב: ע\"ש."],["3495","21","<b>עליהם</b>: בכת\"י ב': אליהם"],["3496","22","<b>בזהר</b>: ראה זהר בא מב, ב."],["3497","23","<b>ספירות</b>: בכת\"י ב' חפירות"],["3498","24","<b>י\"ל</b>: בכת\"י ב': יצירה עשי'."],["3499","25","<b>מבריכה</b>: בכת\"י ב': ובריכה."],["3500","26","<b>למו\"ש</b>: בכת\"י ב': ליו\"ט."],["3501","27","<b>היתכן</b>: בכת\"י ב': לא יתכן."],["3502","28","<b>וד\"ל</b>: בכת\"י ב' נוסף: והנה גידול זה והוספת אורות באצי' עשה זה אברהם."]]],[2100990100,"<h3>מאמר הזוהר נשא בחללא דגולגלתא</h3>\n<b>[זוהר נשא]</b>\n<b>בחללא</b><sup data-n=\"3503\">1</sup> דגולגלתא<sup data-n=\"3504\">2</sup> קרומא דאווירא דח\"ס כו' פי' גולגלתא כתר דאריך וח\"ס חכמה שבכתר ויש חלל וקרום המפסיק בניהם. וביאור ענין ההפרש שבין חכמה הגלוי' לח\"ס הוא דחכמה הגלוי' בז\"א מתחלקת לל\"ב נתיבו' שהוא עד\"מ הנתיב לילך בו ובו מתפשטי' החכמה במדות שיהי' חסד או גבורה שבא מסיבת ההתבוננת בשכל ולפי ערך גילוי השכל כך יהי' ערך המדה כו', וכמו בגשמיות החכמה שביד לעשות מלאכה ושברגל לילך בו משא\"כ ח\"ס שבכתר הוא חכמה נעלמת והיינו ע\"ד דוגמא מ\"ש גבי ר\"ע<sup data-n=\"3505\">3</sup> שסרקו את בשרו במסריקות של ברזל ושאלו המלאכים זו תורה כו' שעפ\"י החכמה<sup data-n=\"3506\">4</sup> הגלוי' שבתורה אין ראוי' להיות שר\"ע שלמד תורה הרבה ונקנס במיתה רעה כזו, אך השיב להם שתוק כך עלה במחשבה כאדם האומר לזולתו השואלו על איזה דבר שעושה נגד דעתו מה איכפת לך אני רוצה כן וכמו המלך שמצוה לעבדיו לעשות כך וכך בלי טעם כו' שבוודאי יש לו טעם בפ\"ע על אותו הדבר אלא שא\"א לו לפרשו לזולתו ונק' טעם<sup data-n=\"3507\">5</sup> הכמוס שנעלם ברצון והיינו מ\"ש אין טעם לרצון כו' ולמטה מטה יש בחי' כזו עקשנות קשה עורף היפך הדעת לגמרי שגם בפ\"ע אין לו טעם כו' והוא בחי' קליפה כו'. והנה הטעם הכמוס נק' ח\"ס שהוא בחי' התעלומות שנעלם הטעם ברצון שהוא מה משיב אעפי\"כ אני רוצה שהוא עד\"מ למעלה הקרום החופה על המוח כו'.\n<b>והנה</b> לפי שח\"ס הוא בחי' העלמה של הטעם ע\"כ ממילא יובן שא\"א להיות ממנה בחי' התחלקות כלל כ\"א מחכמה הגלוי' יש התחלקות כו' אמנם חו\"ב דאריך הם שרשים לכל עולם האצי' ומהם הוא בחי' השתלשלות כי או\"א<sup data-n=\"3508\">6</sup> מלבישים לזרועות דא\"א שהן חו\"ג שבו דאבא בחסד אחיד ותליא ואימא בגבו' אני<sup data-n=\"3509\">7</sup> בינה לי גבו' כו' ואו\"א דאצי' מלובשים באו\"א דבריאה ומהם ביצי' עד שבא בשכל להשגת המלאכים ואח\"כ בשכל גשמי וכו', וכ\"ז הוא לפי שחג\"ת דאריך הם שורש הנאצלים כנודע שהכתר<sup data-n=\"3510\">8</sup> ממוצע בין המאציל לנאצלי' חציו בחי' התחתונה שבמאצי' והוא",[["3503","1","<b>בחללא דגלגלתא</b>: הנחת מהרי\"ל. נעתק מכת\"י 80 (עא, א). נמצא ג\"כ בכת\"י 284 (פז, א). 392 לז, א. 866 ט, ב. 2223 יח, א.\nהנחת כ\"ק אדה\"א ממאמר זה נדפס בביאוה\"ז פח, א (מגוכתי\"ק מס' 1025), בכותרת: ליל שבת פ' (והשאיר מקום חלל).\nהגהות מכ\"ק אדמו\"ר הצ\"צ על מאמר זה (על הנחת כ\"ק אדה\"א) נדפס בביאוה\"ז לכ\"ק אדמו\"ר הצ\"צ ח\"ב ע' תתקעא."],["3504","2","<b>בחללא דגלגלתא</b>: אדרא רבא פ' נשא קכח, ב."],["3505","3","<b>ר\"ע שסרקו. . שתוק כך עלה במחשבה</b>: מנחות כט, ב. וראה ביאוה\"ז בשלח מז, א. תו\"ח וירא קב, א. מאמרי אדה\"א ויקרא כרך ב' ע' תתטז."],["3506","4","<b>החכמה</b>: בכת\"י ב: השכל החכמה."],["3507","5","<b>טעם הכמוס</b>: ראה סידור דרושים לחתונה קל, סע\"ג. ערב שבת קסא, סע\"ב. סה\"מ תקס\"ה ח\"א ע' תסא. סה\"מ תקס\"ג ח\"א ע' קעד."],["3508","6","<b>או\"א מלבישים לזרועות דא\"א</b>: ראה פע\"ח שער (כא) חג המצות פ\"ז. שער הולדת או\"א פ\"ו שער (כט) הנסירה פ\"ו. משנת חסידים סדר ליל פסח פ\"ז מ\"ב. וראה ע\"ח שער (יד) או\"א פ\"א."],["3509","7","<b>אני בינה לי גבו'</b>: משלי יח, יד. שעה\"י קכז, ב. תו\"ח בא [הוצאת קה\"ת — תשס\"ג] פט, ב."],["3510","8","<b>שהכתר ממוצע</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב פ\"א."]]],[2100990101,"בחי' עתיק יומין המתנשא מימות עולם דז\"א ונק' ימי קדם דא\"א כו' והיא ג\"כ בחי' ח\"ס<sup data-n=\"3511\">9</sup> דא\"א שהיא מובדלת מן הנאצלי' בלתי תתלבש בהם וחציו שורש לנאצלי' הוא בחי' חג\"ת דאריך שהם מלובשי' באו\"א כו' וז\"ש והאי ח\"ס שקיט ושכיך באתרי' כחמר טב דיתיב ושקיט על דורדי'. כי הנה החכמה היא המברר וח\"ס מברר באצי' והסיגי' שא\"א להיות מברר באצי' נק' דורדי' והוא מברר בבריאה שגם הוא אלקות אלא שאינו כלול ובטול כ\"כ.\n<b>וביאור</b> ענין דורדי' הנה יש העלם וגילוי ועד\"מ<sup data-n=\"3512\">10</sup> הטפה שנמשכת מן המוח האב כוללת רמ\"ח כחות אברי הוולד ואעפי\"כ הם נעלמי' ואח\"כ כששוהה בבטן האם ט' חדשים נעשה בנין וגידול האברי' בגילוי כו' כך אב ואם נק' חו\"ב שמולידות אהבה שנק' בן זכר חסדו כו' ויראה נק' בת ועיקר השפע הוא מבחי' החכמה כמו שבתחילת ההשכלה יש התפעלות אלא שהוא בהעלם וע\"י התבוננות שמרחיב ומתבונן בדעתו באותו השכלה מתגלה התפעלות לאהוב כו' וכמו למשל התפוח שכלול בכח הצומח בהעלם וכן למעלה יותר אמרו אין<sup data-n=\"3513\">11</sup> לך עשב שאין לו מזל כו' ואעפי\"כ שם ברוחני הרבה יותר וכך הנה ידוע דיש דצח\"מ הדומם אין לו גידול והצומח דומם הוא בעצם כמו העצים שהם דומם אלא שכח הצומח מתלבש בו ומגדלו כו' וכך באדם הגוף הוא דומם והשערות צומח והראש<sup data-n=\"3514\">12</sup> חי והדיבור הוא מדבר ובנפש האותיו'<sup data-n=\"3515\">13</sup> שבמחדו\"מ נק' דומם כי האותיו' אין בהם הגדלה כמו שהוא נמשך כך נשאר כו' והמדות נק' צומח שהרי יש מדה קטנה במיעוט התפעלות ואח\"כ מתרחבו' כו' והשכל נק' חי ע\"ש מ\"ש והחכמה<sup data-n=\"3516\">14</sup> תחי' והכתר שבנפש נק' מדבר כו' וכך למעלה באצי' המל' נק' דומם שהם אותיות דבר ה' והמדות שהוא ז\"א נק' צומח ואו\"א הם נק' חי' וכתר שהוא חג\"ת דאריך המלובשים באו\"א נק' מדבר כו' וכשם שבבחי' האצי' הנגלה יש ד' בחי' הללו כך בהעלם הם ג\"כ בבחי' עתיק<sup data-n=\"3517\">15</sup> הנעלם שהיא מבחי' תחתונה שבמאציל כנ\"ל וכמו שנמצא כחות הרמ\"ח אברי' בהטפה וכן כח התפוח בכח הצומח כו' אלא שבי\"ע הוא רוחני יותר וביאור ענינם שם יובן שהרי פעם<sup data-n=\"3518\">16</sup> איתא בע\"ח דאו\"א יונקים ממזלות דא\"א מזל נוצר<sup data-n=\"3519\">17</sup> ומזל ונקה ופעם איתא שמלבשי' לזרועות דאריך, והענין שמה שמלבשי' לזרועו' דא\"א הוא מבחי' פרצוף אריך שהוא שורש הנאצלי' והוא בחי' הגילוי ומה שמקבלי' משערות ומזלות הוא מפרצוף עתיק שהוא ג\"כ בחי' חסד כו' והנה בכל הבחי' יש ע\"ס וכמ\"כ בחכמה",[["3511","9","<b>ח\"ס דא\"א</b>: ראה ע\"ח (שער א\"א) שי\"ג."],["3512","10","<b>ועד\"מ הטפה שנמשכת מן המוח האב</b>: ראה תניא פ\"ב."],["3513","11","<b>אין לך עשב שאין לו מזל</b>: באוה\"ת וארא ע' ב'תתפג מציין: הובא בר\"ח פ\"ה משער האהבה והוא במ\"ר בראשית פ\"י[ו]. וראה מאמרי אדה\"א דברים ח\"ג ע' תתמח, וש\"נ."],["3514","12","<b>והראש</b>: בכת\"י ב': והדם."],["3515","13","<b>האותיו'. . נק' דומם</b>: ראה ס\"י פ\"ד, מי\"ב. וראה תו\"א ויצא כב, ג. לקו\"ת במדבר ח, ב. שה\"ש לא, ג. ובכ\"מ."],["3516","14","<b>והחכמה תחי'</b>: קהלת ז, יב."],["3517","15","<b>עתיק. . שבי\"ע</b>: תיבות אלו ניתוספו מכת\"י ב'."],["3518","16","<b>פעם איתא בע\"ח</b>: ראה גם תו\"ח [הוצאת קה\"ת — תשס\"ג] קלא, א."],["3519","17","<b>דאו\"א יונקים ממזלות דא\"א. . נוצר</b>: תשא לד, ז. ראה מאמרי אדה\"א שמות ח\"א ע' קעב."]]],[2100990102,"סתימאה חכמה שבח\"ס שבכתר חי ומדות שבח\"ס שבכתר נק' צומח ומשם מקבלים או\"א שהיא מבחי' השערות שהם צומח וכמו השערה הגשמי היא הארה בלבד מעצם המוחין ונק' מותרי מוחין כך שערות דח\"ס היא מבחי' הצומח דח\"ס בלבד והיא בחי' דורדי' כי הנה בח\"ס יש מ\"ה וב\"ן והיא מברר דאו\"י ומברר דאור חוזר שבחי' מברר דאו\"ח וימת וימלוך היא למטה במדריגה ונק' צומח כו' וזה חמר טב של מ\"ה דח\"ס דשקיט ושכיך על דורדי' של ב\"ן דח\"ס ושם הוא ענין י\"ג מדות הרחמי' שהרחמי'<sup data-n=\"3520\">18</sup> דלמטה היא מדתו של יעקב אמת המבריח<sup data-n=\"3521\">19</sup> כו' אבל רחמי' הם בח\"ס כו' והיינו<sup data-n=\"3522\">20</sup> דאמרי אינשי סבא דעתוי סתים פי' עד\"מ הנער מתפעל תיכף בקל אם עושין נגד רצונו אבל הישיש יש בו ישוב הדעת שהיא בחי' הסבלנות שגם אם עושין נגד רצונו לא יקצוף כו' וכך החכמה הגלוי' יש שם בחי' גבול על ההיפוך העוברי' רצונו אבל בח\"ס אין תופס מקום כלל ואינו מתקצף כלל גם על ההיפוך גוים מרקדי' בהיכלו כו' והיינו דעתוי סתים כלומ' בחי' ישוב הדעת ומעוט ההתפעלות כו' וד\"ל.",[["3520","18","<b>שהרחמי'. . מדתו של יעקב</b>: ראה תניא פמ\"ה. תו\"א ויצא כד, א. מג\"א צה, א. ובכ\"מ."],["3521","19","<b>המבריח</b>: ראה זהר תרומה כו, כח. ויקהל לו, לג. בלק קפו, ב. ובהגהות הרח\"ו שם."],["3522","20","<b>והיינו דאמרי אינשי סבא דעתוי סתים</b>: ראה זהר שם (נשא) קכח, ב. וראה לקו\"ת צו יא, א. שה\"ש ל, ב."]]],[2100990103,"<h3>כה תברכו את בנ\"י</h3>\n<b>בעזר\"ה שבת פ' נשא</b>\n<b>כה</b><sup data-n=\"3523\">1</sup> תברכו את בני ישראל אמור להם יברכך ה' כו' יאר ה' כו' ישא<sup data-n=\"3524\">2</sup> ה' כו' ושמו את שמי על בנ\"י ואני אברכם. הנה ארז\"ל אמרו<sup data-n=\"3525\">3</sup> מלאכי השרת לפני הקדב\"ה כתיב אשר<sup data-n=\"3526\">4</sup> לא ישא פנים כו' ואיך אתה נושא פנים לישראל דכתיב ישא ה' פניו אליך, אמר להם הקדב\"ה והאיך לא אשא פנים לישראל אני אמרתי ואכלת<sup data-n=\"3527\">5</sup> ושבעת וברכת כו' והם מחמירים ע\"ע ומדקדקין עד כזית כו'. והמאמר הזה פלאי הוא לכאורה דהאיך יתכן דמשום שמדקדקין לברך בהמ\"ז בפחות מכשיעור יהיו ראויי' לנשיאת פנים למעלה בעבור דקדוק קל כזה כו' וגם מה ענין נשיאת פנים למעלה לענין דקדוק זה שמדקדקי' לברך עד כזית כו'.",[["3523","1","<b>כה תברכו</b>: הנחת כ\"ק אדמו\"ר האמצעי נעתק מגוכתי\"ק 1025 (נט, א). מאמר כ\"ק אדמו\"ר האמצעי שנדפס במאמרי אדה\"א נשא ע' רכב מיוסד על מאמר זה.\nהנחה אחרת בלקו\"ת נשא כו, א.\nמאמר זה נאמר ע\"י כ\"ק אדה\"א — נדפס במאמרי אדמו\"ר האמצעי הנחות תקע\"ז ע' קכח."],["3524","2","<b>כה תברכו. . יברכך. . יאר. . ישא</b>: נשא ו, כג-כו."],["3525","3","<b>אמרו מלאכי השרת. . עד כזית</b>: ראה ברכות כ, ב. במדבר רבא פי\"א, ז."],["3526","4","<b>אשר לא ישא פנים</b>: עקב י, יז."],["3527","5","<b>ואכלת ושבעת וברכת</b>: עקב ח, י."]]],[2100990104,"<b>אך</b> הנה תחלה יש להבין המשך הברכות הללו יברכך ואח\"כ יאר כו' דלכאורה אין להם סדר. אבל הענין שלהם יובן בהקדים תחלה להבין שרש ענין ברכת המזון מהו דהנה כתיב ואכלת ושבעת וברכת את ה' אלקיך כו', ופי' א\"ת ידוע שהם האותיו' שמאל\"ף עד תי\"ו דידוע שכל הנבראים כולם נבראו בבחי' יש מאין ע\"י צרופי אותיות שנמשכו מעשרה מאמרות הכלליים בחלופי' ותמורות כו' כמ\"ש<sup data-n=\"3528\">6</sup> בס\"י ואין כל נברא בפרט שאין לו צירוף אותיו' מיוחד לבחי' התהוותו מאין ליש וכמארז\"ל בבצלאל<sup data-n=\"3529\">7</sup> שהי' יודע לצרף אותיו' שנבראו בהן שמים וארץ כו' אך הי' מאמרו' שנברא בהם כל העולמו' הם באו דרך כללות ושאר הנבראי' נמשכו מצרופי' שלהם שבאו בחלופי' ותמורות דהיינו בחי' הארה דהארה וכמ\"ש<sup data-n=\"3530\">8</sup> בלק\"א וד\"ל.\n<b>והנה</b> גם נפש האדם נבראת בצרופי אותיו' וכמ\"ש בס\"י דהנפש<sup data-n=\"3531\">9</sup> מלאה אותיו' להיות כי נמשכה מרוח פיו ית' וכמ\"ש ויפח<sup data-n=\"3532\">10</sup> באפיו נשמת חיים וידוע שרוח פיו ית' בא בהתהוות העולמות בבחי' אותיות בעשרה מאמרו' בכלל ובריבוי הצרופי' בפרט כנ\"ל ואמנם בזאת יתרון מעלת האדם על כל הנבראי' כולם במה שהוא בחי' הכולל כל הצרופי' שיש בכל הנבראי' עד אשר בו תלוי קריאת שם לכל נברא בפרט כי הוא יודע מכל צירוף השייך לאותו נברא וכמ\"ש ויקרא<sup data-n=\"3533\">11</sup> האדם שמות לכל הבהמה ולעוף השמים כו' ולכל אשר יקרא האדם<sup data-n=\"3534\">12</sup> שם זהו שמו כו' מפני שהוא הממשיך בחי' צרופי אותיו' לכל הנבראי' &lt;רכט&gt;\nלהיותו כולל כולם והוא ראש לכולם כי בחי' המדבר גבוה מדצ\"ח וכוללם יחד וד\"ל וזהו כי<sup data-n=\"3535\">13</sup> לא על הלחם לבדו יחי' האדם כי על כל מוצא פי ה' יחי' האדם, כי הנה בכל מאכל<sup data-n=\"3536\">14</sup> ומזון בפרט יש צרופי אותיו' עליונים המהווי' חיות אותו המאכל ונק' מוצא פי ה' שבמאכל מפני שנמשכו מעשרה מאמרו' שנק' מוצא פי ה' כו' וכנ\"ל והנה כשהאדם אוכל המאכל מעלה הוא אותן הצרופי אותיו' שבחיות המאכל להיותם נכללי' בנפש האדם כשאוכלם ומחי' את האדם ובהתכללות זאת מביאם האדם אל שרש ומקור חוצב כל הי' מאמרו' והוא",[["3528","6","<b>כמ\"ש בס\"י</b>: ראה ס\"י פ\"ב, מ\"ד-ה. שער היחוד והאמונה פ\"א."],["3529","7","<b>בבצלאל שהי' יודע. . שמים וארץ</b>: ראה ברכות נה, א."],["3530","8","<b>וכמ\"ש בלק\"א</b>: ראה שער היחוד והאמונה פי\"ב."],["3531","9","<b>דהנפש מלאה אותיו'</b>: ראה ס\"י פ\"ב מ\"א ואילך בענין כ\"ב אותיות [בעולם שנה נפש]. ובכמה נוסחאות שם (מ\"ב-ג): ”כ\"ב אותיות. . וצר בהם נפש. . וקבען בפה\". ובס' מאמרי אדה\"ז עה\"ת (ח\"ב) ע' תשל וז\"ל: וכדאיתא בס\"י כ\"ב אותיות קבען בפה שקביעותן הוא בפה אבל עצמותן הוא ממקור הנפש (ועד\"ז הוא שם ע' תרלט. וראה ס' המאמרים הקצרים ע' שג)."],["3532","10","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."],["3533","11","<b>ויקרא האדם שמות</b>: בראשית ב, כ."],["3534","12","<b>האדם. . הממשיך. . לכל הנבראי'</b>: ראה מאמרי אדמו\"ר האמצעי — הנחות תקע\"ז ע' לה ובהנסמן שם."],["3535","13","<b>כי לא על הלחם לבדו יחי' האדם</b>: עקב ח, ג."],["3536","14","<b>מאכל. . ונק' מוצא פי ה' שבמאכל</b>: ראה סה\"מ תקס\"ג ס\"ע תשכה — בס' לק\"ת. וכן הוא בתו\"ח שמות [הוצאת קה\"ת — תשס\"ג] נה, ב. המבואר בלק\"ת להאריז\"ל. וראה לקו\"ת וספר הליקוטים [להאריז\"ל] עקב ח, ג. כש\"ט (קה\"ת) סקצ\"ד. תו\"א בשלח סה, א. יתרו עד, א. סה\"מ תקס\"ה ח\"ב ע' תרלח. לקו\"ת צו יג, ב. במדבר יא, ג. נשא כו, ב. סידור קז, ב-ג. ובכ\"מ."]]],[2100990105,"הנק' מאמר אחד כמאמר רז\"ל דבמאמר<sup data-n=\"3537\">15</sup> אחד יכול להבראות כו' והיינו מאמר דנעשה אדם הכולל כל המאמרות כי האדם ממנו לוקחו כל פרטי הצרופי' וכמ\"ש ויקרא האדם שמות כו' וכנ\"ל וה\"ז מביאם ומעלם מן בחי' הפירוד אל בחי' היחוד וד\"ל.\n<b>וזהו</b> כי על כל מוצא פי ה' כאשר יביא לכל מוצא פי ה' הוא כללו' המאמרות כולם שבזה דוקא יחי' האדם ולא על הלחם לבדו כי הנה אותיות לחם<sup data-n=\"3538\">16</sup> אם נקודות שלהם בסגו\"ל הוא ענין הלחם שאוכלים ואם נקודו' שלו בחולם הוא ענין לוחם מלחמה וכמ\"ש בזוהר נהמא<sup data-n=\"3539\">17</sup> אפום חרבא ייכול דבשעת אכילה הוא כדמיון מלחמה אם בחי' הרע שבמאכל גובר יפיל לנפש האדם בגסו' ואם בחי' הטוב שבו יתגבר ע\"י הכונה יתעלה להיו' לחיזוק עוז לנפש לעלות במדרגה באוי\"ר בשעה שיתפלל בכח האכילה ההיא והיינו שהאכילה בדמיון לתפלה שגם בתפלה אמרו דשעת<sup data-n=\"3540\">18</sup> צלותא שעת קרבא כו' משום דכתיב רוממו'<sup data-n=\"3541\">19</sup> אל בגרונם ואז נעשה מזה חרב פיפיו' לחיצונים כו', כי הנה הכח הזה שמתפלל בו הוא מוסר בכונה לה' אחד באמרו לאהבה<sup data-n=\"3542\">20</sup> את ה' אלקיך פי' לאהבה<sup data-n=\"3543\">21</sup> הוא לשון רצון כמו אבה כידוע והיינו בחי' המלחמה שבשעת התפלה למסור כל כחות הגוף ורצונות הזרות שלא יהי' לו רצון זר בלתי לה' לבדו כו' אך הנה עיקר האהבה והרצון הוא שיהי' בחי' גילוי אלקו' למטה כמו שהוא למעלה ולא יסתיר שום בחי' צמצום כלל כו' וזהו לאהבה את ה' אלקיך פי' שיהי' הוי' סובב כ\"ע בבחי' גילוי שהוא הנק' אלקיך כו' וזהו כל עיקר המכוון בהשתלשלו' שיומשך מבחי' ההעלם לגילוי שכמו שהוא למעלה אין<sup data-n=\"3544\">22</sup> עוד מלבדו שהרי אני<sup data-n=\"3545\">23</sup> ה' לא שניתי כתיב דכולא קמי' כלא כו' כי כמו קודם בריאת העולמו' כך גם לאחר הבריאה אין העולם תופס מקום וכולא<sup data-n=\"3546\">24</sup> קמי' כלא חשיבא כו' ואת זה כל האדם לכוין בשעת התפלה ובפרט באמרו ברוך את\"ה כלומר שיהי' נמשך אל הגילוי להיות נק' את\"ה לנוכח כו' וכך יהי' גילוי זה גם בנפשו האלקי' עד שיהי' נק' אלקיך בפרט וד\"ל.\n<b>וזהו</b> וברכת את ה' אלקיך פי' שימשיך מן העלם לגילוי ויהי' את הטפל לה' אלקיך כלומר שיתעלו גם כל צרופי אותיו' שבמאכלי' שאכל ויהיו גם הם נכללים",[["3537","15","<b>דבמאמר אחד יכול להבראות</b>: אבות רפ\"ה."],["3538","16","<b>לחם. . מלחמה</b>: ראה לקו\"ת נשא כו, ב. סה\"מ תקס\"ב ע' קז. תקס\"ד ע' נא. סידור שער נט\"י לסעודה קמ, סע\"א. מאמרי אדה\"א במדבר ח\"א ע' רכז. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' נג. ח\"ב ע' תרפח. ראה גם מאמרי אדה\"א שמות ח\"א ע' קפ. וש\"נ."],["3539","17","<b>נהמא אפום חרבא ייכול</b>: זהר ח\"ג קפח, ב."],["3540","18","<b>דשעת צלותא שעת קרבא</b>: מובא בכ\"מ. וראה זח\"ג רמג, א. זח\"א רמ, ב. ת\"ז תי\"ג (כט, ב). וראה ס' מאמרי אדה\"א ויקרא ח\"א ע' תכח."],["3541","19","<b>רוממות אל בגרונם</b>: תהלים קמט, ו."],["3542","20","<b>לאהבה את ה' אלקיך</b>: פ' שופטים יט, ט. נצבים ל, ו."],["3543","21","<b>לאהבה הוא לשון רצון</b>: ראה גם תו\"א לב, ג. לקו\"ת בלק כא, ב. מסעי פח, ד. ואתחנן ט, ב. שה\"ש יז, א."],["3544","22","<b>אין עוד מלבדו</b>: ואתחנן ד, לה."],["3545","23","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["3546","24","<b>וכולא קמי' כלא</b>: נסמן לעיל ע' תעד."]]],[2100990106,"ועולים עם נפשו האלקי' להיות ה' אלקיך בבחי' גילוי כו' והיינו ואספת<sup data-n=\"3547\">25</sup> דגנך שאחר לאהבה את ה' אלקיך פי' דגנך ללקט פיזורי החיות שבמאכלי' ממוצא פי ה' ולהביאם לשרשם כנ\"ל ע\"י האהבה במס\"נ שבתחלה כנ\"ל ודגנך כתיב וכן ותירושך המיוחד לחיות וניצוצי קדושה שאכל האדם וכללם בנפשו וקרא להם שמות והם שלו נחשבי' לפי שהאדם הוא שרש לכולם וכנ\"ל וכמ\"ש פני<sup data-n=\"3548\">26</sup> ארי' להימין ופני &lt;רל&gt;\nהשור מהשמאל ופניהם פני אדם לפי שכולל הכל כו' וד\"ל וזהו לא על הלחם לבדו יחי' האדם אלא על כל מוצא פי ה' בחי' כללות דוקא כשיכלל הלחם בנפשו ויתפלל בכונה שאז יוכל לקיים ואספת דגנך כנ\"ל ולכך קודם<sup data-n=\"3549\">27</sup> התפלה אסור לאכול כי עדיין הנשמה באפו של אדם ולא נכנסה בו עד שהתפלל בכונה והעלה גם כל כחו' הגשמיי' שבו שמן המאכלי' שאכל כנ\"ל ע\"י לאהבה כו' משא\"כ קודם התפלה עדיין גם הוא מקושר למטה ואיך יעלה מן חלקי הנפש הבהמיו' כו' וד\"ל.\n<b>וזהו</b> הטעם שהתפלה<sup data-n=\"3550\">28</sup> נק' סולם כמ\"ש בזוהר סולם דא הוא צלותא וכתיב בסולם<sup data-n=\"3551\">29</sup> שהוא מוצב ארצה וראשו מגיע השמיימה וכך הוא ענין התפלה דהנה התחלת סדר התפלה הוא מתחיל מברכות השחר שהמה ענינים גשמיי' ודברים תחתוני' כמו<sup data-n=\"3552\">30</sup> הנותן לשכוי בינה ופוקח עורים וכיוצא ואח\"כ הולך ועולה במדרגה יותר גבוה כמו בפסוקי דזמרה עד שמספרים איך שמלאכי' העליוני' או' שירה כמו ביוצר כו' עד שבק\"ש או' בענין אחדו' ה' ממש שהוא למעלה מכל ההשתלשלו' וזהו וראשו מגיע השמיימ' כו' וכמו הסולם שעולין בו במדרגו' כך בסדר התפלה יש מדרגו' זו למעלה מזו כו' וגם כמו בסולם אמר ומלאכי אלקי' עולי' ויורדי' בו ולפי שהמלאכי' הם מבחי' פני ארי' פני שור כו' ופני אדם הוא כולל כולם ע\"כ כולם עולי' ויורדי' בנפש האדם כשהוא עולה בסולם וזהו בשעת התפלה שהיא כדמיון הסולם כנ\"ל וד\"ל וכל זה מפני שע\"י האדם עולי' הכל והוא לפי שהוא כולל כל הצרופי' כנ\"ל וזהו ענין ברכת המזון בכלל באמרו ואכלת ושבעת וברכת את ה' אלקיך פי' א\"ת הם אותיו' שמאל\"ף עד תי\"ו כללו' הי' מאמרו' שנסתעפו מהם פרטי' רבים במאכלי' ומזונו' וכשמברך ואו' ברוך אתה כו' נתעלו כולם ע\"י האדם שכולל כולם כנ\"ל וע\"כ נא' בו וברכת את ה' שיהי' את הטפל כו' להיו' ה' אלקיך מן ההעלם דבחי' סובב לגילוי דבחי' ממלא כו' כנ\"ל וד\"ל.\n<b>וזהו</b> ענין הברכות יברכך ה' כו', פי' יברכך להיות בכנ\"י הברכה שהוא בא בבחי' תוספת מרובה על העיקר בכפלי כפליים כמו הזריעה שזורעין גרעין אחד כדי",[["3547","25","<b>ואספת דגנך</b>: עקב יא, יד."],["3548","26","<b>פני ארי' להימין</b>: ראה יחזקאל א, ה."],["3549","27","<b>קודם התפלה אסור לאכול</b>: ברכות י, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשנו. במדבר ח\"א ע' רכט. ח\"ג ע' תתקכג."],["3550","28","<b>שהתפלה נק' סולם כמ\"ש בזוהר סולם דא הוא צלותא</b>: ראה זהר ח\"א רסו, ב. זח\"ג שו, ב. ת\"ז תמ\"ה (פג, א)."],["3551","29","<b>בסולם שהוא מוצב ארצה. . ומלאכי אלקי' עולי' ויורדי' בו</b>: בראשית כח, יב."],["3552","30","<b>כמו הנותן לשכוי בינה ופוקח עורים</b>: ראה לקו\"ת נשא כאן — תחלה ברכת השחר פוקח עורים זוקף כפופים."]]],[2100990107,"שיצמח ממנו הרבה וכלום<sup data-n=\"3553\">31</sup> אדם זורע קב חטי' אלא להוציא ממנו כמה כורים כידוע כך כתיב וזרעתי<sup data-n=\"3554\">32</sup> את בית ישראל כו' וזרעתיה<sup data-n=\"3555\">33</sup> לי בארץ כו' לפי שכנ\"י במקור חצבם למעלה המה בחי' אלקו' כמ\"ש חלק<sup data-n=\"3556\">34</sup> הוי' עמו יעקב חבל נחלתו ונתלבשו בגופים חומריי' בעוה\"ז בדמיון זריעת החטה בארץ שהעפר מכסה עליה עד שהיא טמונה שמה כך ניצוץ האלקי כתיב בו אור<sup data-n=\"3557\">35</sup> זרוע לצדיק שנזרע בחומר הגופני ונטמן בו דהיינו בחי' התגשמות הנפש הבהמיו' המעלמת ומסתרת אור ניצוץ האלקי בתאוות גופניות לעניני' גשמיי' כמאכלי' גשמיי' וכיוצא שהנפש ניזונת ומקבלת חיות מהם כנ\"ל וכל זה עשה האלקי' את ההתלבשו' וזריעת אור ניצוץ האלקי בגוף כדי להצמיח אח\"כ ריבוי אורו' בניצוץ בעלותו לה' בתפלה כנ\"ל כי אחר שיעלה עמו כל מה שמדובק בו מחלקי חיות דצ\"ח הגשמיים של הנפש הבהמיו' הרי יעלה ויצמח בתוספת<sup data-n=\"3558\">36</sup> מרובה על עיקר הזריעה עד\"מ צמיחת התבואה מגרעין חטה &lt;רלא&gt;\nא' וכיוצא להיות כי שרש שרשם של דצ\"ח הגשמיי' נפלו ממקום גבוה משרש ניצוץ האלקי דהיינו מבחי' עולם התוהו שלפני התיקון וכמ\"ש ואלה<sup data-n=\"3559\">37</sup> המלכי' כו' לפני מלוך מלך לבנ\"י כו' וע\"כ זאת הברכה הבאה מברורי' דרפ\"ח ניצוצי' שנפלו מעולם התוהו עולין עם הניצוץ האלקי בבחי' תוספ' מרובה על העיקר כו' וזהו פי' יברכך ה' מלמטה למעלה ע\"י ברורי' דרפ\"ח כו' כענין אדם הזורע קב שמוציא כמה כורים וד\"ל וישמרך פי' מן המזיקין שלא יהי' יניקת החיצוני' מן התפעלו' אוי\"ר שבתפלה וכיוצא כגון שיגבה לבבו ויתנשא בעבודתו או שיפול מעבודתו בדברים שהם מנגדים אליה כי תשוקת החיצונים לקבל יניקה דוקא במקום שיש השראת קדושה כידוע וד\"ל.\n<b>יאר</b> ה' פניו אליך ויחונך, פי' אחר שאמר יברכך ה' שהוא מלמטה למעלה כנ\"ל מצד בחי' הברורי' שעולי' למעלה ע\"י אהבה כו' אח\"כ ע\"י אתעדל\"ת זו נעשה בחי' אתעדל\"ע כמים הפנים כו' שיאר ה' פניו מלמעלה למטה כי ידוע המאמר דרוח<sup data-n=\"3560\">38</sup> אייתי רוח ואמשיך רוח כו' וכמ\"ש אם<sup data-n=\"3561\">39</sup> ישים אליו לבו רוחו ונשמתו אליו יאסוף מלמעלה למטה כו', ואתעדל\"ת זו היתה ג\"כ שיהי' גילוי זה מן העלם דסובב לבחי' גילוי דממלא כמ\"ש למעלה בפי' לאהבה את ה' אלקיך כו' וכך נמשך אח\"כ אתעדל\"ע שיהי' הגילוי מן ההעלם והיינו מ\"ש יאר ה' פניו כו' דהנה כתיב חכמת<sup data-n=\"3562\">40</sup> אדם תאיר פניו פי' חכמ\"ה<sup data-n=\"3563\">41</sup> הוא בחי' כח מ\"ה כו' והוא גורם בחי' ראיה דהיינו לראות בעין השכל איך שאור א\"ס מהווה מאין ליש וכמארז\"ל איזהו<sup data-n=\"3564\">42</sup> חכם הרואה את הנולד פי' איזהו חכם בבחי' כח מ\"ה כו' הרואה בבחי' ראיי' השכל את הנולד יש",[["3553","31","<b>וכלום אדם זורע</b>: ראה פסחים פז, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' תלד."],["3554","32","<b>וזרעתי את בית ישראל</b>: ירמי' לא, כו."],["3555","33","<b>וזרעתיה לי בארץ</b>: הושע ב, כה."],["3556","34","<b>חלק הוי' עמו</b>: האזינו לב, ט."],["3557","35","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["3558","36","<b>בתוספת מרובה על עיקר</b>: ראה תו\"א פט, ב. תו\"ח בראשית ד, א. ובכ\"מ."],["3559","37","<b>ואלה המלכי'</b>: וישלח לו, לא."],["3560","38","<b>דרוח אייתי רוח</b>: ראה זח\"ב קסב, רע\"א. זח\"א צט רע\"ב. אוה\"ת חנוכה רפו, א."],["3561","39","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["3562","40","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["3563","41","<b>חכמה. . כח מה</b>: זח\"ג לד, א."],["3564","42","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א."]]],[2100990108,"מאין בכל רגע כו' ולא בבחי' שמיעה בלבד כמאמר אינו<sup data-n=\"3565\">43</sup> דומה שמיעה לראיה לפי שהשמיעה הוא רק בחי' ההשגה בהתבוננו' הנק' בינה שאינה אלא מרחוק לשער בהבנת השכל ולא שיראה הדבר כמו שהוא ממש וזהו מצות שמע<sup data-n=\"3566\">44</sup> ישראל ואין שמע<sup data-n=\"3567\">45</sup> אלא ענין הבנה כו' אבל בחי' ראי' מקרוב הוא והוא בבחי' חכמה דוקא וכמ\"ש וירא<sup data-n=\"3568\">46</sup> ראשית לו כו' וכמ\"ש במ\"א וגם בכאן ר\"ל חכמת אדם תאיר פניו שהחכמה מביאה לאדם לידי בחי' ראי' מקרוב לראות בעין השכל איך דכולא קמי' כלא חשיב ממש ואין בחי' היש תופס מקום כלל וידוע שאין זה אלא דוקא בבחי' כח מ\"ה שבנפש והיינו שתאיר פניו לראו' פנים בפנים כו' וזהו ג\"כ פי' יאר ה' פניו אליך דכשם<sup data-n=\"3569\">47</sup> שבא לראו' כו' כך יאר ה' פניו להיו' נגלה לו לאדם כמו שהוא למעלה דקמי' כו' ולא כמו שהוא מלובש בהלבשו' וצמצומי' והיינו שאמר פני\"ו בחי' הפנימי' דוקא וד\"ל.\n<b>וזהו</b> מצות ת\"ת שאחר ואהבת שבק\"ש באמרו ודברת<sup data-n=\"3570\">48</sup> בם כו' וכן בפ' שני' ונתתי<sup data-n=\"3571\">49</sup> מטר ארצכם שהוא ג\"כ מדבר בענין ת\"ת שנמשל לגשמים כמ\"ש כאשר<sup data-n=\"3572\">50</sup> ירד הגשם כו' כן יהי' דברי אשר יצא מפי כו' כמ\"ש ביאור זה במ\"א שקול דתורה נמשל לגשמי' כו' והוא הנק' הארת פנים דהוי' כי הנה ידוע דאוריי'<sup data-n=\"3573\">51</sup> מחכמה עילא' נפק' וחכמ' עילא' כתיב בה חכמת אדם תאיר פניו דהיינו חכמתו ית' שנק' חכמת אדם העליון שעל הכסא כו' והיא תאיר פני הוי' בבחי' הפנימי' כנ\"ל אלא שירדה התורה למטה ונתלבשה בעניני' גשמיים &lt;רלב&gt;\nבשיתא סדרי משנה זרעים מועד נשים כו' אבל למעלה הנה היא בחי' אור<sup data-n=\"3574\">52</sup> פני מלך חיים וההארה שמתפשטת ממנה למטה הוא בא כמים<sup data-n=\"3575\">53</sup> הפנים לפנים כו' ע\"י אתעדל\"ת הנ\"ל וה\"ז כמים<sup data-n=\"3576\">54</sup> שיורדי' מגבוה לנמוך כו' אך אין טפה יורדת כשאין טפיים עולי' כו' והוא בחי' העלא' מ\"ן מברורי' דרפ\"ח באהבה במס\"נ בתחלה כנ\"ל וד\"ל.\n<b>ויחונך</b> פי' ויחונך<sup data-n=\"3577\">55</sup> הוא לשון חן שע\"י הארת הפנים ממילא נמשך החן וכמ\"ש ונח<sup data-n=\"3578\">56</sup> מצא חן כו' וגם הוא לשון חנייה לפי שעי\"ז נעשה להקדב\"ה<sup data-n=\"3579\">57</sup> דירה בתחתונים וכמ\"ש ושכנתי<sup data-n=\"3580\">58</sup> בתוכך כו' והכל ענין א' דהחן בא מחמת החנייה",[["3565","43","<b>אינו דומה שמיעה לראיה</b>: ראה מכילתא יתרו יט, ט. לקח טוב שלח יג, יח."],["3566","44","<b>שמע ישראל</b>: דברים ו, ד."],["3567","45","<b>שמע. . הבנה</b>: ראה שמואל-א ג, י. זח\"ג קלח, ב."],["3568","46","<b>וירא ראשית לו</b>: ברכה לג, כא."],["3569","47","<b>דכשם שבא לראו'</b>: חגיגה ב, א."],["3570","48","<b>ודברת בם</b>: ואתחנן ו, ז."],["3571","49","<b>ונתתי מטר ארצכם</b>: עקב יא, יד."],["3572","50","<b>כאשר ירד הגשם</b>: ישעי' נה, יוד."],["3573","51","<b>דאורייתא מחכמה עילאה נפק'</b>: זח\"ב סב, א. פה, א. קכא, א. זח\"ג פא, א. קפב, א. רסא, א."],["3574","52","<b>אור פני מלך חיים</b>: משלי טז, טו."],["3575","53","<b>כמים הפנים לפנים</b>: משלי כז, יט."],["3576","54","<b>כמים שיורדי' מגבוה לנמוך</b>: תענית ז, א."],["3577","55","<b>ויחונך הוא לשון חן</b>: ראה ג\"כ לקו\"ת שם נשא כו, ד."],["3578","56","<b>ונח מצא חן</b>: בראשית ו, ח."],["3579","57","<b>להקב\"ה דירה בתחתונים</b>: תנחומא נשא טז. ובכ\"מ."],["3580","58","<b>ושכנתי בתוכך</b>: זכרי' ב, יד."]]],[2100990109,"והחנייה באה מצד החן כו' וד\"ל ועם כל זה יובן ענין ברכת המזון בכלל שהוא בחי' המשכו' גילוי אלקו' מלמעלה למטה באמרו ברוך אתה כו' וכנ\"ל והמשכה זו היא על חיו' המאכל שאכל ועלה עם הניצוץ כנ\"ל ואו' עליו ברוך אתה הזן כו' והם ד'<sup data-n=\"3581\">59</sup> פעמי' ברוך ג\"פ דאוריי' וא' מדרבנן והכל כדי להיו' גילוי ההמשכה על חיו' המאכל וכמ\"ש למעלה בפי' וברכת א\"ת כו' וד\"ל.\n<b>ישא</b> ה' פניו אליך וישם לך שלום. פי' משום דכל הנ\"ל היינו אם אוכל כדי שביעה דוקא שאז תשבע הנפש מחיות אותו המאכל שמחי' אותה כו' וכמ\"ש לחם<sup data-n=\"3582\">60</sup> לבב אנוש יסעד והמאכל הרי יש בו מתערובו' טו\"ר דעה\"ד כו' ונתקיים בנפש האלקי' מ\"ש עת<sup data-n=\"3583\">61</sup> אשר שלט האדם באדם כו' דהיינו אדם בליעל דקליפ' נוגה באדם דקדוש' שהוא נפש האלקי' כידוע וכנראה בחוש שהמאכל יגשם את הנפש האלקי' עד שיפול הנופל כו' ואמנם שליטה זו היא לרע לו כי ע\"י שמבררי' הרע דנוגה שבמאכל כמו בשעת התפלה שמתפלל בכח המאכל וכיוצא הרי נתהפך לטוב והרע נדחה חוץ ויאבד כו' וזהו ג\"כ ענין ברכת המזון על חיו' המאכל להעלותו למעלה ולהפכו לקדוש' כנ\"ל אבל אם אין במאכל כדי שביעה לנפש הרי לא שלט האדם באדם כ\"כ אחר שאין בו אלא חיות מועט הרי אין בו ג\"כ כדי שיעור ברכה שיברך וימשיך עליו להפכו לקדוש' ולכך נא' ואכלת ושבעת דוקא ואז וברכת את כו' וד\"ל אך הנה אמרו ז\"ל דאעפ\"כ בני ישראל מחמירי' ע\"ע ומדקדקי' לברך גם על פחות מכשיעור שביעה כמו בכזית או בכביצה ועל זה הוא נושא פנים להם וכמאמרם ז\"ל וכי לא אשא פנים לישראל כו'.\n<b>והענין</b> הוא כי ענין נשיאת פנים היינו כמ\"ש ישא ה' פניו כו' וענין ישא הוא ענין הגבהה והתנשאות שמגביה ומנשא לבחי' פנים העליונים למעלה מן ההשתלשלו' כו' ותחלה יש להבין מהו פי' פני\"ם דהנה הטעם שנק' בלה\"ק צורת השטח של הפנים בשם פנים<sup data-n=\"3584\">62</sup> הוא ע\"ש לשון פונה וכמו ופנה לדרכו כי כל פינות שהאדם פונה הוא בצד זה של ציור הפנים כי שם הוא עיקר החיות הפנימי כמו ראי' שמיעה ריח כו' ושכל שהוא מעיקר הנפש וע\"כ נק' פני\"ם וכמ\"ש פני\"ם<sup data-n=\"3585\">63</sup> בפני\"ם דבר ה' ואמנם הגבהת בחי' הפנים הללו היינו למעלה מעלה גם מבחי' פנים העליונים והיינו למעלה גם מבחי' פנימי' האור והשפע דפנים שהוא למעלה גם מכל עיקר ההשתלשלו' והענין הוא שבחי' חב\"ד נק' פנים ונשיא\"ת הפנים למעלה הוא בבחי' הכתר<sup data-n=\"3586\">64</sup> עליון הנק' גלגלתא כו' שהוא מקור כל המקיפי' &lt;רלג&gt;\nושם נא' המשפילי<sup data-n=\"3587\">65</sup> לראות בשמים וארץ ששמים וארץ דהיינו רוחניו' וגשמיו' שוין כו' ונשיא\"ת פני\"ם הללו לישראל הוא הגורם שיוכל להיו' גילוי אור אלקי בברכת המזון גם בפחו' מכדי",[["3581","59","<b>ד' פעמים ברוך</b>: ראה ברכות מו, א. שו\"ע אדה\"ז סי' קפז סעי' א."],["3582","60","<b>לחם לבב אנוש יסעד</b>: תהלים קד, טו."],["3583","61","<b>עת אשר שלט האדם באדם</b>: קהלת ח, ט."],["3584","62","<b>פנים הוא ע\"ש לשון פונה</b>: ראה לקו\"ת שלח מב, א."],["3585","63","<b>פני\"ם בפני\"ם דבר ה'</b>: ואתחנן ה, ד."],["3586","64","<b>הכתר. . גלגלתא</b>: ראה תו\"א י, ב. צא, ד. לקו\"ת במדבר יט, ג. נצבים מט, ג. ובכ\"מ."],["3587","65","<b>המשפילי לראות בשמים</b>: תהלים קיג, ו."]]],[2100990110,"שיעור שביעה כו' כי פחו' מכשיעור שוה לכדי שיעור אחר דרוחניו' וגשמיו' שוין וכולא קמי' כלא כו' והיינו וכי לא אשא פנים אחר שמדקדקי' כו' כי הא בהא תליא דמשום טעם נשיא' פנים למעלה מן ההשתלשלו' יכול לשכון אור הברכה גם בפחו' מכשיעור וגם מה שמדקדקי' כו' הוא לפי שמגיעי' למעלה מבחי' פנים כו' וזהו ישא ה' פניו אליך אלי\"ך דוקא פי' גם בכלי שלך שורה ממש מאור א\"ס אע\"פ שאינו לפי ערך סדר ההשתלשלו' כנ\"ל, וגם יתפרש דגם כאשר ישא ה' פניו למעלה מכל ההשתלשלו' מ\"מ יאיר אור השפע אליך גם מבחי' אור המופלא הזה שלמעלה מן ההשתלשלו' וכל זה משום שמדקדקי' ע\"ע כו' וכנ\"ל וד\"ל.\n<b>וישם</b> לך שלום. הנה פי' הענין של שלו\"ם הוא כח המחבר ב' הפכים כאחד כמו עושה<sup data-n=\"3588\">66</sup> שלום במרומיו בין מיכאל שר של מים לגבריאל שר של אש שיחדיו ישכנו ולא יכבו זא\"ז כו' ומוכרח לומר מה שיש לזה הכח לחבר ולקשר ב' הפכים כאש ומים שיהיו מיוחדי' בתכלית האחדו' הוא מפני שמתבטלי' ממציאותם לגבי אור הגבוה משניהם כמשל השר והעבד שמתבטלי' שניהם בבוא המלך כמ\"ש<sup data-n=\"3589\">67</sup> במ\"א, וענין זה הכח המחבר למעלה הוא הנק' שלום וכמ\"ש וכל<sup data-n=\"3590\">68</sup> בנייך למודי הוי' ורב שלום בנייך וארז\"ל אלו<sup data-n=\"3591\">69</sup> ת\"ח שמרבים שלום בעולם כו', פי' למודי הוי' לשון נפעל שנלמדים משם הוי' והוא שהם בחי' טפל ומשמש לדבר הוי' בשעה שלומדים דבר<sup data-n=\"3592\">70</sup> ה' זו הלכה עד שהם נלמדי' מה' כי אינם דבר ויש בפ\"ע כלל וכלל אלא הם רק בחי' כלי לדבר ה' וכמ\"ש ודבר\"י<sup data-n=\"3593\">71</sup> אשר שמתי בפיך כו' לעוצם בחי' הביטול כו' וכמ\"ש<sup data-n=\"3594\">72</sup> במ\"א ביאור דבר זה ע\"פ משה ידבר כו'.\n<b>וזהו</b> ע\"ד ענין מאמרם ז\"ל שכינה<sup data-n=\"3595\">73</sup> מדברת מתוך גרונו של משה כו' וכמ\"ש במ\"א וד\"ל, ואחר שהם למודי הוי' ע\"ד הזה אז יש ביכולתם ע\"י המשכת בחי' ביטול שנמשך ע\"י למודם זה שיהי' נמשך בחי' השלום בכל העולמו' וענין השלום הוא כח המחבר העליון בתחתון כמו שביכולתו לחבר ב' הפכים כנ\"ל וזהו ורב שלום בנייך אחר שהם למודי הוי' כנ\"ל מאלו ת\"ח שמרבים שלום בעולם כי ת\"ח הוא אשר יש בו מבחי' חכמה עילא' דהיינו ביטול דשם מ\"ה דהוי' ע\"ד הנ\"ל בשעה שלומד כו'",[["3588","66","<b>עושה שלום במרומיו. . מיכאל. . לגבריאל</b>: איוב כה, ב. במדב\"ר פי\"ב, ח. זח\"ג יב, ב."],["3589","67","<b>כמ\"ש במ\"א</b>: ראה ג\"כ לקו\"ת נשא כז, א. שה\"ש מח, ד. שערי אורה עא, א. ובכ\"מ."],["3590","68","<b>וכל בנייך למודי הוי'</b>: ישעי' נד, יג."],["3591","69","<b>אלו ת\"ח שמרבים שלום בעולם</b>: ברכות סד, א. וש\"נ."],["3592","70","<b>דבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["3593","71","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["3594","72","<b>וכמ\"ש במ\"א. . ע\"פ משה ידבר</b>: יתרו יט, יט. ראה תו\"א סח, סע\"ב ואילך. תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] רסג, א ואילך. לעיל ע' תעד ואילך."],["3595","73","<b>שכינה מדברת מתוך גרונו של משה</b>: תניא פל\"ד (אמרו עליו). אגה\"ק סכ\"ה (כמארז\"ל). אור תורה בחוקותי מג, סע\"ג (ומ\"ש רז\"ל). שו\"ת בית אפרים חאה\"ע סק\"ז (מו, א — מאחז\"ל). וראה זהר פנחס רלב, ב. שם תוספתא שו, ב. ויקרא ז, א. ואתחנן רסה, א. שמו\"ר פ\"ג, טו. ויק\"ר פ\"ב ג. מכילתא שמות יח, יט. עיון יעקב לפסחים סח, ב."]]],[2100990111,"והיינו להיות בחי' גילוי אור א\"ס למטה כמו למעלה אע\"פ שאין ערך בין עולם הפירוד לגבי עצמו' אור א\"ס מ\"מ יוכל להיות ע\"י הלימוד הזה בהיותו המשכת דבר ה' בבחי' ביטול כנ\"ל לחבר ולקשר אור א\"ס בעולמו', ומפני שהשלום הוא ענין בריח התיכון המבריח מן הקצה לקצה דהיינו מקצה העליון דכתר עד קצה האחרון דמלכו' שמסתתרת עד רגלי העשי' כי בחי' השלום הוא בבחי' קו האמצעי דת\"י כידוע ע\"כ אמרו ז\"ל מרבים שלום ענין ריבוי השלום למעלה ולמטה וכמ\"ש ורב שלום בנייך לפי שבכל עולם עד רום המעלו' בפרט מחבר הוא שם אחר שמחבר מן הקצה לקצה כו' וכענין שאמרו ז\"ל ע\"פ<sup data-n=\"3596\">74</sup> או יחזק במעוזי יעשה שלום לי כו' ב' &lt;רלד&gt;\nשלומו' שלום בפשמ\"ע ושלום בפשמ\"ט וד\"ל, וזהו וישם לך שלום שהשלום הזה תלוי בך לפי שזה השלום נמסר לידך כמ\"ש ורב שלום בנייך להיות בך כח לחבר מן הקצה לקצה בכלל ובפרט ע\"י ואשים<sup data-n=\"3597\">75</sup> דברי בפיך כו' והיינו שיש לברכה זו סמיכות וחיבור עם הברכה שלפניה ישא ה' פניו אליך כי ענין נשיאת פנים הוא למעלה מעלה מכל ההשתלשלו' כנ\"ל וע\"כ כשיאיר אור משם דוקא הוא בחי' הכח שיוכל לחבר מן הקצה לקצה כו' וזהו ישא ה' פניו כו' ואז וישם ל\"ך שלו\"ם ל\"ך דוקא יהא נמסר בחי' השלום להבריח מן הקצה לקצה כו' מפני שזהו תכלית הכונה של הנשיאת פנים שיהא גילוי אור א\"ס שלמעלה מן ההשתלשלו' למטה כמו למעלה כו' וד\"ל.\n<b>ושמו</b> את שמי על בני ישראל ואני אברכם. פי' לאחר שנתברכו בנ\"י בבחי' השלום וכמ\"ש וישם לך שלום שזהו תכלית הכונה מברכה דישא ה' פניו כו' אז אמר ושמו את שמי כו' דהנה אמרו ז\"ל לא<sup data-n=\"3598\">76</sup> מצא הקדב\"ה כלי מחזיק ברכה כמו השלום כו' פי' כלי מחזיק ברכה הענין הוא בחי' הכלי שיומשך אור הרבה לתוכו עד בלי שיעור נק' כלי מחזיק ברכה כו' וכך הוא הענין בכאן לפי שאחר שנק' למודי הוי' בלימוד התורה הרי שם הוי' נקרא עליהם בלימוד התורה דוקא וכמ\"ש בפ' וארא ושמי<sup data-n=\"3599\">77</sup> הוי' לא נודעתי להם כו' וגם ברכת וישם לך שלום שהיא סוף הברכו' אינו אלא ע\"י שנק' למודי הוי' וכמ\"ש וכל<sup data-n=\"3600\">78</sup> בנייך למודי הוי' ואז ורב שלום כנ\"ל והשלום הזה הוא הנק' כלי מחזיק ברכ\"ה פי' שמקבל תוספת ברכה מלמעלה מעלה הרבה יותר מכפי ערך הכלי המקבל כו' וד\"ל. וזהו ושמו את שמי על בנ\"י בברכת השלום הזה ואז נקראו בנ\"י כלי מחזיק ברכה שיתברכו בברכה שלמעלה מכפי ערך הקבלה והוא מ\"ש ואני<sup data-n=\"3601\">79</sup> אברכם פי' אני אברכם מלמעלה למטה דהיינו למעלה מכל ההשתלשלו' גם שאין הכלי מגיע לשם לקבל וזהו מפני ששמו את שמי על בנ\"י בברכת השלום לפי שנק' כלי מחזיק ברכה כו' וד\"ל.",[["3596","74","<b>ע\"פ או יחזק במעוזי. . ב' שלימות</b>: ישעי' כז, ה. סנהדרין צט, ב."],["3597","75","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["3598","76","<b>לא מצא הקב\"ה כלי. . כמו השלום</b>: ראה סוף עוקצין."],["3599","77","<b>ושמי הוי' לא נודעתי להם</b>: וארא ו, ג."],["3600","78","<b>וכל בנייך למודי הוי'</b>: ישעי' נד, יג."],["3601","79","<b>ואני אברכם</b>: נשא ו, כז."]]],[2100990112,"<b>אך</b> עדיין יש להבין אחר שכבר נתברכו למה אמר עוד ואני אברכם דמשמע אני דוקא מפני שאין יכולת לברך ברכה זאת זולתו א\"כ היה לו לברך אותם בברכה זאת מתחלה מעצמו ולמה הוצרך לצוות לכהנים לברכם כו'. אך הענין הוא דאיתא (בס\"י) דיש<sup data-n=\"3602\">80</sup> ברכה בראש וברכה בסוף, ברכה בסוף היינו פי' ואני אברכם וברכה בראש היינו פי' יברכך ה' כו' הנ\"ל, וביאור הדברים מובן דיש ברכה העולה מלמטה למעלה כענין הצמיחה שניתוספת ע\"י הזריעה כו' ויש ברכה הבאה אח\"כ מלמעלה שתצמיח הרבה מאד יותר מכפי ערך הכנת הכלי כו' כמו ויברכהו<sup data-n=\"3603\">81</sup> מאה שערים כו' וכך הענין למעלה דברכת יברכך הנ\"ל הוא הברכה בראש מלמטה למעלה ע\"י בחי' העלא' מ\"ן שהוא כדוגמת הזריעה אך אח\"כ כשנשלמה הברכה שמלמטה למעלה אז המה מתברכים מלמעלה למטה והוא הברכה שבסוף במ\"ש ואני אברכם אני דוקא, ולפי שאין ברכה זו הבאה מבחי' אור א\"ס בעצמו יכולה לשכון אלא בכלי המחזיק ברכה הרבה ע\"כ הקדים לצוות לכהנים לברכם בשלום לפי שאין כלי יכולה להחזיק ברכה זו אלא השלו\"ם וד\"ל.",[["3602","80","<b>דיש ברכה בראש וברכה בסוף</b>: ראה זח\"א כו, ב. רלח, א. זח\"ג רעא, א. (וביאוה\"ז לשם דף קיט, א). לקו\"ת בהר כח, א. נשא כז, א. כח, א. סידור עם דא\"ח שער בהמ\"ז קיב, סע\"ב (בשם ספר יצירה). מאמרי אדה\"א ויקרא ח\"ב ס\"ע תצה. במדבר ח\"ב ע' תתיז ואילך. דברים ח\"ד ע' א'תנז. תו\"ח שמות ע' שיד."],["3603","81","<b>ויברכהו מאה שערים</b>: תולדות כו, יב."]]],[2100990113,"<h3>להבין שרשי הדברים</h3>\n<b>בעזר\"ה</b>\n&lt;רלה&gt;\n\nלהבין<sup data-n=\"3604\">1</sup> שרשי הדברים הנ\"ל. הנה יש להבין שרש ענין ברכת המזון ולמה ברכה ראשונה בכל שהוא וברכה אחרונה צריכה שיעור כו'. ותחלה יש להבין שרש ענין הברכה דיברכך הנ\"ל בהיות ידוע<sup data-n=\"3605\">2</sup> הטעם דהצומח מחי' את המדבר אע\"פ שהוא למטה הימנו במדרגה שהוא משום דשרש הצומח הוא בא מחמת שבירת הכלים שנפלו עמהם רפ\"ח ניצוצי' ונתלבשו למטה בעולם הבריאה עד שנתהווה גם חיצוניו' העשי' מדצ\"ח הגשמיים כידוע ובחי' רפ\"ח ניצוצי' דתוהו המה גבוהים בשרשם הרבה מבחי' התיקון וכמ\"ש ואלה<sup data-n=\"3606\">3</sup> המלכי' אשר מלכו כו' לפני מלוך מלך לבנ\"י כו' ושרש ניצוץ האלקי הוא בא מבחי' התיקון כידוע דשרש התהוות הנשמות הוא בא מיחוד זו\"נ שהוא אחר התיקון כידוע וע\"כ יש כח במאכל הצומח להחיות את נפש האדם כי בחי' הניצוץ דתוהו שמלובש בו גבוה הוא הרבה מניצוץ נפש האדם וזהו כי<sup data-n=\"3607\">4</sup> על כל מוצא פי ה' כו' פי' מוצא פי ה' שבמאכל ויתבאר זה עוד בפי' ויקרא אדם שמות כו'.",[["3604","1","<b>להבין שרשי הדברים</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (ס, ב).\nנדפס בשינויים בלקו\"ת נשא כז, א."],["3605","2","<b>ידוע. . דהצומח מחי' את המדבר</b>: ראה לקו\"ת צו יג, ב. תו\"ח ויגש רלב, א. ובכ\"מ."],["3606","3","<b>ואלה המלכי'</b>: וישלח לו, לא."],["3607","4","<b>כי על כל מוצא פי ה'</b>: דברים ח, ג."]]],[2100990114,"<b>וזהו</b> שאמר בע\"ח<sup data-n=\"3608\">5</sup> דהנשמה א\"צ תיקון לעצמה ולא ירדה בעוה\"ז אלא לברר לבושי נוגה שהוא נפש הבהמיו' שנמשכה מהיכלו' דנוגה כידוע והטעם הוא כי הנשמה כבר ניתקנה להיותה באה מעולם התיקון כנ\"ל לכך א\"צ תיקון לעצמה אלא שבאה לתקן נפש הבהמיו' והמאכלי' כו' שהם באי' מבחי' נוגה שצריכין תיקון מפני שיש בהם ניצוצי' דתוהו שנפלו בשבירה כנ\"ל וד\"ל. וביאור ענין בחי' התיקון הוא מבואר במ\"א ודרך כלל הנה ידוע בבחי' התיקון דמה שנברר לפני האצי' ירד ונעשה בבחי' אצי' ומה שנברר באצי' יורד לבריא' כו' והאדם הוא בשרשו בז\"א דאצי' שכבר נברר ולכך א\"צ בירור אבל המאכל יש בו מן הטוב<sup data-n=\"3609\">6</sup> הוא בחי' באו בסדר ענין הברורי' אלא נפל למטה בלתי בירור וע\"כ צריכי' כל דצ\"ח דעשי' בירור ותיקון וענין הברורי' שלהם הוא דוקא ע\"י האדם להיותו מבחי' התיקון שהוא שם<sup data-n=\"3610\">7</sup> מ\"ה המברר ב\"ן כו' וכמ\"ש במ\"א וד\"ל.\n<b>והנה</b> כיצד הוא אופן בירורי' הללו דמאכלי' ע\"י האדם יובן מתוך משל ענין הברורי' הגשמיי' שיש במאכלי' גם כשעכו\"ם אוכל שהוא צריך בירור בטחינה תחלה ואח\"כ מתבשל בקיבה ומתברר עוד ויוצא הפסולת לחוץ ואח\"כ עולה המובחר ונעשה דם בכבד ומן הכבד עולה ממנו המובחר ללב ומן הלב למוח כו' וכך הוא ענין הברורי' הרוחניי' של המאכלי' דהיינו בחי' רפ\"ח ניצוצי' דקדוש' שיש בהם בהעלם ע\"י השבירה כנ\"ל וניצוץ האלקי שבאדם כשאוכלם הוא מבררם הענין הוא ג\"כ ע\"ד הנ\"ל שבתחלה מתברר חלק הטוב שבמאכל ועולה ונכלל בניצוץ האלקי ע\"י העלא' מ\"ן של הניצוץ באהבה במס\"נ כשמתפלל בכח וחיו' אותו המאכל לפי שבמס\"נ של הניצוץ האלקי כשעולה ונכלל באור האלקי עולין עמו גם כל מה שקיבל חיות רוחני מניצוצי הקדוש' שיש במאכלי' ואמנם זהו א\"א בלתי פירוד הרע מן אותו חלק הטוב &lt;רלו&gt;\nוהוא עד\"מ הבירור של המאכל בקיבה דכמו שמתברר בגשמיותו כך הוא בירור שלו ברוחניותו כו' ועד\"ז מתברר עוד עד שנברר המובחר שבהניצוצי' דתוהו ועולין למעלה בבחי' אצי' בבחי' העלא' מ\"ן בכללו' העלא' מ\"ן דכנ\"י שהוא בחי' מל' דאצי' כידוע ע\"י לאהבה את ה' כו' שיש בכללו' נ\"י בק\"ש וכמבואר למעלה ומי הוא המברר ומעלה אותם הרי הוא בחי' הניצוץ דוקא להיותו מבחי' התיקון שכבר נברר שבזה יתרון מעלתו על ניצוצות דתוהו שבמאכלים שלא נבררו עדיין כנ\"ל ונמצא מובן מזה שזהו ממש כמשל הזורע גרעין א' שיצמח ממנו הרבה חטים כנ\"ל כך ניצוץ האלקי שהוא בא מבחי' ז\"א שהוא מבחי' התיקון נזרע באר\"ץ שהוא שם ב\"ן שנפלו שם ניצוצות דתוהו שהם מבחי' ב\"ן וכמ\"ש וימלוך כו' ונפלו בחיצוניו' העולמות כנ\"ל וז\"ש אור<sup data-n=\"3611\">8</sup> זרוע לצדיק שהוא בחי' יסוד ז\"א שהרי מיחוד דזו\"נ נולדו הנשמו' כנ\"ל וזהו",[["3608","5","<b>בע\"ח דהנשמה א\"צ תיקון</b>: ע\"ח שכ\"ו. ראה תניא פרק לז."],["3609","6","<b>הטוב הוא</b>: בגוכתי\"ק חסר כאן תיבה."],["3610","7","<b>שם מ\"ה המברר ב\"ן</b>: ראה ע\"ח שער (ה) טנת\"א פ\"א. שער (י) התיקון פ\"ג. שער (מ) פנימית וחיצונית דרוש ד. ביאוה\"ז תשא נג, ג. לקו\"ת בחוקותי מז, ג."],["3611","8","<b>אור זרוע לצדיק</b>: תהלים צז, יא."]]],[2100990115,"ג\"כ ענין וזרעתי<sup data-n=\"3612\">9</sup> את ב\"י זרע אדם משם מ\"ה וזרע בהמה מבחי' ב\"ן דמ\"ה כי למ\"ד כלים דז\"א מתלבשי' בבי\"ע עד שכלים הפנימי' נעשי' נשמ' לעולם הבריא' כו' וי' כלים החיצוני' הם נפש בעשי' ונמצא שגם הע\"ה ופחותי הערך שבבנ\"י שיש לו נפש דעשי' בלבד הרי הוא ג\"כ מבחי' מ\"ה דז\"א אלא שהוא מבחי' כלים החיצונים דז\"א כו' (והוא הנק' זרע בהמה כלומר בחי' בהמה שבאדם כי פני אדם דוקא שבמרכבה הוא שרש כללות נ\"י אלא משום דכללות המרכבה כולל אותם פני אדם יש באדם ג\"כ בחי' בהמה כו' וכמ\"ש במ\"א) וד\"ל.\n<b>וזהו</b> ענין יברכך ה' כו' שהוא ענין הברכה בכנ\"י מלמטה למעלה כנ\"ל, כי הנה ארז\"ל לא<sup data-n=\"3613\">10</sup> גלו ישראל לבין אוה\"ע אלא כדי שיתוספו עליהם גרים כו' שנא' וזרעתיה<sup data-n=\"3614\">11</sup> לי בארץ כו' ולכאורה המאמר הזה פלאי הוא דודאי כלום<sup data-n=\"3615\">12</sup> אדם זורע קב אלא להוציא כמה כורים כידוע וא\"כ הי' מהראוי שיהיו גרים בכל דור בישראל בכפלי כפליי' ממספר בנ\"י עצמם ולא ימצאו גרים גם חלק א' מאלף מישראל כו' אך הענין הוא דזריעה זו קאי על ניצוץ האלקי בגוף החומרי כנ\"ל שמלובש בו ע' שנה ואוכל מאכלי' גשמיי' וחי מהם וכמ\"ש ימי<sup data-n=\"3616\">13</sup> שנותינו בהם ע' שנה כו' ומבואר במ\"א שפי' בהם היינו בהכלי' דנוגה (כי אותיות הם<sup data-n=\"3617\">14</sup> מלמטה למעלה היפוך אותיות דמ\"ה כו' כמ\"ש במ\"א) ובכל יום מתפלל בכח האכילה ההיא ועולי' עמו ברורי' רפ\"ח ניצוצו' כו' כנ\"ל הרי עולה קיבוץ גדול מניצוצות דתוהו עם הניצוץ האלקי וה\"ז כמו הזורע קב שמוציא כמה כורים לפי שאין מספר ושיעור לניצוצו' דתוהו שמלובשי' בהיכלו' דנוגה ע\"י השבירה כו' וכמבואר במ\"א<sup data-n=\"3618\">15</sup> ואעשה אותך ש\"ם לגוי גדול כו' ש\"ם דוקא כו' והיינו שאמרו דלא גלו ישראל לבין אוה\"ע לברר לצורך עצמם כי הם כבר מבחי' התיקון כנ\"ל אלא כדי לברר בחי' לבושי' והיכלו' דנוגה שמשם שרש הע' שרים דאוה\"ע והיינו להוסיף גרים כי בחי' ניצוצו' דתוהו נק' גרים והמה במספר גדול בכפלי כפליים מניצוצי' דבנ\"י וכמשל הזורע קב כו' וכמ\"ש וזרעתיה לי בארץ וכנ\"ל בפי' וזרעתי את בית ישראל כו' וד\"ל וזהו הטעם עצמו שצריך האדם להתפלל בכל יום ולא די לו שיתפלל פ\"א בשבוע או פ\"א בחדש וכיוצא כי ענין התפלה הוא עליות הניצוצי' דתוהו שיבאו בבחי' העלא' מ\"ן עם הניצוץ &lt;רלז&gt;\nשמעלה אותם ומבררם כנ\"ל ובכל יום הרי יש ניצוצות חדשות כי מתחדשי' באדם בכל יום ניצוצי' חדשות מן המאכלים שהוא אוכל בכל יום מה שלא אכל עד עתה וכחות הגוף מתחדשי' מחידוש חיות מאכלי' בכל יום מה שאין בחבירו א\"כ צריך בכל יום להתפלל בבקר והוא",[["3612","9","<b>וזרעתי את ב\"י</b>: ירמי' לא, כו."],["3613","10","<b>לא גלו ישראל. . שיתוספו עליהם גרים</b>: פסחים פז, ב."],["3614","11","<b>וזרעתיה לי בארץ</b>: הושע ב, כה."],["3615","12","<b>כלום אדם זורע</b>: ראה פסחים פז, ב."],["3616","13","<b>ימי שנותינו בהם ע' שנה</b>: תהלים צ, י."],["3617","14","<b>הם. . היפוך אותיות דמ\"ה כמ\"ש במ\"א</b>: ראה לקו\"ת במדבר ו, ד."],["3618","15","<b>במ\"א ואעשה אותך שם לגוי גדול</b>: ראה תו\"ח חיי שרה קכא, ג. שמות [הוצאת קה\"ת — תשס\"ג] רלא, א. מאמרי אדה\"א דברים ח\"ד ע' א'תסא. וש\"נ. ויקרא ח\"א ס\"ע עב ואילך. מאמרי אדה\"ז תקע\"א ע' קד. וש\"נ. שע\"ת קמא, א."]]],[2100990116,"להעלות מ\"ן מן העבר ומהתחדשו' ניצוצות של זה היום שיוכל להעלותם להבא כו' וד\"ל וע\"כ צריך להיות גם בתפלה בחי' המשכת מוחי' חדשי\"ם דוקא כידוע בפרע\"ח<sup data-n=\"3619\">16</sup> בפי' חדשים לבקרים כו' ובדברי רז\"ל ג\"כ מרומז במה שפסקו שצריך לחדש דבר כו' בחוזר התפלה כו' מפני שהתפלה שייך עיקרה לבחי' הברורי' וזהו מתחדש בכל יום ע\"כ צ\"ל ג\"כ שיהי' בכל יום בעיניך כחדשים כו' אבל האדם מצד עצמו היה די לו בתפלה א' כי הנפש עצמו א\"צ תיקון כי כבר נתקנה להיותה באה מעולם התיקון אלא מפני שבאה לתקן לבושי נוגה צריכה להתפלל בכל יום וד\"ל.\n<b>וזהו</b> פי' יברכך ה' שיתברכו כנ\"י בתוספת מרובה על עיקר שרש נשמותיהם מצד העלא' הברורי' דרפ\"ח כנ\"ל שהם במספר גדול אלף פעמי' כמספר בנ\"י וכמשל הזריעה הנ\"ל והיינו מלמטה למעלה דוקא דהיינו בבחי' א\"ח ע\"י התפלה שנק' סולם כנ\"ל וכמשל הצמיחה שצומחת מלמטה למעלה כו' וד\"ל.\n<b>ועתה</b> יש להבין שרש ענין הברכה השני' יאר ה' פניו אליך כו'. הנה דרך כלל ברכה ראשונ' דיברכך כו' הוא בחי' העלא' מ\"ן וברכה שני' דיאר כו' הוא בחי' המשכת מ\"ד שבא דוקא אחר העלאת מ\"ן כידוע וברכה שלישי' דישא ה' פניו כו' הוא למעלה המחבר המ\"ד ומ\"ן כו' דהנה בחי' העלא' מ\"ן דברורי' דרפ\"ח הנ\"ל בברכת יברכך כו' עדיין לא נשלם ענין הברורי' בשלימות כי בחי' העלא' מ\"ן אע\"פ שגם הוא נק' בשם בירור כידוע אמנם עיקר שלימות הבירור אינו אלא לאחר שנמשך בחי' המשכת המ\"ד על המ\"ן כידוע בע\"ח בפי' ע\"כ יעזוב כו' ודבק באשתו והיו לבשר אחד פי' לבשר אחד הוא כאשר מתחברים ומתדבקי' מ\"ן ומ\"ד יחד דוקא כי בחי' המ\"ד מברר בחי' המ\"ן והיו לאחדים ע\"י בירור זה השני וזהו שלימות הבירור והוא ענין המאמר למהוי<sup data-n=\"3620\">17</sup> אחד באחד פי' אחד תתא' דנוק' דז\"א הוא בחי' מ\"ן וכשמתחבר ומתאחד עם אחד עילא' דבחי' ז\"א שהוא בחי' מ\"ד כידוע אזי בחי' אחד נעשה שלם בשלימות והיינו מפני התבררו' אחד עילא' באחד תתא' וזהו למהוי אחד באחד ויש בו ב' פרושי' ושניהם אמת דאחד עילא' נעשה אחד ע\"י אחד תתא' שהרי לא נק' אדם אלא בכללא<sup data-n=\"3621\">18</sup> דדכר ונוק' וכמ\"ש זכר<sup data-n=\"3622\">19</sup> ונקבה בראם ויקרא שמם אדם כמ\"ש בזוהר והב' דאחד תתא' דנוק' נעשה אחד ע\"י חיבורו באחד עילא' מטעם שהמ\"ד מברר מ\"ן והכל ענין א' הוא משום דבחיבור שניהם דוקא נעשה בחי' אחד שלם וזהו למהוי אחד באחד וכענין והיו לבשר אחד למטה ביחוד זכר ונקבה גשמיי' כמבואר בע\"ח וד\"ל.",[["3619","16","<b>בפרע\"ח בפי' חדשים לבקרים</b>: איכה ג, כג. וראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכז. ו \"נ. שערי תשובה שער התפלה כח, ג."],["3620","17","<b>למהוי אחד באחד</b>: זח\"ב קלה, סע\"א."],["3621","18","<b>בכללא דדכר ונוק'. . ויקרא שמם אדם כמ\"ש בזוהר</b>: בראשית ה, ב. וראה זהר בהקדמה יג, ב."],["3622","19","<b>זכר ונקבה בראם</b>: בראשית ה, ב."]]],[2100990117,"<b>והנה</b> בעבודת ה' יובן זה הענין ג\"כ כי בחי' העלא' מ\"ן בתפלה במס\"נ הוא ענין התשוקה שיהי' גילוי אלקו' כנ\"ל והמשכת המ\"ד אח\"כ היינו כשנעשה ונמשך בחי' גילוי זה מן ההעלם כנ\"ל ומתחלה לא הי' גילוי זה &lt;רלח&gt;\nעדיין באמת אלא רק שהי' חפץ ומשתוקק לזה הגילוי בלבד והוא מ\"ש ואל<sup data-n=\"3623\">20</sup> אישך תשוקתך שהוא בחי' העלא' מ\"ן ואח\"כ והוא<sup data-n=\"3624\">21</sup> ימשול בך שהוא המשכת מ\"ד היינו כשנעשה ונגמר באמת זה הגילוי כמו שהי' לו התשוקה ואין מסתיר למטה כמו למעלה כו' וזהו ענין המשכו' ד' ברכות דברכת המזון דידוע בפע\"ח שהן בחי' המשכו' מוחי' דנוק' ומפני כי בחי' המוחי' נחלקי' לד' מוחי' חו\"ב חו\"ג כו' ע\"כ יש ד' ברכות והרביעי' מדרבנן כי מדאוריי' שהוא תושב\"כ בבחי' ז\"א שעיקרו ג' מוחי' חב\"ד די בג' ברכו' אבל בבוא השפע למלכות תושבע\"פ כו' נחלק לד' חלקי' כו' וכל זה באמרו ברוך אתה הוי' פי' משם הוי' מ\"ה דז\"א לנוק', והנה שרש כל המ\"ד הוא בא מבחי' אור אבא שמאיר בבחי' מוחי' דז\"א כו' כי בחכמה<sup data-n=\"3625\">22</sup> אתברירו דוקא כידוע וזהו ענין הברכה השני' יאר ה' פניו אליך פי' כמ\"ש חכמת<sup data-n=\"3626\">23</sup> אדם תאיר פניו והוא בחי' מוחי' דאבא שמלובש בז\"א עד שמאירי' פניו כו' עד שיכול להמשיך מ\"ד לברר המ\"ן דברכה הראשונה הנ\"ל והוא שלימות הבירור כנ\"ל וד\"ל.\n<b>ישא</b> ה' פניו אליך, פי' אחר שנמשך בחי' מ\"ד דז\"א על העלא' מ\"ן דמאכלי' בברכת המזון כנ\"ל ונתחברו יחד כנ\"ל צריך להגביהם ולהעלותם יחד אל בחי' מקור הגבוה משניהם יחד והוא ענין ישא ה' פניו כו' ואמרו ז\"ל הטעם אמר הקדב\"ה וכי לא אשא פנים לישראל אחר שהם מדקדקי' ע\"ע עד כזית כו', ויש להקדים תחלה ענין א' הנז' בזוהר<sup data-n=\"3627\">24</sup> ובע\"ח בכמה דוכתי דבחי' בוצינא דקרדניתא שהוא הנק' קו המדה ונק' גם בשם משחתא כו' שרשו הוא רק בחי' ה\"ג דבח\"ס דא\"א אך בחי' ה\"ג הללו מבחי' גבורה דע\"י הם שמלובש בח\"ס כו' וענין זה הנק' קו המדה הוא הנותן קצבה ומדה לכל הברורי' שמתבררי' ע\"י החכמה כמה יתברר כו' ולכך שרשו בבחי' ה\"ג דח\"ס דהיינו מבחי' גבורה דע\"י שמלובש בח\"ס כו' כי ענין מדה זו בחכמה בחי' צמצום הוא שמצמצם הדבר שבאופן כך וכך יהי' בחי' הבירור במ\"ד ומ\"ן כשיתחברו ולא באופן אחר כמו ע\"ד דוגמא בכל מעשה המצות בכלל שהם בחי' יחוד דמ\"ה וב\"ן וכמאמר<sup data-n=\"3628\">25</sup> לשם יחוד קדב\"ה ושכינתי' שאו' על כל מצוה בעשותה כו' כידוע והנה כל מעשה המצוה יש לה פרט מיוחד שבאופן זה תתכשר המעשה להיות במעשה זו בחי' היחוד העליון דמ\"ה וב\"ן ואם לאו אינה מצוה כלל ולא נעשה שום יחוד דמ\"ה וב\"ן על ידה כו' כמו מצות<sup data-n=\"3629\">26</sup> ציצית בג'",[["3623","20","<b>ואל אישך תשוקתך</b>: בראשית ג, ט."],["3624","21","<b>והוא ימשול בך</b>: בראשית ג, טז."],["3625","22","<b>בחכמה אתברירו</b>: ראה זח\"ב רנד, ב."],["3626","23","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["3627","24","<b>בזוהר ובע\"ח. . בוצינא דקרדניתא</b>: ראה זח\"א טו, א. ובאור החמה ומקדש מלך שם. ת\"ז רת\"ה ובכסא מלך שם. ראה תניא שער היחוד והאמונה פ\"ד."],["3628","25","<b>וכמאמר לשם יחוד קדב\"ה ושכינתי'</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ס\"ע תתיא ואילך."],["3629","26","<b>מצות ציצית בג' כנפות</b>: ראה או\"ח סי\"א, ד."]]],[2100990118,"כנפו' ופחו' מד' חוטין כו' וכיוצא ותפילין<sup data-n=\"3630\">27</sup> שאינם מרובעו' וכיוצא בזה הרי נמדד מדה וקצבה ליחוד זה דמ\"ד ומ\"ן בכל הענינים איך יהיו ובאיזה אופן יהיו דהיינו כמה יהי' הבירור וכמה לא כו' והנה מי שהוא מודד המדה הזאת למעלה הוא הנק' קו המדה שעל ידו נמדד כל עניני הבירור שע\"י חכמה כמה יהיו כו' עד\"מ אמת הבנין שמודדין בו כמה יהי' האורך והרוחב כו' וכמ\"ש במ\"א ולהיות כי הקו המדה הזה הנה הוא מודד בשיעור החכמה דהיינו כמה יהי' אור החכמה מברר כו' שהרי כל הברורי' א\"א כ\"א ע\"י החכמה כמאמר דבחכמה אתברירו דוקא א\"כ צמצום המדה הוא בחכמה שלא יומשך שיעור כח מ\"ה לברר רק כך וכך כו' ע\"כ נק' קו המדה &lt;רלט&gt;\nהמצמצם זה השיעור דכח מ\"ה כו' בשם בחי' ה\"ג דח\"ס כי בחי' חכמ' סתימא' ידוע שנק' משכיל שהוא בחי' המקור לחכמה דאצי' המברר כו' כי הוא נקרא בחי' חכמה שבכתר בדרך כלל ובהיותו מצמצם בבחי' צמצום על המשכת החכמה איך וכמה כו' ע\"כ הוא מבחי' הגבורות והדינין ובכלל הוא בחי' גבורה דע\"י שמלובש בח\"ס וזהו הענין שנקרא<sup data-n=\"3631\">28</sup> החכמה בשם די\"ן לפעמי' ולפעמי' נק' בשם החסדי' כידוע כי אור<sup data-n=\"3632\">29</sup> אבא מקור החסדי' כו' דמפני בחי' הצמצום הזה נק' ח\"ס בשם דין לגבי האצי' אבל בחי' חכמה סתם שמשפעת האור לאצי' נק' חסד כו' וכמ\"ש במ\"א וד\"ל.\n<b>ואחר</b> הקדמה זו יובן בענין ברכת המזון על פחות מכשיעור שביעה כו' דהנה בהיות המאכל פחות מכשיעור שביעה בגשמיות גם ברוחניות המאכל דהיינו חלקי הטוב הגנוז בו מרפ\"ח ניצוצי' דתוהו כנ\"ל ג\"כ אין בו כדי שיעור הראוי להיות מזה בחי' העלא' מ\"ן למעלה עפ\"י מאמר קו המדה הנ\"ל שנתן קצבה ומדה לשיעור מ\"ד ושיעור מ\"ן וכיצד יהי' הבירור בחכמה כו' ועל פחות מכשיעור שביעה אינו נקרא כלי להחזיק ברכה כלומר אינו בחי' כלי להעלא' מ\"ן עד שיומשך בו הברכה להשפיע בו בחי' מ\"ד והוא בברכת המזון לומר עליו ברוך אתה הוי' כנ\"ל כי אין בחי' חכמה דמ\"ה מברר ב\"ן אלא כשנק' כלי להחזיק בו הברכה כו' וזהו שאמר ואכלת<sup data-n=\"3633\">30</sup> ושבעת דוקא והדר וברכת את ה' אלקיך אבל פחו' מכדי שביעה אין בו העלא' ניצוצו' כ\"כ כדי השיעור להיו' לשובע למעלה ג\"כ בבחי' מל' דאצי' שנק' נפש כמ\"ש צדיק<sup data-n=\"3634\">31</sup> אוכל לשובע נפשו כו' וכמ\"ש בזוהר וד\"ל. וזהו ישא ה' פניו אליך שנושא פנים לישראל משום שמדקדקי' ע\"ע לברך בהמ\"ז בפחו' מכדי שיעור שביעה ג\"כ כו' כי בחי' פני\"ם הוא בבחי' אור אבא שמאיר בבחי' מוחי' דז\"א כנ\"ל אבל למעלה מעלה מבחי' אור אבא דהיינו",[["3630","27","<b>ותפילין שאינם מרובעו'</b>: ראה טוא\"ח סל\"ב."],["3631","28","<b>שנקרא החכמה בשם דין. . ולפעמים. . החסדי'</b>: ע\"ח שער או\"א פ\"ו. וראה תו\"א ה, ד — ושבחו האריז\"ל. לקו\"ת ראה לא, א — כמ\"ש החייט."],["3632","29","<b>אור אבא מקור החסדים</b>: ראה סידור שער התפילין ט, סע\"ד. ביאוה\"ז במדבר קמה, ב. אמרי בינה קכז, א."],["3633","30","<b>ואכלת ושבעת. . וברכת את ה' אלקיך</b>: דברים ח, י."],["3634","31","<b>צדיק אוכל לשובע נפשו</b>: משלי יג, כה."]]],[2100990119,"בבחי' פנימי' הכתר שלמעלה גם מבחי' ה\"ג דח\"ס הנ\"ל הנק' קו המדה שם אין הפרש כלל בין שיש בחי' כלי כשיעור העלא' מ\"ן או שאין בחי' כלי כשיעור הצריך כו' כי בחי' כתר דא\"א הוא למעלה מעלה גם מכל עיקר ההשתלשלו' דאבי\"ע עד שבחי' האצי' ובחי' העשי' שוין לגביו כי גם אדם דאצי' נק' אדם דעשי' בלבד בערך כללות ההשתלשלו' דא\"ק נק' אדם דבריא' וע\"י נק' אדם דיצי' וז\"א נק' אדם דעשי' כו' כידוע וא\"כ לגבי בחי' כתר דא\"א ששם מאיר מבחי' א\"ק נחשב האצי' והעשי' כמעט בערך א' אחר שגם האצי' בחי' עשי' לגביו כערך בחי' המעשה לגבי המחשבה כידוע דמשל בי\"ע הוא בחי' מחשבה דו\"מ כו' וד\"ל ועליו נא' המשפילי<sup data-n=\"3635\">32</sup> לראות בשמים וארץ שרוחניות וגשמיו' שוין כו' ולשם הוא אומר בברכה זו השלישי' ישא ה' פניו פי' שיעלה בחי' הפנים דאור אבא למעלה מעלה בבחי' פנימי' א\"א ומשם יצוה את הברכה גם בפחות מכדי שיעור שביעה מטעם שהוא למעלה מבחי' קו המדה וד\"ל וע\"כ אמרו ז\"ל אמר הקדב\"ה וכי לא אשא פנים לישראל אני אמרתי ואכלת ושבעת וברכת כו' והם מדקדקי' ע\"ע עד כזית כו' פי' כנ\"י המה בבחי' מל' דאצי' כידוע וחכמי ישראל הוא בחי' חכמה שבמל' והוא ענין תורה שבע\"פ שהם דקדוקי סופרים כו' והם החמירו ע\"ע להיות חיוב ברכהמ\"ז גם בכזית מטעם שנעוץ תחלתן בסופן דוקא ומל' עולה &lt;רמ&gt;\nעד פנימי' הכתר ע\"כ הגיעו למעלה מבחי' קו המדה שמשם יוכל להיות השפע גם בפחו' מכשיעור שביעה עכ\"פ מטעם הנ\"ל ואעפ\"כ נתנו ג\"כ שיעור ומדה והוא בכזית או בכביצה אלא שצמצמו בשיעור קטן מאד לפי שהעולמו' הנפרדי' צריכים להתנהג בהכרח ע\"פ בחי' קו המדה הנ\"ל להיות שההשתלשלו' שלהם באה בבחי' אור וכלי כו' אלא לפי שהמשיכו מבחי' פנימי' הכתר ע\"כ יכול לירד השפע גם בשיעור מצומצם מאד כזית גם שאינו בכדי שביעה מטעם הנ\"ל וד\"ל וזהו שאמר הקדב\"ה האיך לא אשא ואגביה פנים למעלה מבחי' קו המדה הנ\"ל אחר שמדקדקי' ע\"ע עד כזית כו' וד\"ל.\n<b>וישם</b> לך שלום. פי' שלו\"ם הוא בחי' הממוצע המחבר ב' הפכי' כמו עושה שלום<sup data-n=\"3636\">33</sup> במרומיו שמחבר ע\"י השלום ב' הפכי' דמיכאל וגבריאל שר של מים ושל אש יחד וכיוצא בזה ובחי' הממוצע ידוע שהוא בבחי' קו האמצעי דת\"י כו' והדעת הוא עיקר הממוצע להיותו מחבר למעלה חו\"ב<sup data-n=\"3637\">34</sup> תרין ריעי' כו' הנק' יחוד דאו\"א והוא דעת עליון וגם מחבר למטה ביחודא תתא' דזו\"נ והוא דעת תחתון כו' וע\"ז נא' ורב שלום בנייך כו' פי' כמארז\"ל ת\"ח<sup data-n=\"3638\">35</sup> מרבים שלום כו' ענין ריבוי השלום הזה היינו ע\"ד הנ\"ל בדעת שהוא עושה השלום למעלה וגם למטה כו' וז\"ש או<sup data-n=\"3639\">36</sup> יחזק במעוזי יעשה שלום לי שלום יעשה לי ב' שלומות כמאמרם ז\"ל שלום בפמליא של מעלה ושלום בפמליא של מטה דהיינו ב' יחודי' הנ\"ל",[["3635","32","<b>המשפילי לראות</b>: תהלים קיג, ו."],["3636","33","<b>עושה שלום במרומיו</b>: איוב כה, ב."],["3637","34","<b>חו\"ב תרין רעין</b>: ראה זח\"ב נו, א. זח\"ג ד, א. אוה\"ת נצבים ע' א'רכב."],["3638","35","<b>ת\"ח מרבים שלום</b>: סוף ברכות. וש\"נ."],["3639","36","<b>או יחזק במעזי</b>: ישעי' כז, ה."]]],[2100990120,"פמליא של מעלה הוא בחי' יחודא עילאה דאו\"א ופמליא של מטה הוא יחוד דזו\"נ כו' וד\"ל.\n<b>וביאור</b> הדברים הללו ידוע על פי' הפסוק כי<sup data-n=\"3640\">37</sup> אל דיעות הוי' כו' שיש ב' דיעות דעת עליון המחבר חו\"ב היינו כשמחבר אור א\"ס שבחכמה שהוא בבחי' אין שיבא לידי גילוי בבינה שנק' יש וכמ\"ש להנחיל<sup data-n=\"3641\">38</sup> אוהבי יש שהרי נאמר קמי'<sup data-n=\"3642\">39</sup> כלא חשיב שלמטה בחי' האין ולמעלה בחי' יש בהיפוך זה אבל ע\"י היחוד דאו\"א נמשך בחי' אין גם ביש דבינה להיות למטה בבינה כמו למעלה בחכמה דהיינו שיהי' גם בהשגה דבינה נתפס איך דקמי' כלא וכאין כו' ועד\"ז ביחודא דזו\"נ דהיינו מאצי' לבי\"ע שהוא בא ג\"כ מאין ליש אלא ששם נפרד היש לבחי' גבול ממש אבל היחוד שם היינו שאור האצי' יאיר בבריא' הענין הוא ג\"כ ע\"ד הנ\"ל שיהי' למטה בבריא' כמו באצי' דהיינו כמו שלמעלה באצי' אין היש תופס מקום דקמי' כלא כו' כך למטה בעולם הנפרד לא יהי' היש תופס מקום ולא יסתיר המסתיר כלל וכלל וד\"ל וכל אלה בחי' היחודי' נעשה הכל עפ\"י הדעת להיותו בחי' הממוצע להביא ולחבר הארת אור העליון בתחתון שיהי' האור בתחתון כמו בעליון ממש והיינו ענין ב' השלומו' להיו' שלום בפמליא של מעלה לחבר ב' הפכי' דחו\"ב כנ\"ל ושלום בפמליא של מטה מאצי' לבי\"ע לחברם יחד ע\"ד הנ\"ל כי בחי' השלום נמשך מן הדעת אחר שהן בקו א' והוא בחי' קו האמצעי כנ\"ל והיינו שאמרו ז\"ל לא<sup data-n=\"3643\">40</sup> מצא הקדב\"ה כלי מחזיק ברכה אלא השלום פי' כלי הוא בחי' המקבל האור והוא בחי' בינה לגבי חכמה ומל' דאצי' שבבי\"ע לגבי ז\"א כו' ובכולם אין האור יורד בבחי' ברכה להיו' גילויו בכלי כמו שהוא למעלה שזהו ענין הברכה כידוע &lt;רמא&gt;\nאלא ע\"י השלום שמביא ומחבר המשפיע במקבל כנ\"ל וד\"ל וזהו וישם לך שלום אחר שאמר ישא ה' פניו כו' כי הנה מ\"ש ורב<sup data-n=\"3644\">41</sup> שלום בנייך וכנ\"ל היינו אחר שאמר וכל בנייך למודי הוי' פי' למודי הוי' הוא כמו שמבואר למעלה בענין לימוד התורה להיו' גילוי אור א\"ס למטה כמו למעלה באין מסתיר מפסיק כו' ואז נמשך בחי' דעת הנ\"ל לעשות היחודי' הנ\"ל וכמו גם בפחו' בכשיעור לברך בהמ\"ז והגם שבפחו' מכדי שיעור אין כלי אבל ע\"י השלום נעשה בחי' כלי להחזיק ברכה גם שלא לפי ערך הכלי וכמשמעו' לשון כלי להחזיק ברכה שגם אם אין ערך המקבל לכך מ\"מ מועט מחזיק את המרובה כו' והוא לפי שישא ה' פניו כו' למעלה מבחי' קו המדה כנ\"ל ע\"כ יהי' אז בחי' כלי להחזיק ברכה גם שלא לפי ערך המקבלי' והוא ע\"י השלום ולהיותו ג\"כ למעלה מבחי' קו המדה אחר שיש בכחו לחבר העליון בתחתון וזהו וישם לך שלום שיהא המשכת השלום תלוי ב\"ך מפני שישא ה' פניו כו' למעלה מבחי' קו המדה כנ\"ל וד\"ל.",[["3640","37","<b>כי אל דעות הוי'. . ב' דיעות</b>: נסמן לעיל ע' תנט."],["3641","38","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["3642","39","<b>קמי כלא חשיבי</b>: נסמן לעיל ע' תעד."],["3643","40","<b>לא מצא הקב\"ה כלי מחזיק ברכה</b>: ראה סוף עוקצין."],["3644","41","<b>ורב שלום בנייך</b>: ישעי' נד, יג."]]],[2100990121,"<b>ושמו</b> את שמי על בנ\"י ואני אברכם. פי' ואנ\"י<sup data-n=\"3645\">42</sup> הוא אותיות אין שהוא בחי' הכתר והענין הזה הוא אחר הברכה הנ\"ל מלמטה למעלה באמרו יברכך כו' דהנה מה שהברכה בא בבחי' תוס' וריבוי מלמטה למעלה הנה זה בא בבחי' אור חוזר שעולה למעלה מעלה עד בחי' הכתר כי בחי' מל' עומדת לנגד בחי' הכתר מלמטה למעלה ולהיות כי נעוץ<sup data-n=\"3646\">43</sup> סופן בתחלתן דוקא כידוע ע\"כ המלכו' עולה עד הכתר<sup data-n=\"3647\">44</sup> דוקא מפני שיש בחי' בריח התיכון שמבריח מן הקצה לקצה דהיינו מתחלתן לסופן ומסופן לתחלתן כו' וז\"ש רבבה<sup data-n=\"3648\">45</sup> כצמח השדה כו' עד\"מ צמח השדה שעולה בבחי' א\"ח ובברכה שמתברך מלמטה למעלה באה ועולה עד בחי' הכתר שהוא בלתי מוגבל ולמעלה מן המספר והיינו ותבואי<sup data-n=\"3649\">46</sup> בעדי עדיים כלומר כתר כל הכתרים כמ\"ש במ\"א וכך אני אברכם מלמעלה למטה ג\"כ מבחי' הכתר דא\"י<sup data-n=\"3650\">47</sup> וכמ\"ש ישא ה' פניו אליך ומבואר למעלה שהוא המשכת האור מפנימי' הכתר וזהו ואני אותיו' אין שהוא בחי' הכתר שיברכם מלמעלה למטה כשם שעלה הברכה מלמטה למעלה כו' וד\"ל.\n<b>ושרש</b> ענין ויקרא האדם שמות כו' הנה לכאורה אינו מובן כלל מ\"ש ויקרא האדם שמות כו' דהלא האדם נברא בע\"ש וכבר נבראו כל הנבראים עד יום הששי וכידוע המאמר דאפי'<sup data-n=\"3651\">48</sup> יתוש קדמך כו' וא\"כ כבר הי' קריאת שם לכל הנבראי' שהרי בעשרה מאמרו' נברא העולם בכלל ובדרך פרט נתחלקו לצרופי' הרבה ועכ\"פ יש צירוף מיוחד לכל נברא בפרט כידוע, אך הענין הוא דבאמת כבר הי' צרופי' מיוחדי' לכל נברא אבל היו רק בהעלם למעלה בבחי' דיבור העליון שמחי' כל הנבראי' כו' אבל להמשיכם לידי גילוי מן ההעלם הוא שקרא האדם שמות לכל החיה והבהמה כו' וזהו שאמרו ז\"ל במדרש<sup data-n=\"3652\">49</sup> ראו חכמתו כו' שחכמתו של אדם גרמה לו להבין בשמות שכבר נקראו למעלה לסוס ולחמור כו' וד\"ל אך הנה בקריאה זו &lt;רמב&gt;\nבגילוי מן ההעלם הוא שתיקנם והעלם להיות בבחי' מדרגת התיקון העליון דהרי האדם הוא משם מ\"ה שהוא בחי' התיקון וכמ\"ש באד\"ר<sup data-n=\"3653\">50</sup> באני עלמין ולא אתקיימו עד דאתברי פרצופא דאדם כו' ואז נמשך בחי' הביטול בכל הנבראי' כענין חמורו של רפב\"י שהוא היה מבחי' בהמות בהררי אלף כו' וע\"כ לא נא' פסוק זה דויקרא האדם אלא בהיותו בג\"ע קודם חטא עה\"ד כו' וד\"ל.",[["3645","42","<b>ואני אותיות אין</b>: ראה פרדס ש\"ג פ\"א. ע\"ח שער מב, פ\"א."],["3646","43","<b>כי נעוץ סופן בתחלתן</b>: ס\"י פ\"א, מ\"ז."],["3647","44","<b>הכתר. . בריח התיכון</b>: ע\"פ לשון הכתוב תרומה כו, כח. ויקהל לו, לג. ראה זהר בלק קפו, ב. ובהגהת הרח\"ו שם."],["3648","45","<b>רבבה כצמח השדה</b>: יחזקאל טז, ז."],["3649","46","<b>ותבואי בעדי עדיים</b>: שם."],["3650","47","<b>דא\"י</b>: דאור ישר."],["3651","48","<b>דאפי' יתוש קדמך</b>: סנהדרין לח, א."],["3652","49","<b>במדרש ראו חכמתו</b>: ב\"ר פ\"ח, א."],["3653","50","<b>באד\"ר באני עלמין ולא אתקיימו</b>: ראה זהר (אדרא רבא) נשא קלה, א."]]],[2100990122,"<b>ואחר</b> כל הנ\"ל מובן הטעם מה שברכת המזון צריכה שיעור כדי שביעה כנ\"ל אבל ברכה<sup data-n=\"3654\">51</sup> ראשונה די בכל שהוא כי אינה אלא בחי' אתעדל\"ע כדי לעורר אתעדל\"ת בלבד עד\"מ אדם הישן שצריכים להקיצו מן השינה כו' ע\"כ סגי בכל שהוא משא\"כ ברכה אחרונה שאחר האכילה שאתעדל\"ע אחר אתעדל\"ת שבא' בבחי' מ\"ן כו' צריך שיעור דוקא עפ\"י בחי' קו המדה ובנ\"י שמדקדקי' ע\"ע בפחות מכשיעור אינו מדאוריי' אלא מדרבנן מטעם הנ\"ל וד\"ל.",[["3654","51","<b>ברכה ראשונה די בכל שהוא</b>: טוא\"ח סר\"י בתחלתו."]]],[2100990123,"<h3>בהעלותך את הנרות</h3>\n<b>שבת פ' בהעלותך</b>\n<b>בהעלותך</b><sup data-n=\"3655\">1</sup> את הנרות אל מול פני המנורה כו' וזה מעשה המנורה כו' עד יריכה עד פרחה מקשה היא כמראה אשר הראה ה' למשה כן עשה את המנורה<sup data-n=\"3656\">2</sup>. הנה ידוע מה שיש לדקדק<sup data-n=\"3657\">3</sup> בזה דהרי הציווי העיקרי בכאן אינו אלא שבהעלותו את הנרות אל מול פני המנורה יאירו כו' ומה שייכות ענין לכאן מה שמפרש עוד והולך ואומר וזה מעשה המנורה כו' שזה הענין הוא רק באיכות מעשה המנורה שאינה אלא מקשה כו' וכבר נאמר פ'<sup data-n=\"3658\">4</sup> שלימה באיכות מעשה המנורה ולמה כתבה כאן דלכאורה אין מעשה המנורה ענין סמיכות וחיבור כלל להצווי שאמר בענין העלא' הנרות כו'.\n<b>אך</b> הענין יובן בהקדים תחלה לבאר מאמר מדברי רז\"ל במדרש<sup data-n=\"3659\">5</sup> והביאו הרמב\"ן בריש פ' זו וז\"ל<sup data-n=\"3660\">6</sup> למה נסמכה פ' זו לפ' חנוכת הנשיאים לפי שכאשר ראה אהרן חנוכת הנשיאי' חלשה דעתו שאין לו ולשבטו חלק בהם א\"ל הקדב\"ה חייך שלך גדול משלהם שאתה מטיב את הנרות בבקר ובערב ע\"כ וידוע מה שקשה ע\"ז המאמר הרבה דלמה חלשה דעתו בזה וכי מעט קרבנו' הי' מקריב אהרן שיחלש",[["3655","1","<b>בהעלותך את הנרות</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (סב, א).\nמאמר זה באריכות מכ\"ק אדמו\"ר האמצעי נדפס במאמרי אדה\"א בהעלותך ע' תתקמה. ראה ספר המאמרים תרל\"ה ח\"ב ע' שכט. תרל\"ד ע' רכו."],["3656","2","<b>בהעלותך את הנרות. . וזה מעשה המנורה. ֿ. עשה את המנורה</b>: בהעלותך ח, ב. שם ד."],["3657","3","<b>לדקדק בזה</b>: ראה גם רמב\"ן ואור החיים שם, ד."],["3658","4","<b>פ' שלימה. . באיכות מעשה המנורה</b>: תרומה כה, לא ואילך. ויקהל לז, יז ואילך."],["3659","5","<b>במדרש והביאו הרמב\"ן בריש פ' זו</b>: מדרש תנחומא תצוה ב. ורמב\"ן ר\"פ בהעלותך. במדב\"ר פט\"ו ג, ה."],["3660","6","<b>וז\"ל</b>: בשינוי לשון קצת."]]],[2100990124,"דעתו בעבור חנוכת הנשיאי' הלא כל הקרבנו' הקריב וביחוד קרבן הקטורת ע\"ג מזבח הפנימי שמשובח מכולם וכמ\"ש ישימו<sup data-n=\"3661\">7</sup> קטורה באפך כו' וכמבואר עוד פרטיו' של הקושיו' בזה ברמב\"ן בר\"פ זו ע\"ש.\n<b>אך</b> להבין זה המאמר יש להקדים תחלה שרש ענין &lt;רמג&gt;\nחנוכת הנשיאים מהו וקצתו מבואר<sup data-n=\"3662\">8</sup> במ\"א בדרך כללות ענין החנוכה של המזבח דהיינו ע\"ד מ\"ש חנוך<sup data-n=\"3663\">9</sup> לנער עפ\"י דרכו גם כי יזקין לא יסור ממנה פי' עד\"מ כשמחנכין לתינוק לבא בראשונה לבית הספר הנה ידוע שצריך אביו לילך עמו בפעם הראשון ואח\"כ יוכל לילך מהתעוררו' עצמותו אבל בפעם הא' א\"א כ\"א בהיות אביו מוליכו לשם ומרצהו לכך וכן עד\"ז כל חינוך צ\"ל מן הגדול ממנו לחנכו בפעם הא' והכונה הוא בזה כדי שיהי' מגיע מחמת זה החינוך תועלת לתינוק על להבא בכל ימי חייו שיוכל לילך מעצמו כו' והיינו חנוך לנער כו' ואח\"כ גם כי יזקין לא יסור ממנה והנמשל מובן מזה בענין חנוכת המזבח ג\"כ ממש ע\"ד הזה. דהנה בחי' מלכות דאצי' הוא בחי' מזבח עילא' בבהמ\"ק של מעלה כמ\"ש בזוהר<sup data-n=\"3664\">10</sup> ע\"פ אש תמיד תוקד על המזבח כו' והוא מזבח החיצון למטה בבהמ\"ק שלמטה ומבואר בזוהר שם דהיינו שהעלא' מ\"ן מבחי' מל' דאצי' תמיד עולה למעלה ולהיו' מזה בחי' אריה<sup data-n=\"3665\">11</sup> דאכיל קרבנין וזהו אש תמיד תוקד כו' אך כדי שיוכל להיו' העלא' מ\"ן במל' בתמידו' במזבח החיצון שהוא אש שע\"ג המזבח כו' הוצרך להיות בפעם הראשון בחי' חינוך למזבח זה והחינוך בא ממקום ומדרגה היותר גבוה כמשל החינוך לתינוק כנ\"ל והיינו ענין ריבוי הקרבנות בחנוכת המזבח כו' כמבואר במ\"א באריכות.\n<b>והנה</b> בחינוך המזבח החיצון הקריבו י\"ב הנשיאי' את קרבנם כאו\"א כפי הראוי לו בשרש שבטו למעלה כי ידוע די\"ב<sup data-n=\"3666\">12</sup> שבטים שרשם למעלה הן י\"ב גבולי אלכסון דמלכות דאצי' ונק' בס\"י<sup data-n=\"3667\">13</sup> שש כפולות וכו' וזהו ששם<sup data-n=\"3668\">14</sup> עלו שבטים שבטי י\"ה כו' ולפי שהחינוך הי' בבחי' מל' דאצי' ע\"כ הקריבו י\"ב הנשיאים דוקא ולהיות כי החינוך צ\"ל ממקום ומדרגה היותר גבוה כנ\"ל ע\"כ הי' חינוכם בא משרש שרשם",[["3661","7","<b>ישימו קטורה באפך</b>: ברכה לג, י. וראה פרש\"י קרח טז, י: הקטורת החביבה מכל הקרבנות."],["3662","8","<b>מבואר במ\"א</b>: ראה תו\"א וישב כט, סע\"ד. לקו\"ת נשא כט, א-ב. ברכה צח, סע\"ב ואילך. סידור עם דא\"ח רעז, א ואילך. שערי אורה שער החנוכה ד\"ה בכ\"ה בכסליו פל\"ז."],["3663","9","<b>חנוך לנער עפ\"י דרכו</b>: משלי כב, ו."],["3664","10","<b>בזוהר ע\"פ אש תמיד תוקד</b>: צו ו, ו. וראה זהר ח\"ג ל סע\"א ואילך ובמקדש מלך שם. קנא, ב ובהגהות מהרח\"ו שם. וראה גם לקו\"ת שה\"ש נא, ב."],["3665","11","<b>אריה דאכיל קרבנין</b>: ראה זהר ח\"א ו, ב. ח\"ב רעח, א. ח\"ג יז, א. לב, ב. לג, א. יומא כא, ב. לקו\"ת במדבר יא, א."],["3666","12","<b>די\"ב שבטים. . י\"ב גבולי אלכסון</b>: ראה זהר ח\"ג קיח, ב. וברמ\"ז שם. ספר יצירה פ\"ה מ\"א ובפי' הראב\"ד שם. לקו\"ת בהעלותך לא, ב. מסעי צד, א ואילך. ביאורי הזהר לאדמו\"ר האמצעי (פה, א ואילך). ולהצ\"צ (ח\"א ע' תמט ואילך). אוה\"ת בראשית ח\"א טו, ב ואילך."],["3667","13","<b>בס\"י שש כפולות</b>: ראה ספר יצירה שם. מקדש מלך לזהר ח\"א קעו, א."],["3668","14","<b>ששם עלו שבטים</b>: תהלים קכב, ד."]]],[2100990125,"האמיתי שמשם נחצבו ונולדו והוא בחי' אור<sup data-n=\"3669\">15</sup> אימא שנקראת אם הבנים והבנים המה י\"ב שבטי' ובכפולות הן רק ששה קצוות דז\"א כו' שזהו בחי' לאה שילדה<sup data-n=\"3670\">16</sup> ששה בנים כו' וד\"ל.\n<b>וזהו</b> שאמרו ז\"ל שחלשה דעתו של אהרן כאשר ראה חנוכת הנשיאי' ולא מצד הקרבת קרבנות כי הרבה קרבנו' גדולי' במעלה הקריב אהרן כנ\"ל אלא מטעם חנוכת המזבח החיצון דוקא להיות כי חנוכה זו הוא בבחי' מל' דאצי' שהוא בחי' מזבח החיצון דוקא כנ\"ל ובנין ותיקון הנוקבא צריך להיות ע\"י אהרן דוקא ולא ע\"י הנשיאי' להיותו מבחי' אור אבא כידוע דאהרן<sup data-n=\"3671\">17</sup> ומשה הם שניהם בבחי' אור אבא אלא שאהרן<sup data-n=\"3672\">18</sup> מבחי' נצח כו' וידוע דאבא<sup data-n=\"3673\">19</sup> יסד ברתא דוקא וכמשל החינוך דאב לבתו להוליכה לחופה וכאמרו את<sup data-n=\"3674\">20</sup> בתי נתתי כו' וכמ\"ש במ\"א וד\"ל והשיבו הקדב\"ה חייך שלך גדול משלהם, פי' כי אור אבא גדול בכפליים מאור אימא כידוע<sup data-n=\"3675\">21</sup> ע\"כ אמר שלך גדול משלהם.\n<b>וביאור</b> הדברים יובן עפ\"י הקדמה בתחלה להבין ההפרש בין אור אבא לאור אימא, דהנה כתיב ליהודים<sup data-n=\"3676\">22</sup> היתה אורה ושמחה ויש להבין מהו ההפרש<sup data-n=\"3677\">23</sup> בין אור לשמחה אך הענין הוא דהשמחה<sup data-n=\"3678\">24</sup> היא בחי' התגלות להיותה באה מבחי' בינה שהוא גילוי ההשגה וע\"כ היא מולדת התפעלות השמחה שהוא ג\"כ בגילוי וגם היא באה בבחי' מורגש אבל האורה<sup data-n=\"3679\">25</sup> הוא בחי' הארת החכמה שנק' אור כמ\"ש בזוהר בפי' יהי אור כו' ופי' אורה בה\"א הוא התפעלות שנולדה &lt;רמד&gt;\nמצד בחי' החכמה שהוא בחי' ביטול בחשאי כו' כמ\"ש במ\"א וזהו ההפרש שיש בין אור אבא לאור אימא מפני שהחכמה<sup data-n=\"3680\">26</sup> נק' אין והבינה נק' יש כו' כידוע וד\"ל וזהו שאמר חייך שלך גדול",[["3669","15","<b>אור אימא שנקראת אם הבנים</b>: תהלים קיג, ט. זהר ח\"א ריט, א. ח\"ב פד, א. פה, ב. פרדס שער כג (שער ערכי הכינויים) ערך אם הבנים. לקו\"ת שמע\"צ פח, ד. ובכ\"מ."],["3670","16","<b>שילדה ששה בנים</b>: ויצא ל, כ. פרדס שער כג שם. לקו\"ת להאריז\"ל פ' ויצא. תו\"א ויצא כב, ד."],["3671","17","<b>דאהרן ומשה. . אור אבא</b>: ראה לקו\"ש ח\"ו ע' 244 ואילך."],["3672","18","<b>שאהרן מבחי' נצח</b>: כ\"ה גם בתו\"א גי, ריש ע\"ד. מאמרי אדה\"ז אתהלך לאזניא ס\"ע עה. הנחות הר\"פ ע' קיד. תקס\"ח ח\"א ע' שנט. וראה לקו\"ש ח\"ו ע' 244."],["3673","19","<b>דאבא יסד ברתא</b>: זח\"ג רמח, א. רנו, ב. רנח, א. ת\"ז תי' כא (סא, ב)."],["3674","20","<b>את בתי נתתי</b>: תצא כב, טז. וראה קידושין ג, ב. כתובות מו, ב."],["3675","21","<b>כידוע ע\"כ אמר שלך גדול</b>: ראה ע\"ח שער הכללים פ\"י. פע\"ח שער ר\"ח חנוכה ופורים פ\"ה. לקו\"ת להאריז\"ל דברים א, יא."],["3676","22","<b>ליהודים היתה אורה</b>: אסתר ח, טז."],["3677","23","<b>ההפרש בין אור לשמחה</b>: בכ\"ז ראה גם אוה\"ת מג\"א ע' ב'שדמ (בהוצאת קה\"ת תש\"נ — ס\"ע קנא ואילך). וראה ספר הערכים — חב\"ד ח\"ד ערך אורה."],["3678","24","<b>דהשמחה. . בינה</b>: ראה תו\"ח שמות סט, א."],["3679","25","<b>האורה. . הארת החכמה שנק' אור כמ\"ש בזוהר</b>: בסה\"מ תרפ\"א ע' רמא מציין כ\"ק אדמו\"ר מהוריי\"צ: זח\"א טז, ב. וראה סה\"מ תרצ\"ו ע' 63 בהערה."],["3680","26","<b>שהחכמה נק' אין</b>: ראה לקו\"ת פקודי ג, סע\"ג. ו, ב. ובכ\"מ. וראה תניא פי\"ח ובליקוט פירושים שם."]]],[2100990126,"משלהם כי בחי' אור שמאיר מאור אבא דוקא הוא ענין הדלקת נרות המנורה במה שציוהו אל מול פני המנורה יאירו ז'<sup data-n=\"3681\">27</sup> הנרות כי פי' ז' הנרות הן ז' מדות שבמל' דאצי' חו\"ג כו' ואל מול פני המנורה כו' היינו להעלותם לנגד בחי' הפנים דאור אבא שהוא בחי' האמצעי והיינו לנגד מדרגת אהרן מפני ששם שרשו למעלה וזהו כל עיקר ענין מצות הדלקת המנורה באור ושמן וגם להטיב הנרות כו' כדי שעי\"ז יהי' בחי' תיקון הנוקבא שנק' מנורה כידוע ע\"י בחי' הארת אור אבא דוקא והוא ענין ההדלקה שאמר בדרך העלאה וביטול כמ\"ש בהעלותך את הנרו' וכמ\"ש בע\"ח<sup data-n=\"3682\">28</sup> באריכות והוא היפך בחי' השמחה כנ\"ל וע\"כ אמר חייך שלך גדול משלהם כי מדרגת הנשיאים מבחי' אימא שהוא בחי' השמחה ואין לה ערך עם בחי' האור שמאיר בהדלקת המנורה כו' שהוא בא ומאיר מבחי' אור אבא כנ\"ל וד\"ל.\n<b>ועם</b> כל זה יובן מ\"ש וזה מעשה המנורה כו' סמוך למצות הדלקת המנורה ולכאורה אין להם קשר וחיבור כלל זע\"ז כנ\"ל. אך הענין הוא שבמצות המנורה יש ב' מצות א' הדלקת המנורה באור ושמן והב' מצות מעשה גופה של מנורה כו' והנה מצות הדלקת המנורה הוא בחי' הארת אור אבא כנ\"ל אך בחי' בנין המלכות בגופה מבחי' ראשה עד בחי' רגלה הוא ענין מצות<sup data-n=\"3683\">29</sup> המעשה של המנורה כי גופה של המנורה הוא בחי' בנין הנוק' באורו' וכלים מבחי' הראש עד בחי' הרגל הנק' בגמ'<sup data-n=\"3684\">30</sup> רגלי השכינה והיינו מה שאמר סמוך למצות ההדלקה וההעלא' וזה מעשה המנורה פי' אחר שאהרן נצטווה להעלות הנרות דמלכות בהארת אור אבא אזי דוקא נבנית בנין המל' והכל ע\"י אור אבא משום דאבא דוקא יסד ברתא וכנ\"ל שזהו ענין שאמר לו חייך שלך גדול כו' ולכך מפרש והולך דרך כלל מעשה המנורה מראשה לרגלה דהיינו עד יריכה עד פרחה כו' ואע\"פ שכבר נאמר פ' שלימה במעשה המנורה אבל לא נאמר בענין שרש בנינה איך שהוא ע\"י בחי' אור אבא דוקא כו' וד\"ל והיינו מ\"ש מקשה היא עד יריכה כו' כאשר<sup data-n=\"3685\">31</sup> הראה ה' למשה כו' פי' כאשר הראה ה' למשה בחי' שרש המל' למעלה כך עשה את המנורה למטה בבחי' עשי' שהוא תיקון האורו' בכלים מכלים שונים עד יריכה עד פרחה כו' כי עיקר בנינה מהגבורו' המתחלקי' אבל הגבורו'<sup data-n=\"3686\">32</sup> הם באי' מבחי' אור אבא ע\"י אהרן שהוא המדליק הנרו' כו' וכמ\"ש בע\"ח וד\"ל.",[["3681","27","<b>ז' הנרות הן ז' מדות שבמל'</b>: ראה גם לקו\"ת בהעלותך כט, ג ואילך. לא, א."],["3682","28","<b>בע\"ח באריכות</b>: ראה ע\"ח שער לד (שער תיקון הנוקבא) פ\"ז."],["3683","29","<b>מצות</b>: בגוכי\"ק רשם ב' פעמים תיבות מצות."],["3684","30","<b>בגמ' רגלי השכינה</b>: ראה קידושין לא, א."],["3685","31","<b>כאשר הראה ה' למשה</b>: ע\"פ בהעלותך ח, ד."],["3686","32","<b>הגבורו'. . ע\"י אהרן. . וכמ\"ש בע\"ח</b>: ראה ע\"ח שם פ\"ה, פ\"ז."]]],[2100990127,"<h3>זוהר פ' שלח והי' ביום ההוא</h3>\n<b>[זהר שלח לך קע\"א.]</b>\n<b>והי'</b><sup data-n=\"3687\">1</sup> ביום ההוא יצאו מים חיים מירושלים<sup data-n=\"3688\">2</sup> כו' וגמיר קמי' חד עמודא דעלמא ברי' דרבי יהודא, י\"ל שרבו הי' ברי' דר\"י או הינוקא עצמו ברי' דר\"י, מיא דאינון מלרע האיך סלקין לעילא מיני' יתיר בכמה דרגין ומה איצטריך לון, כי ים הקדמוני הוא בינה כמארז\"ל נ'<sup data-n=\"3689\">3</sup> שערי בינה נבראו בעולם שמלמטה למעלה נק' מ\"י בגימ' נ' ומלמעלה למטה נק' ים וכשנמשך למטה הוא ים שעשה שלמה על י\"ב בקר מיכאל כו' והים<sup data-n=\"3690\">4</sup> מל'<sup data-n=\"3691\">5</sup> דאצי' עומד עליהם כו' וא\"כ איך יתכן שיצא מים חיים מירושלים הוא המל' כח האחרון אל הים הקדמוני דבינה שאו\"א<sup data-n=\"3692\">6</sup> הם תרין ריעין כו' ואין<sup data-n=\"3693\">7</sup> א\"ס מתלבש כ\"א בחכמה כידוע ומשם יקבל המלכות<sup data-n=\"3694\">8</sup> דלית לה מגרמ' כלום, וגם ב' קושיות בפסוק הא' האיך אפשר להמל' לעלות יתיר בכמה דרגין חג\"ת כו' והב' למה נצרכי' לשפע דילה כו' ומה אתר דכל מבועין ונחלים נפקין מינה הן חו\"ג והיא השפעת הגילוי ודאימא<sup data-n=\"3695\">9</sup> נק' נחלים ע\"ש מ\"ש כל<sup data-n=\"3696\">10</sup> הנחלים הולכים אל הים כו' והשפע דחכמה כח הנעלם נק' מבועין עד\"מ מעיין הוא הולך מתחת לארץ משא\"כ הנהר הולך בגילוי כו' והמשיל משל שני מאן חמא חפירא דבירא דיהיב מיא למבועין דנביע כמו שא\"א לומר שיהי' הולך מים מן הבריכה והחפירה אל מקור המעיין כך א\"א לומר שיצאו מים כו', ואחידו בי' תלת עמודין חג\"ת והם ג' צדיקים עמודי עולם כו' ותתסחי בכל יומא מטלא קדישא כו' הרב כבסני כו'.\n<b>פתח</b> ההוא ינוקא ואמר והי' ביום ההוא לא ידיע מאן הוא, כי הו\"א לשון נסתר שאינו יודע מי זה וכאומר ההוא בה' הידיעה משמע זה בגילוי וא\"כ איך יתכן יחד כו', אלא בכל אתר ביום ההוא יומא בתראה הוא, הוא מל' דאצי', אלא דא הוא יומא דאחיד סופא בשירותא הוא בחי' בינה כמד\"א ועבד<sup data-n=\"3697\">11</sup> הלוי הוא להמשיך בחי' הוא וכשמתחבר עם מל' ה' תתאה מתפשט בבי\"ע נק' ההוא כו' הכא אית לומר סופא דכל דרגין לאו איהו ירושלים פי' בתמי' וא\"כ מה זה שאמר והי' ביום ההוא יצא מים חיים מירושלים דמשמע שירושלים אינו בחי' ביום ההוא המל'",[["3687","1","<b>והי' ביום ההוא</b>: הנחת המהרי\"ל. נעתק מכת\"י 284 (צח, א).\nהנחת כ\"ק אדה\"א ממאמר זה נדפס בביאוה\"ז שלח צ, ד (מגוכתי\"ק 1025). הגהות מכ\"ק אדמו\"ר הצ\"צ נדפס בביאוה\"ז הצ\"צ ע' תעט."],["3688","2","<b>והי' ביום ההוא יצאו מים חיים מירושלים</b>: זכרי' יד, ח."],["3689","3","<b>נ' שערי בינה נבראו בעולם</b>: ראה ר\"ה כא, ב."],["3690","4","<b>י\"ב בקר. . והים</b>: מלכים-א ז, כה. מד. דהי\"ב ד, טו."],["3691","5","<b>והים מל' דאצילות עומד עליהם</b>: ראה מאו\"א אות יו\"ד, סט\"ז. וראה לקו\"ת קרח נג, ד."],["3692","6","<b>שאו\"א הם תרין ריעין</b>: ראה זח\"ב נו, א. זח\"ג ד, א. אוה\"ת נצבים ע' א'רכב."],["3693","7","<b>ואין א\"ס מתלבש כ\"א בחכמה</b>: ראה תניא פי\"ח. פל\"ה בהגה [ובהנסמן בליקוט פירושים לשם ע' תרעא ואילך]."],["3694","8","<b>המלכות דלית לה מגרמ' כלום</b>: ראה זהר תולדות קלה, סע\"ב. ויחי רלו, ב. רמט, ב. ויקהל רטו, א. בחוקותי קיג, ב."],["3695","9","<b>ודאימא</b>: כ\"ה בכת\"י המעתיק, וניכר שחסר כאן."],["3696","10","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז."],["3697","11","<b>ועבד הלוי הוא</b>: קרח יח, כג."]]],[2100990128,"ביום ההוא יצא מים חיים אל ירושלים כל דרגין קדישין דילה כד אסתחרן איקרון ירושלים שמקיפים זב\"ז כמו ירושלים של מטה הר הבית ובתוכה העזרה כו' עד הארון וכפורת שמוקפין מן כולם שיש עשר קדושות כו' וכך למעלה י\"ס דמל' מקיפים זעג\"ז לגו מכל אינון דרגין אית חד נקודה כבודה בת מלך פנימה כתר מל' ונקודה דא איקרי ההוא וכד יקום יומא דא מגו שבכין דעזרה יקום נביעו דמיא כו', שבכין נק' נצח והוד עד\"מ הכברה שעי\"ז ניסנן הקמח כו' וכך נו\"ה נק' כליות שהם ביעי דדכורא דמבשלי' הזרע להיות נמשך כו' ועד\"מ הרב לתלמיד שצריך להשפיע שכלו שא\"א להרב לומר כמו שמבין הוא בעצמו מפני שלא ישיג התלמיד וצריך ליעץ איך להשפיעו ולהטעימו ולהבינו והכליות המה יועצות איך להשפיעו ולהטעימו ונק' שבכין כו', ומסגיאו חלבא דיניק איתמלי פומי' ואתרבי בי' אריק לפומא דאימא כך חצים אל הים הקדמוני, שזה תירוץ על הקושי' הנ\"ל שבאמת המים חיים מבינה הם אלא שהם נמשכו במל' ומריבוי השפע חוזר לשרשו כו'.\n<b>וביאור</b> זה הנה בחי' עליות העולמות הוא עפ\"י מ\"ש דמל' נק' דיבור ע\"ש ודבר<sup data-n=\"3698\">12</sup> מלך שלטון שהנהגת אבא<sup data-n=\"3699\">13</sup> יסד ברתא כו' כמשל השכל שהוא עצמו מלובש באותיות כו' ועיקר ירידת החכמה לעבודת הבירורים לברר כי יש תוהו ותיקון תהו בחי' פירוד חסד לבדו כו' ובתיקון התכללות חו\"ג שמתלבש החסד בגבו' כו' עי\"ד<sup data-n=\"3700\">14</sup> דמ\"ה וכמאמר עושה שלום כו' והנה יש י\"ס בתוהו ויש שם חלקים מבינה שמתבררים וכשמתבררים הוא גבוה מן התיקון ויש בירור ס\"ג בחי' מלאכי' ונשמות וספי' שמה שא\"א לעלות באצי' נשאר בבריאה.\n<b>והנה</b> פי' מסגיאות חלבא מ\"ה דתיקון דאבא שמתלבש במל' וב\"ן דתוהו נתברר ונעשה ס\"ג למעלה ממ\"ה אריק לפומא דאימא עי\"ד חלקים מבינה דתהו כו' (וכמשל<sup data-n=\"3701\">15</sup> ע\"י דבר חדש שהציפור יכול לדבר יש תענוג כך ע\"י אתהפכא דחשוכא לנהורא מיש לאין נמשך עולם התענוג בחי'<sup data-n=\"3702\">16</sup> וד\"ל) וז\"ש אשת<sup data-n=\"3703\">17</sup> חיל ב\"ן עטרת בעלה ז\"א דמתחילה החכמה נמשכת דרך אמצעות המדות שמהם מקבלת המל' כמ\"ש לך<sup data-n=\"3704\">18</sup> הוי' הגדולה ואח\"כ הממלכה כו' אבל ע\"י הבירורים נתעלו ולכך יצאו מים חיים בחי' מקור הבירורים והחכ' מאין כו' וכנודע שזב צריך מים<sup data-n=\"3705\">19</sup> חיים וכמו פרה אדומה ויש שדינם במים מכונסים כו'.",[["3698","12","<b>ודבר מלך שלטון</b>: קהלת ח, ד."],["3699","13","<b>אבא יסד ברתא</b>: ראה זהר (רעיא מהימנא) פינחס רמח, א. רנו, ב. רנח, א."],["3700","14","<b>עי\"ד דמ\"ה</b>: על ידי דמ\"ה. כ\"ה בכת\"י המעתיק."],["3701","15","<b>וכמשל. . שהציפור יכול לדבר</b>: ראה ג\"כ לקו\"ת שלח מח, ד. תו\"ח ויצא קסו, א. וישלח קצ, ג. ובכ\"מ."],["3702","16","<b>בחי'</b>: כ\"ה בכת\"י מעתיק, וניכר שחסר כאן."],["3703","17","<b>אשת חיל ב\"ן עטרת בעלה ז\"א</b>: משלי יב, ד. וראה לקו\"ת שה\"ש טו, ג. תו\"ח בראשית לו, ד. לך לך צא, א. שמות [הוצאת קה\"ת — תשס\"ג] ע, ג."],["3704","18","<b>לך הוי' הגדולה</b>: דברי הימים-א כט, יא."],["3705","19","<b>מים חיים. . פרה אדומה</b>: ראה חוקת יט, יז."]]],[2100990129,"<b>מירושלים</b> נקודת המל' חצים אל הים הקדמוני באימא וחצים אל הים האחרון ז\"ת דמל' הגם שמתחילה ג\"כ קיבלו השפע מכתר מל' אלא שעתה הי' תוספת הבירורים כו' ופי' נקודה פנימי' (פי' הפרד\"ס<sup data-n=\"3706\">20</sup> הוא שעי\"ד אימא בתוקף נעשה אור חוזר כתר חכמה מלמטלמ\"ע לכך נק' כתר מל' כו') פנימי' מלכו' על כלל הג\"ר כו').\n<b>ולהבין</b> בתוספ' ביאור הנ\"ל הנה מסגיאות דחלבא אוריק לפומא דאימא עפ\"י קבלת הפרד\"ס הוא שע\"י אימא בתוקפה נעשה חוזר כתר חכמה מלמטה למעלה ולכך נק' כתר אמנם זהו כשהאימא מאיר בתוקף עוז מסגיאות חלבא דוקא כשהאימא מרובה אז אריק באו\"ח אך טעם הדבר מפני מה יהי' או\"ח ע\"י האימא אינו נודע לנו שבפרד\"ס אינו מבואר כ\"כ רק ממשל המראה כלי ההבטה וכמ\"ש הראני<sup data-n=\"3707\">21</sup> את מראיך מראיך כו' והיא הלכתא בלא טעמא ועפ\"י קבלת האריז\"ל נגלה לנו מפני הבירורים<sup data-n=\"3708\">22</sup> דב\"ן שעולה בס\"ג ממטלמ\"ע כו' והנה חלב דאימא דם<sup data-n=\"3709\">23</sup> נעכר ונעשה חלב היא המגדיל המדות שהיא עפ\"י השכל ואמנם לא כל ההתבוננות מתגלית במדות רק הארה שההשגה שיעור קומה בפ\"ע כמ\"ש האם והחלב מדדים<sup data-n=\"3710\">24</sup> וכך דד במקום בינה אל דד כו' ופירוש גידול המדה שיש התכללות יו\"ד מיו\"ד עד אין קץ ויש יו\"ד מוא\"ו ויש וא\"ו בוא\"ו והוא תלוי בערך המשכות השכל וד\"ל וכשמתגלה הכוונה שהמדות מאירים בגילוי להיות החכ' בגילוי בחסד שמשפיל חכמה בחסדו ולמעלה הוא גילוי אלקות בג\"ע ולמטה תורה קבלה כו' משא\"כ חסד בלי חכמה שהוא בהעלם היא למעלה נהנין מזיו ולמטה הרחבת דירה נאה בני חי' ומזוני כו' ובחכמה עצמה יש כמה בחי' כמו חכמת התורה או תכונה ודקדוק לפי אופן גילוי החכמה בחסד וד\"ל. וסגיאו דחלבא לגידול הנ\"ל שנתברר ברורים וכו' וד\"ל.",[["3706","20","<b>(פי' הפרדס. . מל' כו')</b>: אולי כ\"ז נמחק."],["3707","21","<b>הראני את מראיך</b>: תשא לג, יח."],["3708","22","<b>הבירורים דב\"ן שעולה ס\"ג</b>: ראה לקו\"ת בחוקותי מז, ג. תו\"ח בראשית טז, ג ובהערה 36."],["3709","23","<b>דם נעכר ונעשה חלב</b>: נדה ט, א."],["3710","24","<b>מדדים. . במקום בינה</b>: ברכות י, א."]]],[2100990130,"<h3>ועתה יגדל נא כח</h3>\n<b>בעזר\"ה שבת פ' שלח לך</b>\n&lt;רמה&gt;\n\nועתה<sup data-n=\"3711\">1</sup> יגדל נא כח א\"ד כאשר דברת לאמר ה' ארך אפים רב חסד כו'<sup data-n=\"3712\">2</sup>. הנה אמרו ז\"ל ע\"פ היום<sup data-n=\"3713\">3</sup> לעשותם לא המדרש עיקר אלא המעשה וגדול תלמוד שמביא לידי מעשה, ובזוהר<sup data-n=\"3714\">4</sup> איתא דמצות<sup data-n=\"3715\">5</sup> אינון לבושין לנפש וכשחסר לו אפי' מצוה אחת חסרא לבושא חד כו' וע\"כ לפ\"ז צריך האדם לבא בגלגולי'<sup data-n=\"3716\">6</sup> רבים עד שיקיים כל התרי\"ג מצות וכמו גם אם אינו כהן או לוי צריך שיתגלגל ויתלבש אור נשמתו בגוף עוד להיות כהן ולברך ברכת כהנים או לאכול תרומות וכיוצא כי כמה מצות יש שתלוית בכהנים ולוים וכיוצא בזה יש כמה מצות שא\"א שיתקיימו בלתי שימצא בכמה גופים ע\"י כמה גלגולים רבים וכו'. ולכאורה כל זה אינו מובן למה צריכה הנשמה לבוש ומהו ענין הלבוש שנעשה ע\"י המצות וכו'.\n<b>אך</b> הנה נודע שירידת<sup data-n=\"3717\">7</sup> הנשמה היא צורך עלי', והענין הוא כי הנשמה<sup data-n=\"3718\">8</sup> האלקי' קודם בואה לעוה\"ז בהתלבשו' בחומר הגופני היתה בבחי' עומד וכמ\"ש אליהו חי<sup data-n=\"3719\">9</sup> ה' אשר עמדתי לפניו וענין עומד הוא אשר לא יעלה ולא יגרע ממדרגתו לעולם אלא עומד תמיד במדרגה א' וכמ\"ש ונתתי<sup data-n=\"3720\">10</sup> לך מהלכים בין העומדים האלה כו' ובירידתה בגוף בעוה\"ז הגיעה להיות בבחי' מהלך וכמ\"ש באברהם התהלך<sup data-n=\"3721\">11</sup> לפני כו' והטעם הוא לפי שב' מדרגות יש בעבודת ה' הא' בכל<sup data-n=\"3722\">12</sup> נפשך והוא כפי כח ההשגה שיש בנפש כך הוא התפעלות אוי\"ר וזהו בכל חד וחד לפום שיעורא דילי' שנמשך בו מכח האלקי להיו' בבחי' כלי מוגבל כפי המדה וע\"כ המלאכי'<sup data-n=\"3723\">13</sup> נק' עומדים שעומדים תמיד בעבודתם באוי\"ר במדרגה א' משא\"כ אוי\"ר שתתפעל הנפש בהיותה מלובשת בחומר גופני בעוה\"ז להיות כי החושך והצמצום מסתיר לה אזי",[["3711","1","<b>ועתה יגדל נא כח א\"ד</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (סה, א).\nמאמר זה באריכות מכ\"ק אדמו\"ר האמצעי נדפס במאמרי אדה\"א שלח ע' א'כט.\nמאמר זה עם הגהות וקיצורים נדפס באוה\"ת שלח ע' תעה, שם ע' 69 ואילך.\nהנחת המהרי\"ל נדפס בלקו\"ת שלח לח, ג."],["3712","2","<b>ועתה יגדל נא. . ה' ארך אפים. . כו'</b>: שלח יד, יז. יח."],["3713","3","<b>היום לעשותם. . תלמוד שמביא לידי מעשה</b>: ואתחנן ז, יא. ראה עירובין כב, א."],["3714","4","<b>ובזוהר איתא</b>: ראה לקו\"ת כאן: בזוהר הקדוש הפליא להגדיל בשבח המעשה דמצות אינון כו'."],["3715","5","<b>ובזוהר. . דמצות. . לבושין לנפש</b>: זח\"א רכד, א. ראה תניא פ\"ה. מע\"ח שער מ\"ד פ\"ג. וראה לקו\"ש ח\"כ ע' 315 הערה 5."],["3716","6","<b>בגלגולי' רבים</b>: ראה הל' ת\"ת לאדה\"ז פ\"א ה\"ד (ובהמ\"מ שם). ובכ\"מ."],["3717","7","<b>שירידת הנשמה היא צורך עלי'</b>: ראה לקו\"ת בלק עג, א. אוה\"ת ויקרא כרך ב ע' תרלה. וראה תניא פל\"ז (מח, ב). מאמרי אדה\"א ויקרא ח\"ב ע' תרסז. וש\"נ."],["3718","8","<b>הנשמה. . קודם. . בבחי' עומד</b>: ראה לקו\"ת בחוקותי מה, א. שלח לח, ד. ובהנסמן במאמרי אדה\"ז תקע\"א ע' ו. ע' י. תו\"ח בשלח [הוצאת קה\"ת — תשס\"ג] קסד, ב ואילך."],["3719","9","<b>חי הוי' אשר עמדתי לפניו</b>: מלכים א יז, א. לקו\"ת חקת סד, ד. סידור רסג, ב."],["3720","10","<b>ונתתי לך מהלכים</b>: זכרי' ג, ז. וראה תו\"א ל, א ואילך."],["3721","11","<b>התהלך לפני</b>: לך לך יז, א."],["3722","12","<b>בכל נפשך</b>: ואתחנן ו, ה."],["3723","13","<b>המלאכי' נק' עומדים</b>: ראה תו\"א וישב ל, סע\"א. לקו\"ת בחוקותי מה, א. ובכ\"מ."]]],[2100990131,"תתגבר בהתפעלות שלמעלה מן הכלי המוגבל שלה עד שאין כלי המגביל שלה מסתיר לה ותוכל לילך בעילוי המדרגו' בעילוי אחר עילוי בלי שיעור אחר שיצאתה מגדר גבול הכלי וזהו אהבת בכל מאדך<sup data-n=\"3724\">14</sup> שהוא בלתי מוגבל והיינו בחי' מהלך שהולך תמיד מחיל אל חיל בכל יום הולך ואור בעבודתו במדרגה יותר עליונ' עד בלי שיעור וכמ\"ש<sup data-n=\"3725\">15</sup> במ\"א ע\"פ אם בחוקותי תלכו כו' וד'\"ל.\n<b>אך</b> כיצד יבא האדם לבחי' בכל מאדך בק\"ש היינו שתיקנו שתים<sup data-n=\"3726\">16</sup> לפניה שהן לקיום ק\"ש ולצרכה כו' כי הנה בברכת יוצר אנו אומרים המאיר לארץ כו' ובטובו<sup data-n=\"3727\">17</sup> מחדש בכל יום כו' עד המלך המרומם לבדו כו' אלקי עולם ברחמיך הרבים רחם עלינו אדון עוזינו צור משגבינו מגן ישענו משגב בעדינו, ולכאורה אין לזה סדר וסמיכות כלל.\n<b>אך</b> הנה הענין הוא דפי' מחדש בכל יום כו' התחדשות זאת הוא ענין החידוש מאין ליש דוקא ופי' מאי\"ן ידוע לפי שאין התהוות הבריאה מהבורא כמו דוגמת כח הפועל בנפעל שמהותו של כח הפועל מלובש בנפעל אלא רק בחי' הארה דהארה והוא בחי' כח נבדל מאלקות הנמשך בפעולת הנבראי' עד שנק' הבורא בשם קדוש ומובדל מן הנבראי' וזהו המלך המרומם לבדו כו' פי' בחי' שם מלכות שמתפשטת עליהם בזאת בלבד המה מתהווי' ונבראי' אבל מהותו ועצמותו מרומם לבדו כמו שהיה קודם הבריאה &lt;רמו&gt;\nשהוא המתנשא מימות עולם כו' וד\"ל וזהו ענין החידוש מאין דלכאורה אינו מובן דהלא<sup data-n=\"3728\">18</sup> ממך הכל כתי' ואין כל חדש בזה אך האמת הוא דמבחי' אין ממש נבראו הכל כי אינו בבחי' כח הפועל בנפעל שא\"כ הוא מקבל בחי' שינויי' והתפעלות כי יש שינוי בין קודם הבריא' כו' וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> ענין הסדר והסמיכות ובטובו מחדש כו' עד שהוא מלך מרומם לבדו מאז כו' א\"כ אלקי עולם ברחמיך הרבים רחם עלינו, פי' אחר שאתה מרומם ומובדל לגמרי מאתנו א\"כ תגדל הרחמנות עלינו מפני עוצם הריחוק עד שגם אנחנו אין אנו משיגי' גודל הרחמנות אלא ברחמיך<sup data-n=\"3729\">19</sup> הרבים רחם עלינו כי לפי רוממות עצמותך לא ידוע לנו גודל הרחמנו' רק ברחמי\"ך ברחמי\"ך דוקא וכמ\"ש במ\"א וד\"ל.\n<b>אדון</b><sup data-n=\"3730\">20</sup> עוזינו כו', פי' מבחי' הרחמי' הרבים שלך תמשוך עלינו שיהי' אור אלקי חופף עלינו עכ\"פ בבחי' אור מקיף כי הגם שא\"א שיגיע לנו האור בבחי'",[["3724","14","<b>בכל מאדך. . בלתי מוגבל</b>: ואתחנן ו, ה. וראה תו\"א לט, ד."],["3725","15","<b>וכמ\"ש במ\"א ע\"פ אם בחוקתי תלכו</b>: ראה לעיל ע' תד ואילך. וראה לקו\"ת בחוקתי מה, א ואילך."],["3726","16","<b>שתים לפניה</b>: ראה ברכות פ\"א מ\"ד."],["3727","17","<b>ובטובו מחדש בכל יום</b>: ברכת יוצר."],["3728","18","<b>דהלא ממך הכל</b>: דברי הימים א כט, יד."],["3729","19","<b>ברחמיך הרבים. . לא ידוע לנו גודל הרחמנות. . וכמ\"ש במ\"א</b>: ראה לקו\"ת פינחס עח, ג. מסעי פח, ד. ראה לב, ג. דרושים לשבת שובה סה, א. תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] שמג, ב. תלו, א."],["3730","20","<b>אדון עוזינו. . אור מקיף</b>: ראה ג\"כ תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] עז, א. תלו, א."]]],[2100990132,"השגה בבחי' א\"פ להיות נקלט ונתפס ממש בתוך הנפש מטעם כי הוא מרומם לבדו כנ\"ל אבל מ\"מ יכול להיות שורה עלינו בבחי' אור מקיף עכ\"פ והוא כענין קבלת מלכות שמים שהיא באה על האדם בבחי' מקיף כמ\"ש שום<sup data-n=\"3731\">21</sup> תשים עליך מלך עלי\"ך בבחי' מקיף כו' וד\"ל, ונמשך ג' מקיפי' לנגד ג' מדרגו' נפש רוח נשמה והוא מ\"ש כאן ג' מקיפי' אדון עוזינו צור משגבינו מגן ישעינו משגב בעדינו והכל בבחי' מקיף כי אדון עוזינו הוא ענין קבלת מלכות שמים כידוע דשם<sup data-n=\"3732\">22</sup> אד' הוא בחי' מלכות דאצי' שמחי' הכל מאין ליש וכמ\"ש מלכותך<sup data-n=\"3733\">23</sup> מלכו' כ\"ע וכמאמר אנת<sup data-n=\"3734\">24</sup> אשתמודע אדון על כולא כו' והתפשטות החיות בא לנבראי' רק מבחי' הארה דהארה והוא בחי' שם מלכותו דהיינו בקבלת מ\"ש בלבד כמ\"ש שום תשים עליך מלך ונחלק לג' מקיפי' בג' עולמו' בי\"ע כמ\"ש לכבודי<sup data-n=\"3735\">25</sup> בראתיו יצרתיו אף עשיתיו והוא לנגד<sup data-n=\"3736\">26</sup> בחי' מחשבה דו\"מ שמלובש בג' עולמו' הללו ולכאו\"א יש בחי' מקיף מיוחד וזהו שאמר ג' מקיפי' צור משגבינו פי' צור הוא מחסה כמו צורי אחסה בו כו' וכן מגן ומשגב הכל מיני מקיפי' כמו הצור שחוסה בו האדם בצילו כו' וכמ\"כ לנגד נר\"ן שבאדם שיהא אור אלקי בבחי' מקיף לנפש מקיף בפרט ולרוח מקיף בפרט כו' ולכללו' נ\"י אנו או' אדון שהוא עוזינו וחיי הכל הוא צור משגבינו ומגן כו' כמו בג' מקיפי' דבי\"ע למעלה וד\"ל.\n<b>וזהו</b> והיתה<sup data-n=\"3737\">27</sup> נפש אדוני צרורה בצרור החיים פי' כמו הצרור שנתפס הדבר הנצרר בו מכל צדדיו כך הנר\"נ שבאדם נתפסי' מכל צד בבחי' ג' מקיפי' הנ\"ל וזהו שנק' צרור החיים להיות את ה' כו' וזהו ג\"כ וכבוד<sup data-n=\"3738\">28</sup> ה' יאספך פי' יאספך יקבץ ויאסף אור הנשמה להיו' מוקפת בתוך כבוד ה' מפני שהוא בחי' אור מקיף לנפש כנ\"ל ע\"כ נאספת ונקבצת הנשמ' ומוקפת בתוך תוכו של כבוד ה' כמו שאנו או' צור משגבינו מגן ישעינו כו' וד\"ל.\n<b>והנה</b> פסוק זה דכבוד ה' יאספך במעשה המצות נא' דכתיב והלך<sup data-n=\"3739\">29</sup> לפניך צדקך כו' עד וכבוד ה' יאספך. והענין הוא כי ע\"י המצות נעשי' בחי' מקיפי' לנפש כנ\"ל. כי הנה במעשה<sup data-n=\"3740\">30</sup> המצות<sup data-n=\"3741\">31</sup> יש ב' מדרגות הא' הנק' מצות המלך והב' מה שאמרו ז\"ל מצות<sup data-n=\"3742\">32</sup> צריכות כונה דוקא, פי' מצות המלך היינו &lt;רמז&gt;\nכמ\"ש שום תשים",[["3731","21","<b>שום תשים עליך מלך</b>: פ' שופטים יז, טו."],["3732","22","<b>דשם אד'. . מלכות דאצי'</b>: ראה זהר ויקרא יא א-ב. פרדס שם רפ\"א ופי\"ג. שער היחוד והאמונה פ\"ז."],["3733","23","<b>מלכותך מלכו' כ\"ע</b>: תהלים קמה, יג."],["3734","24","<b>אנת אשתמודע</b>: ת\"ז בהקדמה יז, רע\"ב."],["3735","25","<b>לכבודי בראתיו יצרתיו</b>: ישעי' מג, ז."],["3736","26","<b>לנגד בחי' מחשבה דו\"מ</b>: ראה לקו\"ת בלק סז, א ואילך. מאמרי אדה\"א במדבר ח\"א ס\"ע קצ ואילך. ובכ\"מ."],["3737","27","<b>והיתה נפש אדוני צרורה</b>: שמואל-א כה, כט."],["3738","28","<b>וכבוד ה' יאספך</b>: ישעי' נח, ח."],["3739","29","<b>והלך לפניך צדקך</b>: שם."],["3740","30","<b>במעשה המצות יש ב' מדריגות</b>: ראה ג\"כ אוה\"ת ויקרא כרך ג ע' תשצח."],["3741","31","<b>המצות. . מצות המלך</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ ה'ש\"ת ע' 48. ושם מציין: לב\"ב קנט, א: גזירת המלך. תוספתא נגעים פ\"ג ז: גזירת מלך היא. ועוד ע\"ש."],["3742","32","<b>מצות צריכות כוונה</b>: עירובין צה, סע\"ב (וש\"נ). וראה סידור רלה, ג. עטרת ראש נג, א. נט, א. שער האמונה בהקדמה ע' 8. שם פי\"ג. דרך חיים שער התפלה פמ\"ט. תו\"ח תצוה תצז, ב."]]],[2100990133,"עליך שהוא ענין קבלת<sup data-n=\"3743\">33</sup> מ\"ש שבכל מצוה שזהו למעלה מן ההשגה והטעם ומדרג' השנית הוא הכונה בבחי' רצון העליון אשר במעשה המצות והא בהא תליא דאם יש לו קבלת מ\"ש בתחלה רק לעשות רצונו בלא טעם אזי יוכל לבא למדרגה הב' בטעם וכונה כי הוא ית' מצד עצמו נק' מלך המרומם כו' וכדי שיומשך בבחי' רצון ע\"י כונה שבמצוה צריך תחלה קבלת מ\"ש כי א\"א לעורר בחי' המלך המרומם לבדו כו' כ\"א רק בקבלת מ\"ש בלבד שהוא בחי' ביטול העצמו' מכל וכל כו' וזהו שאנו או' בברכות המצות בא\"י אלקינו מלך העולם, פי' מלך העולם היינו קבלת מ\"ש הנק' מצות המלך וזהו בא דרך המשכה מלמעלה למטה באמרו ברוך אתה כו' וכמ\"ש שום תשים עליך בבחי' ירידת אור אלקי עליך כו' ואח\"כ אשר קדשנו במצוותיו מלמטה למעלה לעורר הכונה לבחי' רצון העליון שמלובש במצוה שע\"ז אמרו מצות צריכות כונה והיינו אשר קדשנ\"ו במצוותיו בחי' קדש הוא בחי' מובדל בערך ומרומם לבדו כמ\"ש בזוהר<sup data-n=\"3744\">34</sup> בפי' קדש שהוא מלה בגרמיה כלומר מובדל בפ\"ע להיות כי בחי' קדש העליון הוא בחי' אור מקיף דרצון העליון והוא ענין כונו' המצות באמרו אשר קדשנו במצוותיו וד\"ל.\n<b>וזהו</b> מ\"ש תחת<sup data-n=\"3745\">35</sup> אשר לא עבדת ה' אלקיד בשמחה ובטוב לבב מרוב כל, פי' רוב כל הוא בחי' חכמה עילא' שבתורה ואמנם שרש המצות גבוה גם מחכמה שבתורה וכמ\"ש והחכמה<sup data-n=\"3746\">36</sup> מאין תמצא פי' מאין הוא בחי' אור רצון העליון שנק' מקיף לחכמה כו' וזהו שאמר שהשמחה וטוב לב בעבודת המצות גבוה הרבה גם מבחי' רב כל וד\"ל. ובזה יובן מה שמצינו בגדולי הצדיקי' שלא זכו לכל השגו' רוה\"ק וגילוי אליהו רק בעבור שמחה של מצוה שהי' להם כמבואר<sup data-n=\"3747\">37</sup> בכתבי האריז\"ל שאמר כן ע\"ע שמפני שמחה של מצוה דוקא זכה לכל",[["3743","33","<b>קבלת מ\"ש שבכל מצוה</b>: ראה ברכות יד, סע\"ב."],["3744","34","<b>בזוהר בפי' קדש שהוא מלה בגרמיה</b>: ראה זוהר אמור צד, ב."],["3745","35","<b>תחת אשר לא עבדת. . מרוב כל</b>: תבא כח, מז."],["3746","36","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["3747","37","<b>כמבואר בכתבי האריז\"ל. . שמפני שמחה של מצוה</b>: ראה בהקדמת ס' חרדים (תנאי המצות, התנאי הרביעי. והובא גם בשל\"ה (דפוס אמ\"ד, נח\"ת) רלט, סע\"ב): וכן גילה הרה\"ח המקובל כהר\"ר יצחק אשכנזי זצ\"ל לאיש סודו שכל מה שהשיג שנפתחו לו שערי החכמה ורוח הקודש בשכר שהי' שמח בעשיית כל מצוה שמחה גדולה לאין תכלית כו'. והובא ג\"כ בשל\"ה מט, א: והעידו תלמידי האלקי הנ\"ל [האריז\"ל] שאמר מה שזכה לרוה\"ק כו'. ובהקדמת שער המצוות להאריז\"ל (ד\"ה גם דע): ויהי' שמח כו' ואם יתמיד בזה אין ספק שישרה עליו רוה\"ק כו'. וראה גם שער רוה\"ק (ת\"א תשכ\"ג ע' לג).\n[ומה שמציין במאמרי אדה\"א שלח ע' א'מח לס' ע\"ח — אולי הוא ע\"פ המבואר בס' שם הגדולים ערך ”ע\"ח\" דהוא שם הכולל גם לשאר כתבי האריז\"ל. ואכ\"מ].\nומובא ג\"כ בכ\"מ בדא\"ח: בסה\"מ תקס\"ב ח\"א ע' נא: ”כי ידוע בכתבי האריז\"ל ששאלוהו תלמידיו מהו עיקר הזכות שזכה לרוה\"ק ולגילוי אליהו כו' והשיב כו' עשה אותה בשמחה רבה ועצומה עד מאד\" (וכן הובא בד\"ה ויספו ענוים מכ\"ק אדאהאמ\"צ — כפ\"ח תשמ\"ה, בתחילתו. וע\"ש בהמ\"מ). סה\"מ תקס\"ג ע' שטו (הנחת הר\"מ בן אדה\"ז): ”כנזכר בשבחי האריז\"ל שלכך זכה להשיג כו'\". סה\"מ תקס\"ט ע' ער: ”וע\"כ איתא בכתבי האריז\"ל שעיקר הטעם שנתגלו לו רזין דאורייתא הוא מפני שהי' שמח שמחה של מצוה כו' לפי שהיא בחי' מקיף של הנשמה וגילוי המקיף הוא יותר גבוה מרוה\"ק כו'\". ס' מאמרי אדה\"ז עה\"ת ח\"א ע' שמח. שם כתובים ח\"ב ע' יו\"ד: ”שמצינו בר\"י לורי' שזכה לרוה\"ק וגילוי אליהו כו' וכידוע בכל צדיקים הנעלים שלא זכו לטעום טעם סודות התורה רק עי\"ז\". ובתו\"א תולדות כ, ב.\nומובא גם בתו\"ח שמות עט, ב. קפא, א. ריט, ב: ”כידוע במ\"ש האריז\"ל לתלמידו הרח\"ו שלא זכה לגילוי אליהו ורוה\"ק ולהשיג טעמי' וסודות כו'\". רלח, ב: ”כמ\"ש הרח\"ו על האריז\"ל כידוע\". שער האמונה ספמ\"א. שערי אורה נג, א. ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שעו. אוה\"ת בשלח ס\"ע שצו. נ\"ך ע' קמט: ”והאריז\"ל גילה להרח\"ו\" כו'. המשך מים רבים תרל\"ו ע' רג (ושם שע\"י שש\"מ זכה לגילוי הנשמה שלמעלה מגילוי אליהו). שם ח\"ב ע' תלח. המשך וככה תרל\"ז ע' צ (כנ\"ל מהמשך מים רבים). סה\"מ תרמ\"ז ע' קכז (כנ\"ל מהמשך מים רבים). סה\"מ תש\"י ס\"ע 235.\nובלקו\"ש ח\"ט ע' 525 ועד\"ז בלקו\"ש ח\"כ ע' 552 מציין ע\"ז: ”השייכות לרוה\"ק — ראה ירושלמי סוכה רפ\"ה, ונת' בלקו\"א להה\"מ ד\"ה וסוכה תהי' (בהוצאת קה\"ת — סרנ\"ט, סו, סע\"ג ואילך)\"."]]],[2100990134,"השגו' רזין כו' מפני ששמחה של מצוה מגיע בבחי' רצון העליון הנק' קדש העליון שהוא למעלה הרבה גם מן החכמה וד\"ל.\n<b>וזהו</b> שאמרו גדול<sup data-n=\"3748\">38</sup> תלמוד שמביא לידי מעשה ולכאורה א' בהיפך לא<sup data-n=\"3749\">39</sup> המדרש עיקר אך הענין הוא דשניהם אמת דבאמת המעשה עיקר מצד שרשה שהיא בחי' רצון העליון והוא בחי' מקיף העליון ולמטה ג\"כ בנפש האדם לא תוכל לבא בנפש בבחי' א\"פ אלא בבחי' מקיף והוא ענין הנז'<sup data-n=\"3750\">40</sup> בזוהר דהמצות נק' לבושי' כי המקיפי' שורין על הלבושי' כידוע ואי חסרא לי' לבושא חד כו' כנ\"ל אבל התורה<sup data-n=\"3751\">41</sup> תוכל לבא למטה בבחי' מזון לנפש בבחי' א\"פ וכמ\"ש ותורתך<sup data-n=\"3752\">42</sup> בתוך מעי כו' וכמ\"ש בפרע\"ח והטעם הוא לפי שנא' עוטה<sup data-n=\"3753\">43</sup> אור כשלמה שהתורה נק' אור וכמ\"ש ותורה<sup data-n=\"3754\">44</sup> או\"ר ובחי' אור דתורה הוא בחי' מעטה לבוש מפני שמלובש בה אור רצון העליון שיש בכללו' המצות דהנה ידוע דאוריי'<sup data-n=\"3755\">45</sup> מח\"ע נפק' והמצו' שרשם בבחי' רצון העליון והנה אנו רואי' שכל התורה היא רק פירוש המצות בלבד דהיינו איך שיהי' אופן מעשה המצוה כמו מצות סוכה יש ע\"ז מסכת סוכה ועל מצות ציצית פ' התכלת ועל מצות הקרבנות מס' זבחים ומס' מנחות וכיוצא בזה גם בתורה פנימי' בדרך הנסתר כמו טעמי המצות וסודיהן כו' וד\"ל ומאחר שכל אלה המה רק פירושי' לפרש מעשה המצות וא\"כ ה\"ז כמו בחי' הלבוש שילביש האדם א\"ע בו שהוא נכסה בו כך בחי' &lt;רמח&gt;\nרצון העליון שבמצות נכסה ונעלם הוא בפירוש שמפרש התורה עד שמכסה עליו כמו בחי' לבוש כו' וז\"ש עוטה אור כשלמה כו' וד\"ל ולהיות כן יכול להיו' אור דתורה בחי' מזון לנפש אחר שהיא בחי' הפירוש בהשגה וטעם אבל גופה של המצוה מצד שרשה בבחי' הרצון עצמו שלמעלה מן ההשגה וטעם א\"א לבא",[["3748","38","<b>גדול תלמוד</b>: קידושין מ, ב."],["3749","39","<b>לא המדרש עיקר</b>: אבות פ\"א מי\"ז."],["3750","40","<b>הנז' בזוהר דהמצות נק' לבושי'</b>: נסמן לעיל בתחלת המאמר."],["3751","41","<b>התורה. . מזון לנפש</b>: ראה זח\"ב רי, א."],["3752","42","<b>ותורתך בתוך מעי. . וכמ\"ש בפרע\"ח</b>: תהלים מ, ט. וראה זח\"ב סב, א."],["3753","43","<b>עוטה אור כשלמה</b>: תהלים קד, ב."],["3754","44","<b>ותורה אור</b>: משלי ו, כג."],["3755","45","<b>דאוריית' מח\"ע נפק'</b>: זהר בשלח דסב, א. יתרו פה, א. רעיא מהימנא משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."]]],[2100990135,"בנפש כ\"א בבחי' מקיפי' ולבושי' בלבד וזהו מ\"ש כבוד<sup data-n=\"3756\">46</sup> ה' יאספך שהוא בחי' לבוש ומקיף אצל מעשה המצות דוקא כמ\"ש והלך לפניך צדקך כו' משום דעיקר המקיפי' באי' ע\"י מעשה מצות והתורה אינו אלא בחי' פירוש והיינו שא' תלמוד גדול שמביא לידי מעשה וד\"ל.\n<b>וזהו</b> ועתה יגדל נא כח א\"ד כו'. דהנה שם א\"ד הוא בחי' מלכו' הנק' אדון עוזינו כמאמר אנת אשתמודע אדון על כולא כו' ומה שנק' בשם א\"ד דוקא הוא מפני שבשם זה מורה על היותו דן לכל העולם בדין ומשפט כי הוא אדון כל הארץ והוא השופט כל הארץ כו' להיותו בבחי' מלך עליהם ודינא<sup data-n=\"3757\">47</sup> דמלכותא דינא וזהו שם א\"ד<sup data-n=\"3758\">48</sup> שהוא דינא בהיפוך אתוון וגם בתיבת שם זה יש אותיו' דין מטעם שהוא בחי' מל' דוקא ודינא דמלכותא דינא כו' וד\"ל וזהו ע\"י ענין מצות המלך כמ\"ש שום תשים עליך מלך שבמעשה המצות אך זהו רק בחי' חיצוניו' בלבד אבל בחי' פנימי' שבשם זה הוא הנק' כח א\"ד כלומר בחי' הכח הפנימי שמלובש בהעלם בשם א\"ד והיינו שרש בחי' מעשה המצוה שהוא בחי' רצון העליון הנ\"ל שאינו אלא בהעלם בלבד במצות המלך ולכך נק' אדון עוזינו בבחי' מקיף כו' וההעלם הזה צריך לבא לידי גילוי ע\"כ אמר יגדל נא כח א\"ד כלומר שיומשך הכח הנעלם שבשם א\"ד ויבא לידי גילוי כו' וד\"ל.\n<b>וביאור</b> הדברי' יובן עד\"מ גשמי מן כח האדם כשזורק אבן בכחו דהנה מה שהאבן הנזרק מיד האדם הולך ונוסע באויר השמים ואינו נופל למטה כטבע הדומם שנופל למטה הוא מפני הכח הרוחני שנמשך מיד האדם אשר חונה סביב לאבן ומקיפו מכל צדדיו ומעכב נפילתו למטה וגם הוא הנושאו במרחק או בגובה שהרי כשיכלה הכח יפול האבן ולפי שיעור אותו הכח כך יהי' שיעור הליכת האבן למרחוק כידוע והנה הכח הזה שמלביש ומקיף לאבן בשעת ההליכה הרי הוא נבדל באותה שעה מכח האדם העצמית שלו והרי כשלא זרק האבן עדיין לא הי' כח זה במציאות נבדל בפ\"ע אלא היה כלול בהעלם בכללות הכח העצמי של האדם אך ע\"י הזריקה שזרק האבן יצא הכח הזה מבחי' ההעלם לידי גילוי להיות נבדל במציאות דבר בפ\"ע כו' והנמשל יובן למשכיל למעלה ג\"כ ע\"ד דוגמא כזאת, דהנה כל העולמות הם רק בבחי' דומם בלבד לגבי מקור המהווה אותם מאין כי הרי התהוותם הוא בבחי' עשייה כמ\"ש כולם<sup data-n=\"3759\">49</sup> בחכמה עשית וכל עשי' אינו אלא בבחי' דומם וכמ\"ש מקימי<sup data-n=\"3760\">50</sup> מעפר דל<sup data-n=\"3761\">51</sup> ופי' עפר זה היינו עולם הבריא' ובחי' דל הוא בחי' כח",[["3756","46","<b>כבוד ה'. . לבוש ומקיף. . המצות</b>: ראה ג\"כ תו\"א ויקהל פז, א. שלח מג, ד. תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] י, א. ובכ\"מ."],["3757","47","<b>ודינא דמלכותא דינא</b>: גיטין י, ב. ובכ\"מ."],["3758","48","<b>א\"ד. . אותיו' דין</b>: ראה זח\"ב קיח, א. זח\"ג יא, ב. וראה סה\"מ ה'ש\"ת ע' 133 בהערה."],["3759","49","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["3760","50","<b>מקימי מעפר דל</b>: תהלים קיג, ז. שמואל-א ב, ח."],["3761","51","<b>מקימי. . דל. . עולם הבריאה</b>: ראה גם ביאוה\"ז ויצא קלד, ד. אמרי בינה שער הק\"ש כז, א. וראה ביאוה\"ז (לכ\"ק אדמו\"ר הצ\"צ) ח\"א ע' רפח. אוה\"ת בראשית (כרך ג) תקכז, א. בלק ע' תתקכ."]]],[2100990136,"אלקי הנק' שכינה וכמ\"ש אשרי<sup data-n=\"3762\">52</sup> משכיל אל דל וכמ\"ש בזוהר וכן כתיב עפר<sup data-n=\"3763\">53</sup> אשר בקרקע המשכן והוא ג\"כ בחי' מלאכי' ונשמו'<sup data-n=\"3764\">54</sup> דעולם הבריאה שנק' בשם עפר אשר בקרקע המשכן כי המשכן הוא בחי' ממלא כ\"ע כו' וכמו שטבע הדומם ליפול למטה כך העולמו' הם באי' ונמשכי' בבחי' &lt;רמט&gt;\nפירוד וכמ\"ש ומשם<sup data-n=\"3765\">55</sup> יפרד כו' אך כח אלקי שמלובש בבחי' מל' הנק' שם א\"ד והוא אדון עוזינו הוא הנושאם ומגביהם למעלה דהיינו שיוכלו להעלות מ\"ן וליכלל באור ה' בבחי' ביטול כו' וצריך שיבא בהם תמיד בחי' כח אלקי זה הנושאם ומעלה אותם למעלה ושלא יפלו למטה והיינו מבחי' ההעלם לידי גילוי כי הכח הזה הי' ודאי תחלה כלול בהעלם עצמו' כח אור א\"ס אלא שיצא אח\"כ מן ההעלם לידי גילוי כפי משל הנ\"ל בזריקת האבן והיינו ע\"י בחי' רצון העליון שמלובש במעשה המצות שנק' כח א\"ד וכאשר בא מן ההעלם לידי גילוי הוא הכח הנושא ומעלה כל העולמות.\n<b>וזהו</b> ועתה יגדל נא כח א\"ד כו' שאמר משה בחטא מרגלים דוקא כי חטא מרגלים הי' חטא גדול וכבד מאד והי' גורם בכנ\"י נפילת המדרגה מאד כענין נפילת אבן למטה כי העונות מכבידין כמשא כבד וכמ\"ש כמשא<sup data-n=\"3766\">56</sup> כבד יכבדו כו' ע\"כ צריך היה משה להמשיך בחי' גילוי כח א\"ד ממקורא דכולא דהיינו בחי' קדש העליון הנ\"ל שהוא היותר עליון מכל המקיפי' פרטיים וכל שהוא כח יותר עליון יכול יותר להגביה את הנופל למטה עד גם שיפול למטה מטה שאין עוד למטה הימנו גם שם יוכל הכח העליון להגיע ולהעלותו משם בהיותו כח גדול מאד (וכמ\"ש<sup data-n=\"3767\">57</sup> במ\"א ע\"פ כי יפול לא יוטל דמטעם זה יש נשמו' גבוהו' בזמן הגלות שכדי לסמוך הנופל צריך לבא האור ממקום עליון ביותר כו') וזהו כבוד ה' יאספך פי' יאספ\"ך מנפילתך למטה כי נעשה בחי' א\"מ לסבבו מכל צד עד שלא יפול לעולם וכמ\"ש צרורה<sup data-n=\"3768\">58</sup> בצרור החיים כו' וכל זה ע\"י מצות המלך דוקא והוא פי' אדון עוזינו מקיף כללי שממנו נמשך ג' מקיפי' פרטיים צור משגבינו כנ\"ל וד\"ל.\n<b>כאשר</b> דברת לאמר ה' ארך אפים ורב חסד כו'. דהנה ידוע ההפרש בין דיבור לאמירה הדיבור<sup data-n=\"3769\">59</sup> הוא בקול רם והאמירה היא בחשאי בלב כי בחי' הדיבור הוא מבחי' עלמא דאתגליא כידוע והאמירה בלב ומחשבה בבחי' עלמא דאתכסיא והיינו בחי' העלם וגילוי כידוע דהמחשבה נק' העלם הדיבור. והנה בשעת מ\"ת כתיב וידבר<sup data-n=\"3770\">60</sup> אלקי' את כל הדברים האלה לאמר הרי לכאורה הזכיר ב' הפכי' במקום א'",[["3762","52","<b>אשרי משכיל אל דל. . בזוהר</b>: תהלים מא, ב. וראה ביאוה\"ז בלק קו, ד."],["3763","53","<b>עפר אשר בקרקע המשכן</b>: במדבר ה, יז."],["3764","54","<b>ונשמות. . בשם עפר</b>: ע' בזהר ח\"ג קכה, א. ובמק\"מ שם."],["3765","55","<b>ומשם יפרד</b>: בראשית ב, י."],["3766","56","<b>כמשא כבד יכבדו כו'</b>: תהלים לח, ה."],["3767","57","<b>וכמ\"ש במ\"א ע\"פ כי יפול לא יוטל</b>: תהלים לז, כד."],["3768","58","<b>צרורה בצרור החיים</b>: שמואל-א כה, כט."],["3769","59","<b>הדיבור הוא בקול רם. . עלמא דאתגליא</b>: ראה זח\"ג קלג, א."],["3770","60","<b>וידבר אלקים את כל הדברים האלה</b>: יתרו כ, א."]]],[2100990137,"דיבור ואמירה באמרו וידב\"ר לאמ\"ר ומה גם שאין זה כסדר כלל דהאמירה קדמה לדיבור כנ\"ל במחשבה שקודמת לדיבור וכאן אמר דיבור קודם לאמירה.\n<b>אך</b> הענין הוא דהאי לאמר הוא ענין האמירה שבאה אחר הדיבור דוקא והוא בחי' העלם שנעשה אחר בחי' הגילוי כי מבחי' גילוי שבעליון המשפיע נעשה בחי' העלם בתחתון המקבל ההשפעה עד\"מ תלמיד המקבל שפע חכמה מרבו הרי הוא מקבל השכל דרך כלי דיבור של הרב והרי מבחי' דיבור של הרב שהוא רק בחי' גילוי נעשה בחי' העלם המחשבה בתלמיד כששומע הדיבור כו' וכך יובן למשכיל למעלה בבחי' דיבור העליון שהוא י' הדברות שנק' דבר ה' הרי מבחי' דיבור זה שהוא רק בחי' גילוי למעלה נעשה ממנו בחי' העלם למטה והוא ענין לאמר שהוא בחי' אמירה שבמחשבה כו' והענין הוא כי הנה כתיב ויניחהו<sup data-n=\"3771\">61</sup> בג\"ע לעבדה ולשמרה כו' לעבדה ברמ\"ח מ\"ע ולשמרה בשס\"ה ל\"ת כידוע וכל זה &lt;רנ&gt;\nמדבר בג\"ע התחתון בלבד ולא בג\"ע העליון שהרי אדה\"ר היה בג\"ע התחתון שבארץ בלבד כידוע וזהו דוקא ממצות מעשיות אבל מלימוד התורה<sup data-n=\"3772\">62</sup> נעשה מזון לנפש בג\"ע העליון דוקא וכמ\"ש בספרי הקבלה, ולכאורה יפלא מאד דהלא מבואר למעלה דשרש המצות גבוה הרבה מחכמה שבתורה ואיך ע\"י המצו' אין התיקון רק בג\"ע התחתון.\n<b>אך</b> הענין הוא דקבלת שכר ישנו בכמה מדרגו' בעילוי אחר עילוי כמו בהנאו' הנשמו' בג\"ע דכתיב ילכו<sup data-n=\"3773\">63</sup> מחיל אל חיל כו' אך זהו<sup data-n=\"3774\">64</sup> הכלל שכל שהמדרגה יותר עליונה תוכל לימשך ולהאיר למטה מטה ביותר כו' וע\"כ גם בקבלת שכר בג\"ע וכיוצא כל שהאור יותר עליון מפני עוצם רוממותו יוכל לירד גם למטה מטה ולהאיר והיינו ענין ג\"ע התחתון שמטעם זה יש בו יתרון מעלה מבג\"ע העליון כי הנה המצו' שרשם באמת מאד נעלה גם מבחי' חכמה שבתורה וכנ\"ל וע\"כ היא הנותנת שיוכל קבלת שכרם לימשך גם בהגשמת המדרגה יותר והיינו גם בג\"ע התחתון עד שמצינו בשכר המצות שיוכלו לבא בהגשמת עוה\"ז השפל ביותר וכמו ששנינו אלו<sup data-n=\"3775\">65</sup> דברים שאדם אוכל פירותיהן בעוה\"ז כו' הרי יש מצות שאדם אוכל בשכרם בעוה\"ז בעניני ברכה גשמית ממש כמו הברכות שנאמרו בפ' אם<sup data-n=\"3776\">66</sup> בחוקותי תלכו כו' והשיג לכם דיש את בציר כו' ורדפתי את אויבכם כו' ואין מקרא יוצא מידי פשט הענין לעולם וגם הרי נא' בברכו' האלה והשיגו\"ך<sup data-n=\"3777\">67</sup> והשיגו\"ך ממש כי",[["3771","61","<b>ויניחהו בג\"ע לעבדה ולשמרה. . מ\"ע. . ל\"ת</b>: בראשית ב, טו. זח\"א כז א. זח\"ב קסה, ב. ובהנסמן בלקו\"ש ח\"כ ס\"ע 262."],["3772","62","<b>התורה. . מזון לנפש. . בספרי הקבלה</b>: ראה תניא ספ\"ה (ובמ\"מ והגהות והע\"ק שם)."],["3773","63","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["3774","64","<b>זהו הכלל</b>: ראה שערי אורה שער הפורים נח, א. סה, א. וראה תו\"ח בראשית כה, א. פא, ד. וראה מאמרי אדה\"א שמות ח\"ב ע' שמב ושם: הכלל הגדול בכ\"מ. ובכ\"מ."],["3775","65","<b>אלו דברים שאדם אוכל פירותיהן בעוה\"ז</b>: פאה א, א."],["3776","66","<b>אם בחוקותי תלכו. . והשיג לכם דיש. . ורדפתי</b>: בחוקתי כו, ג-ו."],["3777","67","<b>והשיגו\"ך</b>: תבוא כח, טו. מה."]]],[2100990138,"יוכלו לבא בירידו' המדרגו' כ\"כ עד שישיגום האדם באשר הוא שם גם בהגשמה היותר תחתונה והכל מטעם הנ\"ל לפי ששרש המצות גבוה מאד לכך יכולי' להאיר כ\"כ למטה מטה משא\"כ התורה שאינה גבוה כ\"כ כי אוריי' מחכמ' נפק' וחכמה עילא' אינו אלא בחי' לבוש לרצון העליון כנ\"ל בפי' עוטה אור כשלמה ע\"כ אין הארתה מתפשטת ונמשכת עד למטה בג\"ע התחתון אלא רק בג\"ע העליון בלבד כו' וד\"ל ואמנם הנה אין הארת המצות מתפשטת למטה כ\"כ אלא ע\"י אמצעו' התורה דוקא אחר שהיא מלבשת לרצון העליון כנ\"ל והיא פירוש הרצון כו' א\"כ א\"א להיות גילוי הרצון מן ההעלם אלא ע\"י הדיבור בתורה דוקא והרי מבחי' דיבור<sup data-n=\"3778\">68</sup> בד\"ת נעשה בחי' העלם למטה כי ע\"י הדיבור בד\"ת כמ\"ש ואשים<sup data-n=\"3779\">69</sup> דברי בפיך נמשך גילוי הרצון העליון שמלובש במצות ויורד ומאיר עד למטה בג\"ע התחתון לנשמות וגם לנשמו' שמלובשי' בגופי' להיו' אוכלי' פירותיהן גם בעוה\"ז בענינים גשמיים כנ\"ל.\n<b>וזהו</b> כאשר דברת לאמר שמבחי' הדיבור בגילוי נעשה בחי' אמירה בהעלם למטה דהיינו שהוא מקור בחי' גילוי אור אלקי עד למטה מטה והוא ממעשה המצות וכל זה ע\"י שיגדל כח א\"ד בתחלה דהיינו בחי' כח הפנימי המלובש במקיפי' והוא בחי' רצון העליון שהוא שרש כל המצות בבחי' מקיף כנ\"ל ואזי ממילא יהי' נמשך אח\"כ מהדיבור אמירה מגילוי העלם למטה אך מתחלה צ\"ל מן ההעלם גילוי למעלה ואח\"כ יומשך מבחי' הגילוי שבעליון בחי' העלם למטה והיינו ועתה יגדל נא כח א\"ד בתחלה ואח\"כ כאשר דברת לאמר וד\"ל.\n&lt;רנא&gt;\n<b>ה'</b> ארך אפים ורב חסד כו' נושא עון ופשע כו'. הנה פי' אפים הוא בחי' הפנים ששם הוא בחי' עיקר הגילוי של ההשפעה כמ\"ש באור<sup data-n=\"3780\">70</sup> פני מלך חיים וכן כתיב יאר<sup data-n=\"3781\">71</sup> ה' פניו כו' וכנראה בחוש הטבע שבפנים של אדם שם הוא ניכר כל קירוב ואהבה וחיבה יתירה והגם שיש לו בלב ומוח כבר עיקר הגילוי הוא ניכר בהארת הפנים דוקא כידוע וע\"כ נק' פנים<sup data-n=\"3782\">72</sup> מלשון פונה וגם מלשון פנימית והכל ענין א' וכמ\"ש במ\"א משא\"כ בחי' אחוריי' הוא היפך ענין הקירוב אלא כמאן<sup data-n=\"3783\">73</sup> דשדי בתר כתפוהי כמ\"ש בזוהר ומפני שע\"י המצות נמשך גילוי הארת הפנים גם עד למטה למטה כמו להיות אוכלין פירותיהן בעוה\"ז כנ\"ל ע\"כ נק' הארה זו בשם ארך אפים כלומר בחי' פנים ארוכים כ\"כ עד שמגיעי' להאיר למטה מטה כ\"כ כו' וכנ\"ל בפי' והשיגוך שמשיגי' גם בהגשמת הברכה במדרגה היותר תחתונה ולהיו' כי זהו מצד עוצם הרוממו' דוקא ע\"כ מדה זו דארך אפים היא נקראת מדו' הרחמים<sup data-n=\"3784\">74</sup> כי הרחמי'",[["3778","68","<b>דיבור בד\"ת</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב ה\"ב."],["3779","69","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["3780","70","<b>באור פני מלך חיים</b>: משלי טז, טו."],["3781","71","<b>יאר ה' פניו</b>: נשא ו, כה."],["3782","72","<b>פנים מלשון פונה וגם מלשון פנימית. . וכמ\"ש במ\"א</b>: ראה לקו\"ת שלח מא, ד, ומציין שם: וע' בזהר אמור צ\"ג ב' ע\"פ בקשו פני."],["3783","73","<b>כמאן דשדי בתר כתפוהי</b>: ראה תניא פכ\"ב."],["3784","74","<b>הרחמים. . הרוממו'. . וכמ\"ש במ\"א</b>: ראה לקו\"ת עקב יג, ד. וראה ס' מאמרי אדה\"א דברים ח\"א ע' שיב ואילך."]]],[2100990139,"נמשכי' מצד הרוממו' דוקא וכמ\"ש במ\"א וכן מדת ורב חסד ענינו הוא שזהו עיקר ריבוי החסד דוקא במה שהוא יורד כ\"כ ומתלבש עד למטה מטה להיו' חסד וברכה גשמי' כו' וכנ\"ל וד\"ל וכן ענין ונושא עון שאפי' העון שעל ידו הוא פגום כבר מפגימת יניקו' החיצונים הרחוקי' בתכלית כו' מ\"מ הוא נושא עון להגביה ולהעלותו למעלה וכמארז\"ל שאפי' זדונו'<sup data-n=\"3785\">75</sup> נעשו כזכיות ממש כו' והיינו ועובר על פשע שמפשע נעשה שפע דמאחר שזדונו' נעשו כזכיו' הרי מן הפשע<sup data-n=\"3786\">76</sup> נעשה שפע כו' וכמ\"ש בזוהר וד\"ל.\n<b>ובכל</b> זה יובן מ\"ש וחטאך<sup data-n=\"3787\">77</sup> בצדקה פרוק וגם בדברי רז\"ל אנו מוצאים שהתורה<sup data-n=\"3788\">78</sup> ג\"כ מכפרת מדכתי' בחסד<sup data-n=\"3789\">79</sup> ואמת יכופר עון ואין<sup data-n=\"3790\">80</sup> אמת אלא תורה כו' ולכאורה אינו מובן דמה ענין צדקה ותורה לחטא שחטאה הנפש עד שיועילו לה לכפר שהרי היא כבר נפגמה בחטאה כו' אך הענין הוא דהצדקה<sup data-n=\"3791\">81</sup> היא כללו' המצו' כולן כמ\"ש בכמה דוכתי במקרא וכן התורה היא בחי' כלי להביא בחי' העלם הרצון העליון לידי גילוי ומן בחי' הגילוי נעשה העלם למטה והיינו מה שנמשכי' י\"ג מדו' הרחמי' ארך אפים ורב חסד כו' גם למטה מטה כנ\"ל שאז נושא גם עון ועובר על פשע כו' וע\"כ בצדקה הוא עיקר הכפרה על החטא ובתורה הוא שבא לידי גילוי בלבד והיינו בחסד ואמת בשניהם יחד וכמ\"ש למעלה בפי' ועתה יגדל נא כח א\"ד כאשר דברת לאמר כנ\"ל וכמשל הנ\"ל בזריקת האבן שהכח העליון מגביהו שלא יפול כו' והיינו לאהפכא<sup data-n=\"3792\">82</sup> גם חשוכא לנהורא ולהיו' גם הזדונו' כזכיו' דהיינו להיו' עובר על פשע מפשע יהא שפע כו' וד\"ל.\n<b>ומה</b> שאמר ועתה יגדל נא כו' ועת\"ה דוקא. הענין הוא לפי שנא' היום<sup data-n=\"3793\">83</sup> לעשותם וארז\"ל היום דוקא לעשותם ולמחר לקבל שכרם בלבד כי שכר<sup data-n=\"3794\">84</sup> מצוה בהאי עלמא ליכא כו' והנה בענין התשובה ג\"כ אמרו דאין התשובה מועלת אלא היום בהיות הנשמה בגוף בעוה\"ז וכמארז\"ל אין<sup data-n=\"3795\">85</sup> ועתה אלא תשובה וע\"כ אמרו יפה<sup data-n=\"3796\">86</sup> שעה א' בתשובה ומע\"ט בעוה\"ז דוקא כו' והכל מטעם אחד כי הנה התשובה הוא לאהפכא חשוכא לנהורא ומרירו למיתקא &lt;רנב&gt;\nכו' שזה א\"א להיו' עפ\"י סדרי",[["3785","75","<b>זדונו' נעשו כזכיות</b>: ראה יומא פו, ב."],["3786","76","<b>הפשע נעשה שפע. . בזוהר</b>: ראה זהר במדבר קלג, א. ועוד."],["3787","77","<b>וחטאך בצדקה פרוק</b>: דניאל ד, כד."],["3788","78","<b>שהתורה ג\"כ מכפרת</b>: ראה ירושלמי ר\"ה ד, ח."],["3789","79","<b>בחסד ואמת יכופר עון</b>: משלי טז, ו. וראה אגה\"ת פ\"ט."],["3790","80","<b>ואין אמת אלא תורה</b>: ירושלמי ר\"ה פ\"ג ה\"ח. איכ\"ר פתיחתא ב. ילקוט שמעוני עה\"פ דניאל ח, יב (רמז תתרסו). ת\"ז תכ\"א (נ, א)."],["3791","81","<b>דהצדקה היא כללות המצות</b>: ראה תניא פל\"ז (מח, ב). לקו\"ת שה\"ש טז, ג. לח, א. תו\"א מב, ג."],["3792","82","<b>לאהפכא. . חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["3793","83","<b>היום לעשותם. . ולמחר לקבל שכרם</b>: ואתחנן ז, יא. עירובין כ, א."],["3794","84","<b>שכר מצוה בהאי עלמא ליכא</b>: קידושין לט, ב. וראה אגה\"ק ס\"ג. לקו\"ת בהעלותך לד, א."],["3795","85","<b>אין ועתה אלא תשובה</b>: ראה במדב\"ר פי\"ג, ג. וראה תורת שמואל תרל\"ב ח\"ב ע' תרד. תרל\"ג ח\"ב ע' תקעא."],["3796","86","<b>יפה שעה א' בתשובה</b>: אבות פ\"ד מי\"ז."]]],[2100990140,"ההשתלשלו' דעה\"ד טו\"ר ג\"כ נמשך ובא בהשתלשלו' אלא צריך להיות ההארה להתהפכו' זאת ממקום ומדרגה הגבוה מכל ההשתלשלו' והוא מבחי' מקור כל המקיפי' וז\"ש אשר<sup data-n=\"3797\">87</sup> אנכי מצוך היום על התשובה כי אנכי<sup data-n=\"3798\">88</sup> מי שאנכי הוא בחי' מקיף העליון שורה בזמן ירידת הנשמה בגוף דהיינו בעוה\"ז דוקא ולא בעוה\"ב והיינו לפי שנעוץ<sup data-n=\"3799\">89</sup> תחלתן בסופן דוקא וכמ\"ש במ\"א משא\"כ לע\"ל ביום<sup data-n=\"3800\">90</sup> שכולו שבת שיהי' מנוחה לחיי העולמים דהיינו כמו שהי' קודם שנברא ונאצל כו' שהי' הוא<sup data-n=\"3801\">91</sup> ושמו בלבד ואין ההעלם בא לידי גילוי ואיך יהופך על ידו מרע לטוב כו' ולכך אין ועתה אלא תשובה להיותה עתה דוקא, וגם כאן במעשה המצות להיות השראת כח א\"ד למטה להגביה ולהעלו' גם בחי' הדומם שלא יפול הנופל כנ\"ל אמר ועתה דוקא יגדל נא כח א\"ד כו' כי היום דוקא לעשותם כו'. ומטעם הנ\"ל שהיום דוקא בא בחי' ההעלם לידי גילוי ולא לע\"ל שיהי' מנוחה לחיי כל העולמי' כנ\"ל ע\"כ אין העת להגדלת בחי' כח א\"ד אלא עתה דוקא כל שיתא<sup data-n=\"3802\">92</sup> אלפי שני דהוי עלמא ולא באלף השביעי וזהו ועת\"ה יגדל נא כח א\"ד כו' וד\"ל.",[["3797","87","<b>אשר אנכי מצוך היום</b>: ואתחנן ו, ו."],["3798","88","<b>אנכי מי שאנכי</b>: ראה זח\"א קסז, ב. זח\"ג יא, א. לקו\"ת להאריז\"ל תולדות כז, יט. אבן עזרא שם. לקו\"ת פינחס פ, ב. ראה לא, ד."],["3799","89","<b>שנעוץ תחלתן בסופן</b>: ס\"י פ\"א מ\"ז."],["3800","90","<b>ביום שכולו שבת</b>: תמיד בסופה."],["3801","91","<b>הוא ושמו בלבד</b>: ראה פדר\"א פ\"ג. וראה סה\"מ תרנ\"א ס\"ט."],["3802","92","<b>שיתא אלפי שני דהוי עלמא</b>: ראה ר\"ה לא, א."]]],[2100990141,"<h3>להבין שרשי הדברים</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b><sup data-n=\"3803\">1</sup> שרשי הדברים הנ\"ל. הנה שרש ענין ירידת<sup data-n=\"3804\">2</sup> הנשמה בעוה\"ז להיות בבחי' מהלך ע\"י אהבת בכל מאדך כנ\"ל מובן עפ\"י<sup data-n=\"3805\">3</sup> המבואר במ\"א בטעם שעיקר התשובה בעוה\"ז דוקא וכמ\"ש היום<sup data-n=\"3806\">4</sup> היום דוקא ואין בעוה\"ב בחי' תשובה אלא כאשר הוא כן יקום כו' שהוא מפני שבחי' ממלא כ\"ע בכלל הוא בא בסדר השתלשלו' בבחי' אורו' וכלים באבי\"ע הכל במדה וקצבה עפ\"י מאמר<sup data-n=\"3807\">5</sup> קו המדה הידוע וכל עולם ועולם מד' עולמו' דאבי\"ע מקבל במדה כמו שהוא לא ישונה באיזה",[["3803","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (סו, ב).\nנוסח אחר (הנחת המהרי\"ל) נדפס (בתוס' הגהות מכ\"ק אדמו\"ר הצ\"צ) בלקו\"ת שלח לט, ג."],["3804","2","<b>ירידת הנשמה. . מהלך</b>: ראה תו\"א ס\"פ וישב (ל, סע\"א ואילך). מאמרי אדה\"ז תקע\"א ע' ו, וש\"נ. שם ע' יג ואילך. תקס\"ה ח\"ב ע' תשפא. מאמרי אדה\"א ויקרא ח\"ב ע' תרסז, וש\"נ. ובכ\"מ."],["3805","3","<b>עפ\"י המבואר במ\"א</b>: ראה לקו\"ת ואתחנן ו, א. ועוד."],["3806","4","<b>היום היום דוקא</b>: ואתחנן ז, יא. עירובין כב, א."],["3807","5","<b>מאמר קו המדה</b>: ראה זהר בראשית טו, א. יח, ב. וראה תו\"ח בראשית טו, ב. פג, ד. פז, א. ובכ\"מ."]]],[2100990142,"תוס' או איזה גרעון כו' וע\"כ כל בחי' הנמצאי' בכלל שבאבי\"ע כולם נקראי' בשם עומדים כי הם עומדי' תמיד במדרגה א' בלי שינוי בתוס' או בגרעון אור וכמ\"ש אליהו חי<sup data-n=\"3808\">6</sup> ה' אשר עמדתי לפניו כו' וכנ\"ל והיינו כמו בחי' אהבת בכל נפשך למטה שההתפעלות אהבה נמשכת במדה לפי ערך ההשגה כו' כך כל הנשמו' ומלאכים ואורות עליונים שבאבי\"ע אין בהן בחי' שינוי כלל משא\"כ בעוה\"ז שבחי' סובב כ\"ע בכלל מאיר בבחי' ממלא וכמ\"ש אשר<sup data-n=\"3809\">7</sup> אנכי מצוך היום אנכי<sup data-n=\"3810\">8</sup> מי שאנכי כו' שהוא הנק' המתנשא מימות עולם וכמ\"ש ומתחת זרועות עולם כו' מפני ששם<sup data-n=\"3811\">9</sup> מ\"ה מברר ב\"ן בדרך כלל ע\"כ יכול להיו' אהבת בכל מאדך שנק' עי\"ז מהלך כנ\"ל דוקא בעוה\"ז.\n<b>וזהו</b> שאמרו יפה<sup data-n=\"3812\">10</sup> שעה א' בתשובה ומע\"ט בעוה\"ז דוקא &lt;רנג&gt;\nולא בעוה\"ב לפי שאין התשובה מועיל בעוה\"ב מטעם הנ\"ל אבל בעוה\"ז מפני בחי' הארת סובב כ\"ע יכול להיות בחי' אהבה שלמעלה מן הכלי והמדה והיינו ג\"כ הטעם שיכול להיו' התשובה שהוא לאהפכא חשוכא לנהורא ומרירו למיתקא היפך סדרי ההשתלשלו' כו' וזהו שאמר ועתה יגדל כו' ועתה דוקא כי אין<sup data-n=\"3813\">11</sup> ועתה אלא לשון תשובה כמ\"ש למעלה וזהו ג\"כ שרש ענין היום לעשותם היום דוקא וכמאמרם תשובה ומע\"ט בעוה\"ז דוקא וכיון שמת<sup data-n=\"3814\">12</sup> אדם נעשה חפשי מן המצות ג\"כ כידוע כי בחי' שרש המצות הוא להמשיך בחי' מקיפי' דוקא כמשי\"ת וזה אינו אלא בעוה\"ז דוקא מטעם הנ\"ל וד\"ל.\n<b>והנה</b> ביאור שרש ענין ג' מקיפים הנ\"ל בפי' צור משגבינו מגן ומשגב שהוא דוקא ע\"י המצות בקבלת מ\"ש כי<sup data-n=\"3815\">13</sup> הוא המלך המרומם לבדו כו' וכנ\"ל תחלה יש להקדים ע\"ד הפשוט איך שמקיפים הללו באי' בעבודת ה' דהנה אהבת בכל מאדך שלמעלה מן הכלי אינה באה רק מהתבוננו' דסובב כ\"ע איך שהוא מלך מרומם ומתנשא מימות עולם כו' ולעוצם גודל ריחוקו מרוממו' זו תפול השפלו' בלב האדם ויעורר ע\"ע רחמי'<sup data-n=\"3816\">14</sup> רבים על מה שהוא רחוק כ\"כ ולפי ערך הרוממו' כך ערך השפלו' כידוע ומזה נמשך בחי' א\"מ על נפשו וכמ\"ש וכבוד<sup data-n=\"3817\">15</sup> ה' יאספך דהיינו אחר שמצד השפלות והריחוק לא יוכל אור אלקי לגלות בו בבחי' א\"פ יבא עליו בבחי' א\"מ והא\"מ הוא מ\"ש ברחמיך הרבים ברחמיך דוקא מפני שידוע לפניו גודל השפלו' וכנ\"ל והמשכת הרחמי' הרבים הוא ענין המשכת המקיף כידוע וד\"ל.",[["3808","6","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-א יז, א."],["3809","7","<b>אשר אנכי מצוך היום</b>: ואתחנן ו, ו."],["3810","8","<b>אנכי מי שאנכי</b>: ראה זח\"א קסז, ב. לקו\"ת להאריז\"ל תולדות כז, יט. וראה תניא מהדו\"ק ספמ\"ט. לעיל בהמאמר הערה 88."],["3811","9","<b>ששם מ\"ה מברר ב\"ן</b>: ראה ע\"ח שער (ה) טנת\"א פ\"א."],["3812","10","<b>יפה שעה א' בתשובה</b>: אבות פ\"ד, מי\"ז."],["3813","11","<b>אין ועתה אלא לשון תשובה</b>: נסמן לעיל ע' תקכב."],["3814","12","<b>שמת אדם. . חפשי מן המצות</b>: ראה תהלים פח, ו. שבת ל, א."],["3815","13","<b>כי הוא המלך המרומם לבדו</b>: ברכות יוצר."],["3816","14","<b>רחמי'. . הרוממות. . השפלות</b>: נסמן לעיל ע' תקכא."],["3817","15","<b>וכבוד ה' יאספך</b>: ישעי' נח, ח."]]],[2100990143,"<b>וע\"ד</b> דוגמא זאת יובן למשכיל למעלה בבחי' מלכו' דאצי' איך שנמשך ממנה ג\"כ ג' מקיפי' הללו בבי\"ע דהנה ידוע דבחי' מל'<sup data-n=\"3818\">16</sup> דאצי' נעשה בחי' עתיק לבריא' וכמ\"כ מבחי' מל' דבריא' נעש' עתיק ליצי' וכן מיצי' לעשי' ונמצא ג' כתרים הללו בג' עולמו' בי\"ע כולם נמשכו מבחי' מל' דאצי' שנק' אדון עוזינו שהוא שם אד' כמ\"ש למעלה, ועד\"ז יובן ג\"כ בעולם האצי' כי הנה יש בחי' בי\"ע באצי' ג\"כ כידוע שבחי' נהי\"ם דאצי' נק' בחי' עשי' שבאצי' ובחי' חג\"ת בחי' יצירה שבאצי' ובחי' חב\"ד שהן או\"א<sup data-n=\"3819\">17</sup> תרין ריעי' כו' בחי' בריא' שבאצי' ובחי' אצי' שבאצי' הוא בחי' כתר דאצי' שהוא בחי' עתיק' בכלל והוא הנק' המלך המרומם כו' מתנשא מימות עולם כי בחי' ז\"ת דע\"י שמלובשי' באו\"א וזו\"נ נק' ימות עולם אבל ג\"ר שבע\"י מובדל ומרומם מהתלבשו' זאת ולכך נקרא עתיק יומין כלומר שנעתק ונבדל מבחי' יומין כו' מלשון המעתיק<sup data-n=\"3820\">18</sup> הרים וכידוע והוא פי' בחי' כתר<sup data-n=\"3821\">19</sup> מלשון כותרת כי הוא רק מקיף מבחוץ לכל ההשתלשלו' דבחי' יומין שמלובשים באבי\"ע כו' וד\"ל ועד\"ז גם בחי' ג' מקיפי' דבי\"ע כמו מל' דאצי' שנעשה בחי' עתיק לבריא' ג\"כ נק' מובדל מהתלבשו' היומין שהם המדו' דכתר שמלובשי' באו\"א דבריא' כו' ועד\"ז עתיק דיצי' ודעשי' כו' וכמאמר לאו<sup data-n=\"3822\">20</sup> דאית לך צדק ידיעא כו' עד ולאו מכל אינון מדות כלל ומבחי' ג' מקיפי' הללו נמשך בג' עולמות ע\"ד דוגמא בג' מקיפים דנר\"נ שבנפש ע\"י התבוננו' בחי' סובב שנמשך בחי' רחמים רבים כנ\"ל וזהו פי' אדון עוזינו שהוא בחי' מקור כל המקיפי' בין באצי' בין בבי\"ע להיו' ממנו צור ומחסה בג' מדרגו' דבי\"ע שיש בכל עולם וד\"ל.\n&lt;רנד&gt;\n<b>ועתה</b> יש להבין איך נמשך ג' מקיפי' הללו ע\"י המצות דוקא. ותחלה יש להבין שרש ענין המצות. דהנה שרש ענין המצות הן בחי' מקיפי' שבכתר ונחלקי' ג\"כ לג' מקיפי' בג' מדרגו' דמחשבה דו\"מ שהן נר\"ן שבבי\"ע וכנ\"ל דכמו דמבחי' מל' דאצי' נעשי' בחי' עתיק בג' עולמו' כנ\"ל כך מבחי' מל' דא\"ס שנעשה בחי' עתיק לאצי' נחלק גם הוא לג' מקיפי' בבחי' ג' מדרגו' דנר\"נ דאצי' כו' ומשם שרש המצות שהרי נקראי' תר\"ך<sup data-n=\"3823\">21</sup> עמודי אור תרי''ג דאוריי' וז' דרבנן שהוא בחי' כתר בכלל כידוע.\n<b>וביאור</b> הדברי' הנה במצות יש ב' עניני' א' שעושה המצוה בכונה והוא שיודע טעמה וסודה למעלה באורו' היחודי' שנעשה על ידה למעלה ומכוין בעשייתה להמשיך אורו' עליוני' ולייחד יחודי' כמו במצות תקיעת<sup data-n=\"3824\">22</sup> שופר לכוין",[["3818","16","<b>מל' דאצי'. . עתי' לבריאה</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ב. וראה תו\"א מקץ מט, ב."],["3819","17","<b>או\"א תרין ריעי'</b>: ראה זח\"א ד, א. קכ, א. צב, ב. ובכ\"מ."],["3820","18","<b>המעתיק הרים</b>: איוב ט, ה."],["3821","19","<b>כתר מלשון כותרת</b>: ע\"ח שער או\"א (שי\"ג) פ\"ג. שער מוחין דצלם (שכ\"ג) פ\"ב. ובכ\"מ. לקו\"ת במדבר סט, א."],["3822","20","<b>לאו דאית לך צדק ידיעא</b>: ת\"ז בהקדמה (פתח אליהו)."],["3823","21","<b>תר\"ך עמודי אור. . תרי\"ג דאורייתא וז' דרבנן</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א."],["3824","22","<b>תקיעת שופר. . הארת עתיק בבינה</b>: ראה פע\"ח שער השופר פ\"א-ב. זח\"ג קעח, ב. וראה לקו\"ת דרושים לר\"ה נז, א-ב."]]],[2100990144,"בבחי' הארת עתיק בבינה ובמצות<sup data-n=\"3825\">23</sup> תפילין לכוין בהמשכו' מוחי' לז\"א וכן כיוצא בכל אלה יש פרטי כוונו' בכל מצוה ומצוה שע\"ז א' מצות<sup data-n=\"3826\">24</sup> צריכו' כוונה הנה כונות הללו אינן נק' עבודה וכתיב תחת<sup data-n=\"3827\">25</sup> אשר לא עבדת וכן לעבדו<sup data-n=\"3828\">26</sup> בכל לבבכם כו' אחר שבעשייתו מתקן דבר מה כמו שמייחד יחודי' וכונתו שיהי' בזה לאיזה תועלת דבר למעלה א\"כ ה\"ז כמו שעוסק בצרכי מו\"מ שלו שאין העסק נק' עבודה אצלו אחר שהוא לו לתועלת וכמו שיעסוק ברפואה מפני שהרפואה תועלת אין העסק בה נק' עבודה ומלאכה כלל כידוע.\n<b>אבל</b> מדרגה הב' בעסק המצות הוא שעושה א\"ע כאילו אינו יודע כלל טעמה וסודה ושיהי' במעשה שלה איזה תועלת יחודי' עליוני' וכיוצא ואינו עושה ומתקן דבר כלל אלא שעושה המצוה מפני שכך גזר ה' וצריך לעשו' רצונו בלבד יהי' דבר המעשה איך שיהי' צריך לקיים ואינו משגיח כלל בגוף המעשה כי כמו עד\"מ<sup data-n=\"3829\">27</sup> אם יגזור המלך לחטוב עצים וכיוצא אע\"פ שבודאי אין במעשה זו תועלת כלל לא למלך ולא לעצמו מ\"מ יעסוק באהבה כי גזרת מלך היא וכיוצא בזה ואז יהי' שוין בעיניו כל המצות קלה כחמורה אחר שאינו מכוין לכונו' שבהן אלא לכללו' ענינם שהן רק גזרת מלך וזהו הטעם שנק' כללו' המצות<sup data-n=\"3830\">28</sup> בשם מצות המלך כי הם רק גזרת מלך בכלל והוא ענין קבלת מ\"ש בכלל שישנה בכל המצות כולן וכל מצוה שחסר בה קבלת מ\"ש זאת גם שיכוין בה באמת לתכלית כונה שיש בה לא עשה כלום כמבואר למעיין בכתבי האריז\"ל, ושרש הדברים להיות כי בחי' שרש המצו' הן בבחי' פנימי' הרצון שהוא בחי' פנימי' הכתר ונעשי' בחי' אור מקיף למטה וכמ\"ש אשר קדשנו במצוותיו כו' אך א\"א להיות בחי' המשכת מקיפי' למטה בנר\"נ בלתי שיומשך תחלה מקיף הכללי שהוא בחי' הכתר מבחי' מלכו' שבעליון והיינו מבחי' מל' דא\"ס שנעשה בחי' כת\"ר לאצי' כנ\"ל ובחי' מל' דא\"ס היינו ענין קבלת מ\"ש שיש בכל מצוה שמקיים גזרת המלך בלבד כנ\"ל, ואח\"כ יוכל לימשך למטה בחי' מקיפי' דכתר עליון באבי\"ע שמשם שרש המצות ויאירו על האדם ג\"כ למטה בנר\"נ שבו וזהו שאו' תחלה ברוך אתה ה' כו' מלך העולם דהיינו קבלת מ\"ש שבכל מעשה המצוה שהוא מבחי' מל' דא\"ס ואח\"כ או' אשר קדשנו במצוותיו כו' וד\"ל.\n<b>והטעם</b> שהן ג' מקיפי' בכלל כי כללו' המצות הן מחולקי' לג' מדרגו' מחשבה דו\"מ מצות התלויו' במחשבה כמו מצות אוי\"ר שגם הן &lt;רנה&gt;\nתלויו' בכונה שבמחשבה וכמו מצות ק\"ש<sup data-n=\"3831\">29</sup> שתלוי' בכונת הלב כי אם לא כיון לבו לא יצא ויש מצות שתלויות",[["3825","23","<b>ובמצות תפילין. . מוחין לז\"א</b>: ראה פע\"ח שער התפילין. וראה ג\"כ תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] עח, ב. דרך מצותיך לד, ב. סה\"מ תרכ\"ז ע' מה. ע' רצה. ע' תכא. תרכ\"ט ע' ע. ע' צו. תרל\"ב ח\"א ע' קע."],["3826","24","<b>מצות צריכו' כוונה</b>: עירובין צה, סע\"ב."],["3827","25","<b>תחת אשר לא עבדת</b>: תבא כח, מז."],["3828","26","<b>לעבדו בכל לבבכם</b>: עקב יא, יג."],["3829","27","<b>עד\"מ. . לחטוב עצים</b>: ראה לקו\"ת כאן (שלח מ, א). המשך תרס\"ו ע' נד. ועוד. לקו\"ש חי\"א ע' 230 ואילך. חכ\"א ע' 17."],["3830","28","<b>המצות. . מצות המלך</b>: אסתר ג, ג. זח\"ג קעה, ב. לעיל ע' תקטו."],["3831","29","<b>ק\"ש. . לא כיון לבו לא יצא</b>: ראה שו\"ע אדה\"ז או\"ח סס\"ג."]]],[2100990145,"בדיבור<sup data-n=\"3832\">30</sup> כמו מצות ת\"ת וברכת המזון וכיוצא ושאר מצות הן בבחי' עשי' ממש ודרך כלל הן מקיפי' לבחי' נר\"ן שמלובשי' במחשבה דו\"מ והמקיפי' שורין דוקא על בחי' הלבושים דמחשבה דו\"מ כידוע ולהיו' כי שרש המצוה היא בבחי' עתיק וכתר שבג' מדרגו' בי\"ע שהן בחי' מחשבה דו\"מ ע\"כ נמשך על ידם ג' מקיפי' הללו בכלל וזהו ג\"כ שרש ענין אדון עוזינו שהוא בחי' מל' דא\"ס שנעשה בחי' עתיק בג' מדרגו' דנר\"נ דאצי' והן הנק' צור משגבינו מגן ומשגב כו' והכל ע\"י מצות מעשיות דוקא כי פי' אדון הוא שם א\"ד שהוא קבלת מ\"ש שבכל מצוה מפני שהוא אדון על כולא כמ\"ש שום<sup data-n=\"3833\">31</sup> תשים עליך מלך ומזה נעשה בחי' ג' מקיפי' כנ\"ל וד\"ל.\n<b>וזהו</b> תחת אשר לא עבדת ה' בשמחה כו' מרב כל. פי' שמחה של מצוה להיותה בבחי' הכתר שלמעלה מן החכמה ע\"כ היא למעלה גם מרב כל כי פי' כל הן בחי' נ' שערים דבינה ורב של כל הוא בחי' החכמה כי החכמה נק' מעיין והבינה<sup data-n=\"3834\">32</sup> נק' נהר וכמ\"ש ונהר<sup data-n=\"3835\">33</sup> יוצא מעדן וכמו עד\"מ ריבוי המשך הנהר שהוא בא רק מן המעיין כו'. וביאור שרש הדברי' הנה שרש התורה היא בבחי' חכמה סתימא' חכמה שבכתר כי אורייתא<sup data-n=\"3836\">34</sup> מחכמה נפקת ושרש המצות הם מבחי' כתר שבכתר כי הנה ידוע שהמצות<sup data-n=\"3837\">35</sup> נקראו ארחות הוי' והם תרי\"ג ארחין דמתפלגין מחד אורחא בפלגותא דשערי בגלגלתא כו' כמ\"ש באד\"ר ופי' ארחא היינו כמו עד\"מ הדרך והשביל שהוא מקום הפנוי מן העשבי' והתבואה כדי לילך בו כך עד\"מ האורחין הם בחי' מקום פנוי מן השערו' והם בחי' הלבנוניו' ונק' תליסר חוורתי כו' להיו' כי בחי' השערות הן בחי' המשכו' הרצון שמלובשי' כבר בבחי' ח\"ס שהוא ענין סתימות הטעם לרצון ונק' טעם כמוס שמשם נמשך שרש התורה דמה שהיא בחי' הפירוש על המצות היינו להביא הרצון בבחי' דין וצמצום שבזה האופן יהי' השראת וגילוי אור א\"ס ברצון זה ואם לאו לא יהי' גילוי אור א\"ס וכמו סוכה<sup data-n=\"3838\">36</sup> בצלתה מרובה מחמתה דוקא יהי' נמשך אור א\"ס ברצון שבמצות סוכה ואם חמתה מרובה מצלתה הסוכה פסולה ואינה מצוה כלל דהיינו שאין נמשך בה כלל גילוי אור הרצון מבחי' עצמו' אור א\"ס ועד\"ז בכל דקדוקי דיני המצו' כולם המה רק דיני' וצמצומי' ברצון העליון שיש בהם וכמו תפילין<sup data-n=\"3839\">37</sup> מרובעו' ובד' בתים דוקא ורצועו' שחורו' דוקא וא\"ל אינם מצוה ואין בהם בחי' הרצון כלל וכן בשאר מצו' כולן כמו בברכת כהנים בנשיא' כפים הרי יש בה דיני' שמעכבי' כל עיקר המצוה והכל מבחי' ח\"ס דא\"א",[["3832","30","<b>בדיבור. . ת\"ת</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב ה\"ב. מאמרי אדה\"א דברים ח\"א ע' רמ. ח\"ד ע' א'רג. וש\"נ."],["3833","31","<b>שום תשים עליך מלך</b>: דברים יז, טו."],["3834","32","<b>והבינה. . נהר</b>: ראה זהר (אדרא דמשכנתא) משפטים קכג, ב."],["3835","33","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["3836","34","<b>אורייתא מחכמה נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רעיא מהימנא משפטים קכא, א."],["3837","35","<b>שהמצות נק' ארחות ה'. . תרי\"ג ארחין דמתפלגין</b>: ראה זהר ח\"ג קלו, א. אוה\"ת בלק ע' א'יז."],["3838","36","<b>סוכה. . חמתה מרובה מצלתה. . פסולה</b>: ריש סוכה."],["3839","37","<b>תפילין מרובעות. . ורצועות שחורות</b>: ראה שו\"ע אדה\"ז או\"ח סל\"ב סעיף לט. וראה לקו\"ת שלח לט, ב."]]],[2100990146,"שנק' טעם כמוס לרצון ועפ\"י הטעם הכמוס הזה יהי' כל בחי' דין וצמצום ברצון שבמצות לעשו' כך ולא כך וכו' מפני שבו מלובש מבחי' גבורה דעתיק וד\"ל.\n<b>אבל</b> בחי' הארחין הם מקומו' פנויי' מבחי' השערות שהן הצמצומים שנמשכי' מח\"ס אלא הם כולם בחי' חסדי' ונק' בדרך כלל בחי' חסד דעתיק' כי הם רק ענין כללו' המשכה וירידה דוקא מגבוה לנמוך כטבע החסדי' כו' להיו' כי הם בחי' המשכו' אור א\"ס בכלל להיו' בבחי' גילוי אור למטה ע\"י הרצון שבמעשה &lt;רנו&gt;\nהמצו' כמאמר נתאוה<sup data-n=\"3840\">38</sup> הקדב\"ה להיו' לו דירה בתחתוני' כו' ונק'<sup data-n=\"3841\">39</sup> תליסר חוורתי כו' כי הם בחי' העונג הפנימי שברצון המלובש במצו' כענין נתאוה הקדב\"ה כו' והמצו' הן הכלים שבהן יהי' גילוי אורו למטה כו' וכמ\"ש במ\"א וע\"כ נק' שרש המצות שהן בחי' הארחין הנ\"ל בשם תר\"ך עמודים כי עד\"מ העמוד הגשמי שמחבר הגג עם קרקיעותו של בית והוא הממוצע בין היותר עליון להיותר תחתון ומחברם יחד כו' כך הוא בחי' גילוי אור א\"ס לירד מגבוה לנמוך עד למטה מטה באין בחי' דין וצמצום באופן הרצון איך ומה אלא אחר שמתלבש בח\"ס נעשה בבחי' דין וצמצום כנ\"ל וד\"ל.\n<b>ובזה</b> יובן שרש ענין עוטה אור כשלמה הנ\"ל משום דח\"ס דא\"א נק' אור והוא מעטה לבוש לבחי' העצמיו' של הרצון שהן בחי' ארחין הנ\"ל כי אור חסד שלהם מתלבש ומתצמצם ע\"י פירוש החכמה שבתורה על המצות כנ\"ל וד\"ל וזהו דשמחה של מצוה מצד עצמיו' הרצון כנ\"ל גדול גם מן בחי' רב כל שהוא בחי' ח\"ס הגם שהוא בחי' מקור למקור דנ' שערי' שנק' כל מקבלי' מחכמה וכתי' והחכמה מאין תמצא דהיינו מבחי' חכמה שבכתר כידוע להיות שהשרש האמיתי של המצות הוא בבחי' כתר שבכתר שנק' גלגלתא דא\"א ששם הם בחי' הארחין הנ\"ל וד\"ל.\n<b>ואחר</b> כל זה יובן שרש ענין ועתה יגדל נא כח א\"ד כו' ומתחלה יש לבאר שרש ענין הנ\"ל בפי' כאשר דברת לאמר כו' ומהו ענין המשל מכח זריקת האבן כו'. דהנה עיקר שרש ההפרש בין המצות לתורה הוא כמו שיש הפרש בין בחי' מוחא לבחי' גלגלתא כי שרש המצות בבחי' ארחין שבגלגלתא דא\"א כנ\"ל ושרש התורה בבחי' מוחא סתימא' דא\"א כנ\"ל וידוע שהרצון מתלבש בח\"ס והוא ענין הטעם הכמוס לרצון כנ\"ל א\"כ גילוי הרצון למטה בהכרח הוא בא ע\"י התורה דוקא שהוא בחי' ח\"ס וכמשל דיבורו של הרב שנעשה בחי' העלם לתלמיד המקבל כמבואר למעלה כך בחי' הדיבור בד\"ת מגלה בחי' רצון שבכתר למטה ונעשה ונמשך בבחי' העלם למטה והן י\"ג מדו' הרחמי' שנק' מדות והמדו' נמשכי' דרך החכמה דוקא כידוע וזהו שאמר כאשר דברת לאמר פי' מבחי' הדיבור דתורה ששרשה בבחי' ח\"ס נמשכי' י\"ג<sup data-n=\"3842\">40</sup> מדו' הנק' י\"ג תקוני' דהיינו ארך אפים ורב חסד",[["3840","38","<b>נתאוה הקב\"ה. . דירה בתחתונים</b>: ראה תניא רפל\"ו, ובליקוט פירושים לשם. ביאוה\"ז תזריע עב, ג. וראה מאמרי אדה\"א הנחות תקע\"ז ע' שכט."],["3841","39","<b>ונק' תליסר חוורתי</b>: ראה זהר (אדרא רבא) נשא קכח, ב."],["3842","40","<b>י\"ג מדות. . י\"ג תקוני'</b>: ראה לקו\"ת תזריע כד, ד. נשא כו, א. יהל אור ע' תרכו ואילך. ובכ\"מ."]]],[2100990147,"כו' והן מאירים בבחי' העלם למטה כידוע והיינו בבחי' אמירה בחשאי כי הנה מצד בחי' התחתונה שבעצמו' אור א\"ס שמאיר בכתר עליון הרי הוא מובדל ומרומם מכל בחי' מדה וספי' כמאמר לאו<sup data-n=\"3843\">41</sup> דאית לך צדק ידיעא כו' עד ולאו מכל אינון מדות כלל אך מפני התלבשו' הרצון בח\"ס דא\"א אזי בחי' גילוי הדיבור דח\"ס מביא לידי גילוי מבחי' הכתר להיו' נמשך בבחי' המדו' די\"ג מדה\"ר שיהי' נקרא אל<sup data-n=\"3844\">42</sup> רחום וחנון ארך אפים כו' ולפי שהתורה מביאה לידי גילוי בשכל וטעם כמוס עכ\"פ והרי משם נמשך עוד ומאיר בחכמה דאצי' שנק' אור אבא עד שמתפשטת החכמה הזאת גם בבחי' חכמה שבמל' דעשי' להיות נמצא מציאת שכל וטעם לרצון שבמצוה ע\"ד הנגלה או ע\"ד הנסתר לכל משכיל ומבין בחכמה שבתורה גם ששרש נפשו אינו אלא מי\"ס דעשי' בלבד &lt;רנז&gt;\nע\"כ נק' התורה מזון לנפש בבחי' א\"פ אחר שבאה לידי השגה ממש בנפש משא\"כ בחי' הרצון עצמו שמלובש במצוה א\"א לבא בנפש בבחי' א\"פ בהשגה אחר ששרשו למעלה גם מבחי' ח\"ס כנ\"ל אלא בא ושורה על הנפש בבחי' אור מקיף ע\"ד דוגמא מצות הסוכה בחי' החכמה שיש בה יכולה לבא בבחי' השגה כמו איך שצריך להיו' הסכך בהכשרו באופן שיוכשר להיו' בחי' א\"מ אבל ההשראה עצמה של הסכך בבחי' א\"מ זה אינו מושג בנפש וע\"כ כללות המצות נק' מקיפי' ולבושי' לנפש כנ\"ל וד\"ל.\n<b>וזהו</b> ועתה יגדל נא כח אד' כו' מה שנמשל לזריקת האבן בכח נבדל כו' כי הנה התורה<sup data-n=\"3845\">43</sup> נק' עוז וכח כמ\"ש תנו<sup data-n=\"3846\">44</sup> עוז לאלקים ואין עוז אלא תורה כו' ולכך נק'<sup data-n=\"3847\">45</sup> במשנה ג\"כ עוז ותושיה כו' לפי ששרשה בבחי' ח\"ס שנק' כח פי' כח מ\"ה להיותו שרש וכח המשכיל כו' וכמ\"ש במ\"א אמנם לגבי בחי' הכח של גלגלתא הוא קטן בערך כערך כח קטן שנכלל בכח הגדול באדם עד\"מ כח הזריקה של האבן שהיתה כלולה בכח העצמי של האדם כנ\"ל וכך נא' בכ\"ד<sup data-n=\"3848\">46</sup> ספרי' דאוריי' ותמלא כדה ותעל כו' כמו ששואבין בכד קטן מים מהגדול והכל ענין משל א' לפי שנא' והחכמה מאין תמצא פי' מאין דגלגלתא שהוא בחי' כתר שבכתר כנ\"ל אך הנה בחי' הכח של התורה לאחר שבא לידי גילוי בדיבור כנ\"ל בפי' כאשר דברת לאמר אזי נקרא כח נבדל שיצא לגילוי מן ההעלם דגלגלתא וכאשר אומר ועתה יגדל נא כח ר\"ל שיומשך הכח של התורה בבחי' תוספת עוז וכח להביא יותר מן ההעלם דכתר לידי גילוי ואזי ממילא יהיו נמשכים הארו' י\"ג מדה\"ר כנ\"ל וד\"ל.",[["3843","41","<b>לאו דאית לך צדק ידיעא</b>: ת\"ז בהקדמה (יז, א)."],["3844","42","<b>אל רחום וחנון</b>: תשא לד, ו."],["3845","43","<b>התורה נק' עוז. . ואין עוז אלא תורה</b>: ראה ויקרא רבה פל\"א, ה. ספרי ברכה לג, ב. יל\"ש בלשח רמז רמד. הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ ה'תשי\"א ע' 181."],["3846","44","<b>תנו עוז לאלקים</b>: תהלים סח, לה. ראה פע\"ח (שער התפלה) ש\"א פ\"ז."],["3847","45","<b>נק' במשנה ג\"כ עוז ותושיה</b>: ראה מכילתא דרשב\"י יתרו פי\"ט, טז. תו\"ח בשלח [הוצאת קה\"ת — תשס\"ג] קפד, א. רנא, א. לקו\"ת ויקרא ו, ב. מאמרי אדה\"א שמות ח\"ב ע' תקלו. ויקרא ח\"ב ע' תקעח. נ\"ך ע' רסח. דרושי חתונה ח\"ב ע' תפה, ובהנסמן בהנ\"ל."],["3848","46","<b>בכ\"ד ספרי' דאורייתא ותמלא כדה ותעל</b>: ראה תקו\"ז תכ\"א (מו, א). מאמרי אדה\"א שמות ח\"א ע' ק. וש\"נ."]]],[2100990148,"<b>אך</b> הנה אחר כל זה עדיין יש להבין למה הי\"ג מדה\"ר נק' בשם מקיפי' אחר שאין יורדים למטה אלא אחר צמצום החכמה שבתורה כנ\"ל בפי' כאשר דברת לאמר כו'. אבל הענין יובן בהקדים תחלה מה שמבואר בכוונו' התפלה שבברוך שאמר הכונה הוא בבחי' א\"א דבריאה כו' וגם שם נמשך י\"ג תיקוני' מא\"א דבריא' בעולם הבריא' והן ענין י\"ג תיבו' שיר ושבחה וכו' שבסוף ברכת ישתבח כו' ולכאורה זה יפלא מאד דבשלמא אחר ש\"ע אומרי' ויעבור כו' כי בש\"ע הוא בבחי' אצי' ע\"כ יתכן להמשיך יגת\"ד מלפני האצי' אחר ש\"ע אבל בב\"ש שעדיין אין ההארה שם רק בבחי' היצירה בלבד כידוע בענין ד' תקוני' דשכינתא אצי' בש\"ע וכו' אך הענין הוא להיות הכלל ידוע דכל מקום דמבחי' מלכו' שבעליון דוקא נעשה בחי' עתיק וכתר לתחתון כמו בחי' מל' דאצי' נעשה בחי' עתיק לבריא' וכך הוא עד רום המעלו' ועתיק וא\"א המה במדרגה א' אלא שא\"א הוא בחי' גילוי הרצון להאיר למטה ובחי' עתיק מובדל כו' וע\"כ גם בבחי' מל' דאצי' שנעשה כתר לבריא' יש ב' מדרגו' הא' בחי' ע\"י שהוא מובדל והב' בחי' א\"א דבריא' שממנו יאיר י\"ג מדה\"ר בעולם הבריאה שהוא בחי' הגילוי של הרצון לבריא' כי בחי' הרצון לבריא' נק' כתר דבריא' כמו בחי' הרצון להאציל נק' כתר דאצי' וכמ\"ש כל<sup data-n=\"3849\">47</sup> אשר חפץ ה' עשה וכן כל אשר חפץ יצר וברא והאציל כו' ובכולם נק' הרצון בחי' הכתר אלא שבאצי' נק' א\"א דאצי' ובבריא' נק' א\"א דבריא' וביצי' ועשי' נק' א\"א &lt;רנח&gt;\nדיצי' כו' וי\"ג תקוני' כמו שנמשך מבחי' א\"א דאצי' באצי' כך נמשך מא\"א דבריא' בבריא' (וכמ\"ש במ\"א<sup data-n=\"3850\">48</sup> ע\"פ וחסידיך יברכוכה יברכו כ\"ה שלהאיר בעולם הבריא' י\"ג מדה\"ר כו' שוה במדרגה א' קמי' עצמו' המאציל כמו שיאיר י\"ג מדה\"ר באצי' אחר שאצי' ועשי' שוין שם קודם שעלה ברצונו להאציל כו') ואמנם בבחי' מל' דאצי' קודם שנעשה בחי' עתיק וכתר לבריא' עדיין מובדל שם מבחי' הארו' השפע בי\"ג מדו' בעולם הבריא' אלא דוקא אחר שנעשה המלכו' בחי' כתר אזי יאיר כו' וד\"ל.\n<b>וזהו</b> ענין י\"ג מדה\"ר שמאירי' בעולם הבריא' מבחי' א\"א דבריא' בק\"ש בסוף ברכתה בי\"ג תיבו' דשיר ושבחה כו' ואח\"כ אחר ש\"ע מאיר מלפני האצי' באצי' י\"ג מדה\"ר אלא שהארת י\"ג מדו' דע\"י וא\"א דאצי' באי' ממקום יותר גבוה והיינו מבחי' מלכו' דא\"ק כי ידוע דבחי' מלכו' דא\"ק נעשה בחי' ע\"י וא\"א לאצי' ע\"ד שמל' דאצי' נעשה בחי' ע\"י לבריאה ממש וד\"ל ובכל זה יתורץ הקושיא הלז מה שי\"ג מדה\"ר נק' מקיפי' אע\"פ שיורדי' אחר צמצום החכמה כי הנה הי\"ג מדה\"ר נמשכי' בכל מקום מבחי' עתיק וא\"א והוא בחי' הכתר שנק' מקיף בכלל אלא שא\"א שירדו אלא ע\"י צמצום בחי' החכמה שבכתר והוא בחי' דיבור שבמל' דעליון שנעשה בחי' העלם למטה כנ\"ל כי בחי' מל' דעליון מתלבש בח\"ס דכתר שלמטה בבחי' הדיבור דשם ומשם בוקעי' הארת הי\"ג מדה\"ר כנ\"ל ונקראו בשם מקיפי' למטה מפני שהם מבחי' הכתר כי שרשם מבחי' ח\"ס שגם הוא בודאי נחשב בכלל בחי' הכתר כו' וד\"ל.",[["3849","47","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["3850","48","<b>במ\"א ע\"פ וחסידך יברכוכה</b>: ראה ג\"כ פירוש המלות סו, א. קט, ד."]]]]});
